window.EXPL={"공인노2017_26-32-2":{"f":"노동조합이 설립신고증을 교부받은 경우에는 설립신고서가 접수된 때에 노동조합이 성립된 것으로 본다.","w":"3일 안에 반려나 보완지시가 없으면 성립한 것으로 보는 규정은 없다. 신고증을 교부받아야 하고, 교부받으면 설립신고서가 접수된 때로 거슬러 설립된 것으로 본다(노조법 제12조 제4항).","c":"상","v":1},"공인노2017_26-32-3":{"f":"노동조합설립신고서의 보완을 요구하거나 그 신고서를 반려하는 경우에는 노동위원회의 의결을 거칠 필요가 없다.","w":"설립신고서 보완요구와 반려는 행정관청이 혼자 한다. 노동위원회 의결이 필요한 것은 규약·결의 시정명령, 휴면노조 해산 같은 경우다.","c":"상","v":1},"공인노2017_26-32-4":{"f":"노동조합의 회의록, 재정에 관한 장부와 서류는 3년간 보존하여야 한다.","w":"회의록과 재정에 관한 장부·서류의 보존기간은 3년이다(노조법 제14조 제2항).","c":"상","v":1},"공인노2017_26-32-5":{"f":"노동조합에의 참가가 금지되는 자인지 여부는 일정한 직급이나 직책에 의하여 일률적으로 결정되는 것이 아니라 그 업무의 내용에 따라 실질적으로 결정된다.","w":"판례는 직급·직책만 보지 않고, 맡은 업무가 사용자의 이익을 대표하는 것인지 단순 보조·조언에 그치는지를 따져 실질적으로 판단한다.","c":"상","v":1},"공인노2019_28-28-3":{"f":"노동위원회의 부당노동행위 구제명령을 이행할 수 있는 법률적 또는 사실적인 권한이나 능력을 가지는 지위에 있다면 직접고용관계에 있지 않더라도 그 한도 내에서 사용자에 해당한다.","w":"판례는 직접 근로계약을 맺지 않았어도 구제명령을 이행할 권한이나 능력이 있으면 그 범위에서 부당노동행위 주체인 사용자로 본다. 2025년 개정 노조법은 근로조건을 실질적·구체적으로 지배·결정하는 자를 그 범위에서 사용자로 보도록 명문화했다.","c":"상","v":1},"공인노2025_34-58-3":{"f":"노동조합에 대하여는 그 사업체를 제외하고는 세법이 정하는 바에 따라 조세를 부과하지 아니한다.","w":"비과세 대상은 노동조합이고, 노동조합이 운영하는 사업체에는 세금이 부과된다(노조법 제8조).","c":"상","v":1},"공인노2026_35-49-3":{"f":"총회가 규약의 제ㆍ개정결의를 통하여 총회에 갈음할 대의원회를 두고 ‘규약의 개정에 관한 사항’을 대의원회의 의결사항으로 정한 경우에도 총회의 규약개정권한은 소멸되지 않는다.","w":"판례는 대의원회에 규약개정 권한을 준 뒤에도 총회가 최고의결기관으로서 규약을 개정할 권한은 그대로 남는다고 본다.","c":"상","v":1},"공인노2017_26-41-2":{"f":"노동조합 전임자 급여 지원 행위는 노동조합의 자주성을 저해할 위험성이 있는지를 따지지 않고 그 자체로 부당노동행위가 된다.","w":"(2021 개정 전 기준 X. 현행은 전임자 급여 지원 금지 조항이 없어졌고, 근로시간 면제 한도를 넘는 급여 지급을 부당노동행위로 정한다(노조법 제81조 제1항 제4호).) 개정 전 노조법 제81조 제4호는 전임자 급여 지원을 그 자체로 부당노동행위로 정해 자주성 저해 위험을 따로 따지지 않았다.","c":"중","v":1,"old":1,"ow":"(2021 개정 전 기준 X. 현행은 전임자 급여 지원 금지 조항이 없어졌고, 근로시간 면제 한도를 넘는 급여 지급을 부당노동행위로 정한다(노조법 제81조 제1항 제4호).) 개정 전 노조법 제81조 제4호는 전임자 급여 지원을 그 자체로 부당노동행위로 정해 자주성 저해 위험을 따로 따지지 않았다."},"공인노2019_28-31-3":{"f":"근로시간 면제자에 대한 급여는 사회통념상 수긍할 만한 합리적인 범위를 초과할 정도로 과다하지 않다면 근로의 대가로 보아야 한다.","w":"판례는 근로시간 면제자가 받는 급여를 근로의 대가인 임금으로 본다. 합리적 범위를 넘을 만큼 과다한 부분만 근로의 대가가 아니게 된다.","c":"상","v":1},"공인노2019_28-33-3":{"f":"노동조합 활동은 취업규칙이나 단체협약에 별도의 허용규정이 있으면 취업시간 중에도 할 수 있다.","w":"노동조합 활동은 원칙적으로 취업시간 밖에서 해야 하지만, 취업규칙·단체협약의 허용규정이나 관행, 사용자의 승낙이 있으면 취업시간 중에도 정당하다는 것이 판례다.","c":"상","v":1},"공인노2022_31-28-5":{"f":"종사근로자인 조합원이 해고되어 노동위원회에 부당노동행위의 구제신청을 한 경우에는 중앙노동위원회의 재심판정이 있을 때까지는 종사근로자로 본다.","w":"종사근로자 지위를 유지해 주는 것은 부당노동행위 구제신청을 한 경우다. 부당해고 구제신청만으로는 이 규정이 적용되지 않는다(노조법 제5조 제3항).","c":"상","v":1},"공인노2022_31-30-4":{"f":"근로시간면제자에 대한 근로시간 면제 한도를 정하기 위하여 근로시간면제심의위원회를 경제사회노동위원회에 둔다.","w":"2021년 개정으로 근로시간면제심의위원회는 고용노동부에서 경제사회노동위원회로 옮겨졌다(노조법 제24조의2 제1항).","c":"상","v":1},"공인노2024_33-44-1":{"f":"노동조합의 규약에는 목적과 사업을 기재해야 한다.","w":"목적과 사업은 규약 기재사항이다(제11조). 설립신고서에는 명칭, 주된 사무소 소재지, 조합원수, 임원의 성명·주소, 소속 연합단체 명칭 등을 적는다(제10조).","c":"상","v":1},"공인노2024_33-45-1":{"f":"노동조합은 회의록을 3년간 보존하여야 한다.","w":"3년 보존 의무가 있는 서류는 회의록과 재정에 관한 장부·서류뿐이다. 조합원 명부는 비치 의무만 있고 보존기간은 정해져 있지 않다(노조법 제14조).","c":"상","v":1},"공인노2024_33-45-2":{"f":"예산ㆍ결산에 관한 사항은 총회에서 재적조합원 과반수의 출석과 출석조합원 과반수의 찬성으로 의결한다.","w":"예산·결산은 일반 의결정족수(재적 과반수 출석, 출석 과반수 찬성)로 정한다. 출석 3분의 2 이상 찬성이 필요한 것은 규약 제정·변경, 임원 해임, 합병·분할·해산, 조직형태 변경이다(제16조 제2항).","c":"상","v":1},"공인노2024_33-45-4":{"f":"노동조합의 대표자는 대의원의 3분의 1 이상이 회의에 부의할 사항을 제시하고 회의의 소집을 요구한 때에는 지체없이 임시대의원회를 소집하여야 한다.","w":"조합원이나 대의원 3분의 1 이상이 소집을 요구하면 대표자는 지체 없이 임시총회나 임시대의원회를 소집해야 한다(제18조 제2항). 15일은 행정관청이 소집권자를 지명하는 기한이다.","c":"상","v":1},"공인노2024_33-45-5":{"f":"행정관청은 노동조합에 총회의 소집권자가 없는 경우에 조합원의 3분의 1 이상이 회의에 부의할 사항을 제시하고 소집권자의 지명을 요구한 때에는 15일 이내에 회의의 소집권자를 지명하여야 한다.","w":"소집권자가 없을 때 행정관청은 요구를 받은 뒤 15일 이내에 소집권자를 지명한다(제18조 제4항).","c":"상","v":1},"공인노2024_33-46-1":{"f":"근로시간면제심의위원회는 근로시간 면제 한도를 심의ㆍ의결하고, 3년마다 그 적정성 여부를 재심의하여 의결할 수 있다.","w":"3년마다 재심의는 의무가 아니라 재량이다(노조법 제24조의2 제2항).","c":"상","v":1},"공인노2024_33-46-2":{"f":"경제사회노동위원회 위원장은 근로시간면제심의위원회가 의결한 사항을 고용노동부장관에게 즉시 통보하여야 한다.","w":"위원회 의결 사항을 고용노동부장관에게 통보하는 사람은 경제사회노동위원회 위원장이다(노조법 제24조의2 제3항).","c":"상","v":1},"공인노2024_33-46-3":{"f":"근로시간면제심의위원회 위원의 임기는 2년으로 한다.","w":"근로시간면제심의위원회 위원의 임기는 2년이고, 임기가 끝나도 후임자가 위촉될 때까지 직무를 계속한다(노조법 시행령 제11조의5 제1항·제3항).","c":"상","v":1},"공인노2024_33-46-5":{"f":"근로시간면제심의위원회는 경제사회노동위원회 위원장으로부터 근로시간 면제 한도를 정하기 위한 심의 요청을 받은 때에는 그 심의 요청을 받은 날부터 60일 이내에 심의ㆍ의결해야 한다.","w":"심의 기한은 요청을 받은 날부터 60일이다(노조법 시행령 제11조의6 제1항).","c":"상","v":1},"공인노2024_33-47-3":{"f":"노동조합의 대표자는 그 회계감사원으로 하여금 6월에 1회 이상 당해 노동조합의 모든 재원 및 용도, 주요한 기부자의 성명, 현재의 경리 상황등에 대한 회계감사를 실시하게 하고 그 내용과 감사결과를 전체 조합원에게 공개하여야 한다.","w":"회계감사 주기는 6개월에 1회 이상이다(노조법 제25조 제1항). 회계연도마다 하는 것은 결산결과와 운영상황 공표다.","c":"상","v":1},"공인노2025_34-44-1":{"f":"연합단체인 노동조합을 설립하고자 하는 자는 신고서에 규약을 첨부하여 고용노동부장관에게 제출하여야 한다.","w":"연합단체와 둘 이상의 시·도에 걸치는 단위노동조합은 고용노동부장관에게 신고한다. 시·도지사에게 내는 것은 하나의 시·도 안의 여러 시·군·구에 걸치는 단위노동조합이다(제10조 제1항).","c":"상","v":1},"공인노2025_34-47-2":{"f":"대의원회를 둔 때에는 총회에 관한 규정은 대의원회에 이를 준용한다.","w":"대의원회를 둔 때에는 총회에 관한 규정이 대의원회에 준용된다(노조법 제17조 제5항).","c":"상","v":1},"공인노2025_34-47-3":{"f":"노동조합은 회의록 및 재정에 관한 장부와 서류를 작성하여 3년간 보존하여야 한다.","w":"보존기간은 3년이다(노조법 제14조 제2항).","c":"상","v":1},"공인노2025_34-47-4":{"f":"행정관청은 노동위원회의 의결 없이 노동조합의 결산결과와 운영상황 보고를 요구할 수 있다.","w":"결산결과·운영상황 보고 요구에는 노동위원회 의결이 필요 없다. 행정관청이 사유를 적은 서면으로 10일 전에 요구하면 된다(노조법 제27조, 시행령 제12조).","c":"상","v":1},"공인노2025_34-47-5":{"f":"노동조합의 대표자는 그 회계감사원으로 하여금 6월에 1회 이상 회계감사를 실시하게하여야 한다.","w":"회계감사는 6개월에 1회 이상 해야 한다(노조법 제25조 제1항).","c":"상","v":1},"공인노2025_34-50-5":{"f":"산업별 노동조합의 지회 등이 독자적으로 단체교섭을 진행하고 단체협약을 체결하지 못하였더라도 법인 아닌 사단의 실질을 가지고 있어 기업별 노동조합과 유사한 근로자 단체로서 독립성이 인정된다면 그 지회 등은 스스로 고유한 사항에 관하여 산업별 노동조합과 독립하여 의사를 결정할 수 있는 능력을 가지고 있다.","w":"2016년 대법원 전원합의체 판결은 독자적 교섭·협약 체결 경험이 없어도 법인 아닌 사단의 실질과 독립성이 있으면 지회가 스스로 의사를 결정할 수 있고, 조직형태 변경 결의로 기업별 노조로 전환할 수 있다고 했다.","c":"상","v":1},"공인노2025_34-68-1":{"f":"위원회는 근로시간 면제 한도를 심의·의결하고, 3년마다 그 적정성 여부를 재심의하여 의결할 수 있다.","w":"재심의 주기는 3년이다(노조법 제24조의2 제2항).","c":"상","v":1},"공인노2025_34-68-3":{"f":"위원회는 경제사회노동위원회 위원장으로부터 근로시간 면제 한도를 정하기 위한 심의요청을 받은 때에는 그 심의 요청을 받은 날부터 60일 이내에 심의·의결해야 한다.","w":"위원회가 경제사회노동위원회로 옮겨진 뒤 심의 요청은 경제사회노동위원회 위원장이 하고, 심의 기한은 요청을 받은 날부터 60일이다(노조법 시행령 제11조의6 제1항).","c":"상","v":1},"공인노2025_34-68-4":{"f":"위원회는 재적위원 과반수의 출석과 출석위원 과반수의 찬성으로 의결한다.","w":"의결정족수는 재적위원 과반수 출석, 출석위원 과반수 찬성이다(노조법 제24조의2 제7항).","c":"상","v":1},"공인노2025_34-68-5":{"f":"위원회 위원의 임기는 2년으로 하고, 임기가 끝났더라도 후임자가 위촉될 때까지 계속하여 그 직무를 수행한다.","w":"근로시간면제심의위원회 위원의 임기는 2년이다(노조법 시행령 제11조의5 제1항).","c":"상","v":1},"공인노2026_35-42-5":{"f":"총회의 의결사항 중 임원의 선거에 관한 사항은 조합원의 직접ㆍ비밀ㆍ무기명투표에 의하여야 한다.","w":"직접·비밀·무기명투표가 필요한 것은 규약의 제정·변경과 임원의 선거·해임이다(노조법 제16조 제4항). 조직형태 변경은 출석 3분의 2 이상 찬성이 필요할 뿐 투표 방식 규정은 없다.","c":"상","v":1},"공인노2026_35-43-1":{"f":"총회에서 임원의 선거는 출석조합원 과반수의 찬성을 얻은 자를 임원으로 선출하여야 한다.","w":"임원 선거는 출석조합원 과반수 찬성이 원칙이다. 과반수 득표자가 없을 때만 규약에 따라 결선투표를 해서 다수 득표자를 뽑을 수 있다(노조법 제16조 제3항).","c":"상","v":1},"공인노2026_35-43-2":{"f":"노동조합의 대표자는 규약으로 총회에 갈음할 대의원회를 둔 경우 임시대의원회를 소집할 수 있다.","w":"대표자는 필요하다고 인정하면 임시총회나 임시대의원회를 소집할 수 있다(노조법 제18조 제1항).","c":"상","v":1},"공인노2026_35-43-3":{"f":"행정관청은 노동조합의 대표자가 회의의 소집을 고의로 기피하거나 이를 해태하여 조합원의 3분의 1 이상이 임시총회 소집권자의 지명을 요구한 때에는 15일 이내에 노동위원회의 의결을 요청하여야 한다.","w":"노동위원회 의결을 요청하는 주체는 행정관청이다. 대표자가 소집을 기피·해태할 때 조합원 3분의 1 이상이 요구하면 행정관청이 15일 이내에 의결을 요청하고, 의결이 나면 지체 없이 소집권자를 지명한다(제18조 제3항).","c":"상","v":1},"공인노2026_35-43-5":{"f":"총회는 회의개최일 7일전까지 그 회의에 부의할 사항을 공고하고 규약에 정한 방법에 의하여 소집하여야 하며, 대의원회는 노동조합이 동일한 사업장내의 근로자로 구성된 경우에는 그 규약으로 공고기간을 단축할 수 있다.","w":"같은 사업장 근로자로 구성된 노동조합은 규약으로 7일 공고기간을 줄일 수 있다(노조법 제19조 단서).","c":"상","v":1},"공인노2026_35-44-1":{"f":"노동조합의 대표자는 대의원 3분의 1 이상의 요구가 있는 경우에는 조합원이 아닌 공인회계사로 하여금 회계감사를 실시하게 할 수 있다.","w":"대의원 3분의 1 이상이 요구하면 노동조합의 대표자가 조합원 아닌 공인회계사나 회계법인에 회계감사를 맡길 수 있다. 맡기는 사람은 회계감사원이 아니라 대표자이고, 의무가 아니라 재량이다(노조법 시행령 제11조의7 제2항 제4호).","c":"상","v":1},"공인노2026_35-45-1":{"f":"하나의 사업 또는 사업장을 대상으로 조직된 노동조합의 임원은 그 사업 또는 사업장에 종사하는 조합원 중에서 선출하도록 규약으로 정하여야 한다.","w":"임원 자격은 규약으로 정하되, 기업 단위 노동조합의 임원은 그 사업장에 종사하는 조합원 중에서 선출하도록 정해야 한다(노조법 제23조 제1항).","c":"상","v":1},"공인노2026_35-45-2":{"f":"행정관청(고용노동부장관은 제외한다)은 매년 2월 말까지 노동단체카드 사본을 고용노동부장관에게 제출해야 한다.","w":"노동단체카드 사본은 노동위원회가 아니라 고용노동부장관에게 매년 2월 말까지 제출한다(노조법 시행규칙 제7조 제2항).","c":"상","v":1},"공인노2026_35-45-4":{"f":"근로시간면제심의위원회에 간사 1명을 두며, 간사는 경제사회노동위원회의 소속 직원 중에서 경제사회노동위원회 위원장이 지명한다.","w":"근로시간면제심의위원회가 경제사회노동위원회에 있으므로 간사도 경제사회노동위원회 소속 직원 중에서 그 위원장이 지명한다(노조법 시행령 제11조의6 제2항).","c":"상","v":1},"공인노2026_35-45-5":{"f":"근로시간면제심의위원회는 근로시간 면제 한도를 정할 때 사업 또는 사업장에 종사하는 근로자인 조합원 수와 해당 업무의 범위 등을 고려하여 시간과 이를 사용할 수 있는 인원으로 정할 수 있다.","w":"면제 한도의 기준은 전체 근로자 수가 아니라 그 사업장에 종사하는 근로자인 조합원 수다. 시간과 사용 인원으로 정하는 것도 재량 규정이다(노조법 시행령 제11조의2).","c":"상","v":1},"공인노2026_35-47-2":{"f":"근로시간면제심의위원회는 근로시간 면제 한도를 3년마다 그 적정성 여부를 재심의하여 의결할 수 있다.","w":"재심의 주기는 3년이고, 재심의는 할 수 있는 것이지 의무가 아니다(노조법 제24조의2 제2항).","c":"상","v":1},"공인노2026_35-48-1":{"f":"행정관청은 규약이 기재사항의 누락등으로 보완이 필요한 경우에는 대통령령이 정하는 바에 따라 20일 이내의 기간을 정하여 보완을 요구하여야 하며, 보완된 규약을 접수한 때에는 3일 이내에 신고증을 교부하여야 한다.","w":"보완된 설립신고서나 규약을 받으면 3일 이내에 신고증을 교부해야 한다(노조법 제12조 제2항).","c":"상","v":1},"공인노2026_35-48-3":{"f":"노동조합이 설립신고증을 교부받은 후 주로 정치운동을 목적으로 하는 경우에 해당하는 설립신고서의 반려사유가 발생한 경우에는 행정관청은 30일의 기간을 정하여 시정을 요구할 수 있다.","w":"신고증 교부 뒤 반려사유가 생기면 행정관청은 30일의 기간을 정해 시정을 요구할 수 있다(노조법 시행령 제9조 제2항). 20일은 설립신고서·규약의 보완요구 기간이다.","c":"상","v":1},"공인노2026_35-48-4":{"f":"노동조합이 행정관청에 전년도 12월 31일 현재의 조합원수를 통보할 때 둘 이상의 사업 또는 사업장의 근로자로 구성된 단위노동조합의 경우에는 사업 또는 사업장별로 구분하여 조합원수를 통보해야 한다.","w":"둘 이상의 사업장 근로자로 구성된 단위노동조합은 조합원수를 사업장별로 나누어 통보해야 한다(노조법 시행령 제10조 제4항).","c":"상","v":1},"공인노2026_35-48-5":{"f":"산업별 연합단체인 노동조합은 해당 노동조합에 가입한 노동조합의 활동에 대해 지도할 수 있다.","w":"산업별 연합단체와 총연합단체는 가입한 노동조합의 활동에 대해 협조·지원 또는 지도할 수 있다(노조법 시행령 제8조 제2항).","c":"상","v":1},"공인노2017_26-37-5":{"f":"산업별 노동조합의 지회가 노동조합 유사의 독립한 근로자단체로서 법인 아닌 사단에 해당하는 경우, 조직형태 변경 결의를 통하여 기업별 노동조합으로 전환할 수 있다.","w":"2016년 대법원 전원합의체 판결은 독립성 있는 지회가 조직형태 변경 결의로 기업별 노동조합으로 전환할 수 있다고 했다.","c":"상","v":1},"공인노2019_28-32-4":{"f":"노동조합 총회에서 재적조합원 과반수의 출석과 출석조합원 3분의 2 이상의 찬성으로 노동조합 해산결의가 있는 경우에 노동조합은 해산한다.","w":"해산결의는 특별의결사항이라 출석조합원 3분의 2 이상 찬성이 필요하다(노조법 제16조 제2항).","c":"상","v":1},"공인노2024_33-48-5":{"f":"노동조합의 해산사유가 있는 경우, 노동위원회가 의결을 할 때에는 해산사유 발생일 이후의 해당 노동조합의 활동을 고려해서는 아니 된다.","w":"휴면노조 해산 의결 때 노동위원회는 해산사유 발생일 이후의 활동을 고려해서는 안 된다(노조법 시행령 제13조 제3항).","c":"상","v":1},"공인노2025_34-43-4":{"f":"종사근로자가 아닌 노동조합의 조합원은 하나의 사업 또는 사업장을 대상으로 조직된 노동조합의 임원이 될 수 없다.","w":"기업 단위 노동조합의 임원은 그 사업장에 종사하는 조합원 중에서 선출하도록 규약으로 정해야 하므로, 종사근로자 아닌 조합원은 임원이 될 수 없다(노조법 제23조 제1항).","c":"상","v":1},"공인노2025_34-45-3":{"f":"규약에서 정한 해산사유가 발생하여 노동조합이 해산한 때에는 그 해산사유가 발생한 때에 해산된 것으로 본다.","w":"규약상 해산사유가 생기면 그때 해산하고, 대표자는 해산한 날부터 15일 이내에 신고할 뿐이다. 신고는 해산의 요건이 아니다(노조법 제28조).","c":"상","v":1},"공인노2017_26-34-3":{"f":"교섭대표노동조합이 결정된 날부터 1년 동안 단체협약을 체결하지 못한 경우에는 어느 노동조합이든지 사용자에게 교섭을 요구할 수 있다.","w":"결정된 날부터 1년 안에 단체협약을 맺지 못하면 교섭대표노동조합의 지위가 풀려 어느 노동조합이든 교섭을 요구할 수 있다(노조법 시행령 제14조의10 제3항).","c":"상","v":1},"공인노2019_28-34-2":{"f":"단위노동조합이 당해 노동조합이 가입한 상부단체인 연합단체에 단체교섭권한을 위임한 경우에도 단위노동조합의 단체교섭권한은 소멸하지 않는다.","w":"판례는 교섭권한을 위임해도 단위노동조합의 권한은 없어지지 않고 수임자의 권한과 중복하여 남는다고 본다.","c":"상","v":1},"공인노2019_28-35-2":{"f":"노동조합은 교섭대표노동조합이 공정대표의무를 위반하여 차별한 경우에는 그 행위가 있은 날부터 3개월 이내에 노동위원회에 그 시정을 요청할 수 있다.","w":"공정대표의무 위반 시정 요청 기간은 그 행위가 있은 날부터 3개월이다. 단체협약 내용이 차별이면 단체협약 체결일부터 센다(노조법 제29조의4 제2항).","c":"상","v":1},"공인노2019_28-36-1":{"f":"하나의 사업 또는 사업장 단위에서 유일하게 존재하는 노동조합은 교섭창구 단일화 절차를 형식적으로 거쳤더라도 교섭대표노동조합의 지위를 취득할 수 없다.","w":"판례는 복수노조가 없는 사업장의 유일 노조는 절차를 형식적으로 밟았더라도 교섭대표노동조합이 될 수 없다고 본다. 창구 단일화는 노조가 둘 이상일 때의 제도다.","c":"상","v":1},"공인노2019_28-36-2":{"f":"교섭창구 단일화 절차에 따라 결정된 교섭대표노동조합이 그 결정된 날부터 1년 동안 단체협약을 체결하지 못한 경우에는 어느 노동조합이든지 사용자에게 교섭을 요구할 수 있다.","w":"기간은 6개월이 아니라 1년이다(노조법 시행령 제14조의10 제3항).","c":"상","v":1},"공인노2019_28-36-3":{"f":"하나의 사업 또는 사업장에서 교섭단위를 분리할 필요가 있다고 인정되는 경우에 노동위원회는 노동관계 당사자의 양쪽 또는 어느 한쪽의 신청을 받아 교섭단위를 분리하는 결정을 할 수 있다.","w":"교섭단위 분리는 노동위원회의 결정으로만 한다. 노사가 합의만으로 교섭단위를 나누는 규정은 없다(노조법 제29조의3 제2항).","c":"상","v":1},"공인노2019_28-36-4":{"f":"공동교섭대표단에 참여할 수 있는 노동조합은 그 조합원 수가 교섭창구 단일화 절차에 참여한 노동조합의 전체 조합원 100분의 10 이상인 노동조합으로 한다.","w":"공동교섭대표단 참여 기준은 전체 조합원의 100분의 10 이상이다(노조법 제29조의2 제5항).","c":"상","v":1},"공인노2022_31-31-4":{"f":"노동조합은 해당 사업에 단체협약이 2개 이상 있는 경우에는 먼저 이르는 단체협약의 유효기간 만료일 이전 3개월이 되는 날부터 사용자에게 교섭을 요구할 수 있다.","w":"단체협약이 둘 이상이면 먼저 만료되는 협약을 기준으로 만료일 3개월 전부터 교섭을 요구할 수 있다(노조법 시행령 제14조의2 제1항).","c":"상","v":1},"공인노2022_31-32-3":{"f":"교섭대표노동조합을 자율적으로 결정하는 기한까지 교섭대표노동조합을 정하지 못하고 사용자의 동의를 얻지 못한 경우에는 교섭창구 단일화 절차에 참여한 노동조합의 종사근로자인 조합원 과반수로 조직된 노동조합이 교섭대표노동조합이 된다.","w":"과반수 노동조합을 따질 때는 종사근로자인 조합원만 센다. 해고자 등 종사근로자가 아닌 조합원은 빠진다(노조법 제29조의2 제4항·제10항).","c":"상","v":1},"공인노2022_31-33-1":{"f":"노동조합 또는 사용자는 사용자가 교섭요구 사실을 공고하기 전에는 노동위원회에 교섭단위를 분리하는 결정을 신청할 수 있다.","w":"교섭단위 분리 신청은 사용자가 교섭요구 사실을 공고하기 전이나, 공고한 경우에는 교섭대표노동조합이 결정된 날 이후에 할 수 있다(노조법 시행령 제14조의11 제1항).","c":"상","v":1},"공인노2022_31-33-2":{"f":"노동조합 또는 사용자는 분리된 교섭단위를 통합하여 교섭하려는 경우에는 노동위원회에 분리된 교섭단위를 통합하는 결정을 신청할 수 있다.","w":"2021년 개정으로 분리된 교섭단위를 통합하는 결정도 신청할 수 있게 되었다(노조법 제29조의3 제2항).","c":"상","v":1},"공인노2022_31-33-3":{"f":"노동위원회는 노동관계 당사자의 어느 한쪽이 신청한 경우에도 교섭단위를 분리하는 결정을 할 수 있다.","w":"노동위원회는 노사 양쪽 또는 어느 한쪽의 신청을 받아 교섭단위 분리 결정을 할 수 있다(노조법 제29조의3 제2항).","c":"상","v":1},"공인노2022_31-33-5":{"f":"교섭단위 분리신청에 대한 노동위원회의 결정이 있기 전에 교섭 요구가 있는 때에는 교섭단위를 분리하는 결정이 있을 때까지 교섭요구 사실의 공고 등 교섭창구단일화절차의 진행은 정지된다.","w":"분리 결정이 나올 때까지 교섭요구 사실의 공고 등 창구 단일화 절차는 멈춘다(노조법 시행령 제14조의11 제7항).","c":"상","v":1},"공인노2024_33-49-1":{"f":"노동조합 또는 사용자는 사용자가 교섭요구 사실을 공고하기 전에는 노동위원회에 교섭단위를 분리하는 결정을 신청할 수 있다.","w":"공고 전에도 신청할 수 있다. 공고한 뒤라면 교섭대표노동조합이 결정된 날 이후에 신청한다(노조법 시행령 제14조의11 제1항).","c":"상","v":1},"공인노2024_33-54-5":{"f":"교섭대표노동조합이나 사용자가 교섭창구 단일화 절차에 참여한 다른 노동조합을 차별한 것으로 인정되는 경우, 그와 같은 차별에 합리적인 이유가 있다는 점에 대하여 교섭대표노동조합이나 사용자에게 주장ㆍ증명책임이 있다.","w":"판례는 차별에 합리적 이유가 있다는 점의 주장·증명책임을 교섭대표노동조합이나 사용자에게 지운다.","c":"상","v":1},"공인노2024_33-55-4":{"f":"교섭대표노동조합의 지위 유지기간이 만료되었음에도 불구하고 새로운 교섭대표노동조합이 결정되지 못할 경우 기존 교섭대표노동조합은 새로운 교섭대표노동조합이 결정될 때까지 기존 단체협약의 이행과 관련해서는 교섭대표노동조합의 지위를 유지한다.","w":"지위가 연장되는 범위는 기존 단체협약의 이행에 관한 것뿐이다. 새 협약을 위한 갱신 교섭 권한까지 유지되지는 않는다(노조법 시행령 제14조의10 제2항).","c":"상","v":1},"공인노2025_34-52-2":{"f":"공정대표의무는 단체교섭의 과정이나 그 결과물인 단체협약의 내용뿐만 아니라 단체협약의 이행과정에도 적용된다.","w":"판례는 공정대표의무가 교섭 과정과 협약 내용뿐 아니라 협약을 이행하는 과정에서도 지켜져야 한다고 본다.","c":"상","v":1},"공인노2025_34-53-3":{"f":"노동조합이 단체협약의 체결에 관한 권한을 위임한 때에는 그 사실을 상대방에게 통보하여야 한다.","w":"교섭·체결 권한을 위임하면 그 사실을 상대방에게 알려야 한다(노조법 제29조 제4항). 노동위원회 통보 규정은 없다.","c":"상","v":1},"공인노2026_35-50-5":{"f":"교섭대표노동조합이 단체교섭 과정의 모든 단계에서 교섭창구 단일화절차에 참여한 소수노동조합에 대하여 일체의 정보제공 및 의견수렴 절차를 거쳐야만 절차적 공정대표의무를 이행한 것은 아니다.","w":"판례는 교섭 과정의 모든 단계에서 소수노조에 모든 정보를 주고 의견을 들어야 하는 것은 아니라고 본다. 소수노조가 교섭에 의견을 낼 수 있도록 필요한 정보를 적절히 제공하고 의견을 수렴하면 된다.","c":"상","v":1},"공인노2026_35-51-2":{"f":"노동조합 설립신고를 하지 않은 노동조합의 분회나 지부라도 독자적인 규약 및 집행기관을 가지고 독립된 조직체로서 활동을 하는 경우에는 당해 조직이나 그 조합원에 고유한 사항에 대하여 독자적으로 단체교섭하고 단체협약을 체결할 수 있다.","w":"판례는 분회·지부가 설립신고를 하지 않았어도 독립된 조직체로 활동하면 고유한 사항에 대해 독자적으로 교섭하고 협약을 맺을 수 있다고 본다.","c":"상","v":1},"공인노2026_35-54-2":{"f":"노동조합은 사업장에 단체협약이 2개 이상 있는 경우에는 먼저 이르는 단체협약의 유효기간 만료일 이전 3개월이 되는 날부터 사용자에게 교섭을 요구할 수 있다.","w":"기준은 가장 먼저 만료되는 단체협약이다(노조법 시행령 제14조의2 제1항).","c":"상","v":1},"공인노2026_35-54-3":{"f":"노동조합은 사용자가 교섭요구 사실의 공고를 하지 아니하거나 다르게 공고하는 경우에는 고용노동부령으로 정하는 바에 따라 노동위원회에 시정을 요청할 수 있다.","w":"교섭요구 사실 공고에 문제가 있으면 노동위원회에 시정을 요청한다(노조법 시행령 제14조의3 제2항).","c":"상","v":1},"공인노2026_35-54-4":{"f":"노동조합이 단체교섭에 관한 권한을 위임한 때에는 그 사실을 상대방에게 통보하여야 한다.","w":"위임 사실은 상대방에게 통보한다(노조법 제29조 제4항).","c":"상","v":1},"공인노2026_35-54-5":{"f":"단위노동조합이 당해 노동조합이 가입한 상부 연합단체에 단체교섭권한을 위임한 경우에도 단위노동조합의 단체교섭권한은 존재한다.","w":"위임해도 단위노동조합의 교섭권한은 사라지지 않고 연합단체의 권한과 함께 남는다는 것이 판례다.","c":"상","v":1},"공인노2026_35-56-3":{"f":"교섭단위 분리의 신청이 제기된 사업장의 모든 노동조합과 사용자는 노동위원회가 지정하는 기간까지 의견을 제출할 수 있다.","w":"분리 신청 통지를 받은 노동조합과 사용자는 노동위원회가 지정하는 기간까지 의견을 낼 수 있을 뿐, 14일 안에 출석해 의견을 제출할 의무는 없다(노조법 시행령 제14조의11 제2항).","c":"상","v":1},"공인노2026_35-57-4":{"f":"노동위원회는 공동교섭대표단 구성에 관한 결정신청을 받은 때에는 그 신청을 받은 날부터 10일 이내에 총 10명 이내에서 각 노동조합별 공동교섭대표단에 참여하는 인원수를 결정하여 그 노동조합과 사용자에게 통지해야 한다.","w":"노동위원회는 신청일부터 10일 이내에, 공동교섭대표단 전체 10명 이내에서 노동조합별 인원을 정한다(노조법 시행령 제14조의9 제2항).","c":"상","v":1},"공인노2017_26-38-1":{"f":"단체협약은 특별한 사정이 없는 한 명문의 규정을 근로자에게 불리하게 해석할 수 없다.","w":"판례는 단체협약 같은 처분문서는 명문의 규정을 근로자에게 불리하게 변형해 해석할 수 없다고 본다.","c":"상","v":1},"공인노2017_26-38-3":{"f":"근로조건을 불리하게 변경하는 내용의 단체협약이 현저히 합리성을 결하여 노동조합의 목적을 벗어난 것으로 볼 수 있는 경우와 같은 특별한 사정이 없는 한 그러한 노사간의 합의를 무효라고 볼 수는 없고, 노동조합으로서는 그러한 합의를 위하여 사전에 근로자들로부터 개별적인 동의나 수권을 받을 필요가 없다.","w":"판례는 불리한 단체협약을 맺을 때 노동조합이 근로자 개개인의 동의나 수권을 미리 받을 필요가 없다고 본다.","c":"상","v":1},"공인노2017_26-38-4":{"f":"노동조합이 기존의 임금, 근로시간, 퇴직금 등 근로조건을 결정하는 기준에 관하여 소급적으로 동의하는 내용의 단체협약을 사용자와 체결한 경우에, 동의의 효력은 단체협약 체결 이전에 퇴직한 근로자에게는 미치지 않는다.","w":"판례는 소급 동의 단체협약의 효력이 협약 체결 당시 근로관계가 유지되는 근로자에게만 미치고, 이미 퇴직한 근로자에게는 미치지 않는다고 본다.","c":"상","v":1},"공인노2017_26-38-5":{"f":"단체협약의 유효기간이 경과한 후에도 새로운 단체협약이 체결되지 않은 때에는 새로운 단체협약이 체결될 때까지 단체협약의 해지권을 행사하지 못하도록 하는 취지의 약정은 무효이다.","w":"6개월 전 통고로 해지할 수 있게 한 노조법 제32조 제3항 단서는 강행규정이라 해지권 행사를 막는 약정은 무효라는 것이 판례다.","c":"상","v":1},"공인노2019_28-37-5":{"f":"노동조합과 사용자 쌍방이 노사협의회를 거쳐 실질적ㆍ형식적 요건을 갖춘 합의가 있다면 단체교섭을 거치지 않고 체결한 것이라도 단체협약으로 볼 수 있다.","w":"판례는 노사협의회를 거쳤더라도 노조와 사용자 대표가 단체협약으로 할 의사로 서면 작성·서명 등 실질적·형식적 요건을 갖추었다면 단체협약으로 본다.","c":"상","v":1},"공인노2019_28-39-3":{"f":"단체협약의 해석에 관하여 관계 당사자간에 의견의 불일치가 있는 때에는 당사자 쌍방 또는 단체협약에 정하는 바에 의하여 어느 일방이 노동위원회에 그 해석에 관한 견해의 제시를 요청할 수 있다.","w":"노동위원회의 해석 견해 제시는 당사자의 요청이 있어야 한다. 노동위원회가 직권으로 하지 않는다(노조법 제34조 제1항).","c":"상","v":1},"공인노2022_31-34-2":{"f":"하나의 사업장에 상시 사용되는 동종의 근로자 반수 이상이 하나의 단체협약의 적용을 받게 된 때에는 다른 동종의 근로자에 대하여도 당해 단체협약이 적용된다.","w":"사업장 단위 일반적 구속력은 요건을 채우면 바로 생긴다. 행정관청의 결정이 필요한 것은 지역적 구속력이다(노조법 제35조, 제36조).","c":"상","v":1},"공인노2022_31-36-5":{"f":"노동조합은 사용자와 사이에 근로조건을 불리하게 변경하는 내용의 단체협약을 체결할 수 있다.","w":"판례는 노동조합이 근로조건을 불리하게 바꾸는 단체협약도 맺을 수 있고, 현저히 합리성을 잃어 노동조합의 목적을 벗어난 경우가 아니면 유효하다고 본다.","c":"상","v":1},"공인노2024_33-50-2":{"f":"단체협약의 유효기간이 만료되는 때를 전후하여 당사자 쌍방이 새로운 단체협약을 체결하고자 단체교섭을 계속하였음에도 불구하고 새로운 단체협약이 체결되지 아니한 경우에는 별도의 약정이 있는 경우를 제외하고는 종전의 단체협약은 그 효력만료일부터 3월까지 계속 효력을 갖는다.","w":"3개월 자동연장은 별도 약정이 없을 때 적용된다. 별도 약정이 있으면 그 약정에 따른다(노조법 제32조 제3항).","c":"상","v":1},"공인노2024_33-53-1":{"f":"행정관청은 단체협약중 위법한 내용이 있는 경우에는 노동위원회의 의결을 얻어 그 시정을 명할 수 있다.","w":"위법한 단체협약의 시정명령은 행정관청이 노동위원회 의결을 얻어 내린다(노조법 제31조 제3항).","c":"상","v":1},"공인노2025_34-49-3":{"f":"단체협약은 서면으로 작성하여 당사자 쌍방이 서명 또는 날인하여야 하며, 단체협약의 당사자는 단체협약의 체결일부터 15일 이내에 이를 행정관청에게 신고하여야 한다.","w":"단체협약 신고처는 행정관청이다(노조법 제31조 제2항).","c":"상","v":1},"공인노2025_34-51-4":{"f":"단체협약의 당사자인 노동조합은 단체협약의 유효기간 중에 단체협약에서 정한 근로 조건 등에 관한 내용의 변경이나 폐지를 요구하는 쟁의행위를 행하지 않을 평화의무를 부담한다.","w":"판례는 단체협약 당사자인 노동조합이 유효기간 중 협약 내용의 변경·폐지를 요구하며 쟁의행위를 하지 않을 평화의무를 진다고 본다.","c":"상","v":1},"공인노2025_34-54-5":{"f":"서로 다른 종류의 사업을 운영하던 회사들이 합병한 이후 그 중 한 사업부문의 근로자들로 구성된 노동조합이 회사와 체결한 단체협약은 다른 사업부문의 근로자들에게는 적용되지 않는다.","w":"판례는 합병 전 다른 사업을 하던 부문의 근로자는 그 단체협약의 적용이 예상되는 동종 근로자가 아니어서 협약이 확장 적용되지 않는다고 본다.","c":"중","v":1},"공인노2026_35-52-5":{"f":"단체협약에 규정된 인사조항의 구체적 내용이 사용자가 인사처분을 함에 있어서 신중을 기할 수 있도록 노동조합이 의견을 제시할 수 있는 기회만을 주어야 하도록 규정된 경우에는 그 절차를 거치지 아니하였더라도 그 인사처분은 무효가 아니다.","w":"판례는 노조의 동의·승낙을 요구하는 조항과 의견 제시 기회만 주는 협의 조항을 나눈다. 협의 조항이면 절차를 거치지 않았어도 인사처분이 곧바로 무효가 되지는 않는다.","c":"상","v":1},"공인노2026_35-53-2":{"f":"단체협약에서 노동조합규약과 달리 조합원 자격규정을 둔 경우, 단체협약의 일반적 구속력 적용은 단체협약에 따른다.","w":"판례는 일반적 구속력의 동종 근로자를 그 단체협약 규정상 적용이 예상되는 사람으로 보고, 단체협약에서 조합원 자격이 없는 사람은 적용 대상에서 뺀다.","c":"중","v":1},"공인노2026_35-53-3":{"f":"하나의 사업장에서 일반적 구속력이 인정되는 경우 행정관청이 이를 공고하여야 하는 것은 아니다.","w":"사업장 단위 일반적 구속력은 요건을 채우면 바로 생기고 공고 절차가 없다. 공고는 지역적 구속력 결정을 한 경우에 한다(노조법 제36조 제2항).","c":"상","v":1},"공인노2026_35-53-4":{"f":"행정관청은 노동위원회의 의결을 얻어 직권으로 단체협약의 지역적 구속력 적용 결정을 할 수 있다.","w":"행정관청은 당사자 쌍방 또는 일방의 신청이 있거나 직권으로, 노동위원회 의결을 얻어 지역적 구속력 결정을 할 수 있다(노조법 제36조 제1항).","c":"상","v":1},"공인노2026_35-53-5":{"f":"행정관청이 단체협약의 지역적 구속력 적용 결정을 한 때에는 지체없이 이를 공고하여야 한다.","w":"지역적 구속력 결정을 하면 지체 없이 공고해야 하고, 별도의 적용기간을 정하라는 규정은 없다(노조법 제36조 제2항).","c":"중","v":1},"공인노2026_35-55-4":{"f":"노동조합과 사용자 쌍방의 대표자가 근로조건에 관한 사항에 관하여 단체협약으로 할 의사로 문서로 작성하여 서명 또는 날인하는 등으로 단체협약의 실질적ㆍ형식적 요건을 갖추었다면 노사협의회의 합의를 거치는 방식으로 하였더라도 단체협약으로 볼 수 있다.","w":"판례는 노사협의회를 거친 합의라도 단체협약의 실질적·형식적 요건을 갖추면 단체협약으로 본다.","c":"상","v":1},"공인노2017_26-40-4":{"f":"쟁의행위를 위한 찬반투표절차를 거치지 아니한 경우 조합원의 민주적 의사결정이 실질적으로 확보되었다고 볼 수 있는 때에도 그 절차를 따를 수 없는 객관적인 사정이 없는 한 그 쟁의행위는 정당성을 상실한다.","w":"대법원 전원합의체 판결은 찬반투표를 거치지 않은 쟁의행위는 투표를 할 수 없는 객관적 사정이 없는 한, 민주적 의사결정이 실질적으로 있었더라도 정당성을 잃는다고 했다.","c":"상","v":1},"공인노2019_28-42-5":{"f":"노동조합의 쟁의행위는 그 조합원의 직접ㆍ비밀ㆍ무기명투표에 의한 조합원 과반수의 찬성으로 결정하지 아니하면 이를 행할 수 없다.","w":"쟁의행위 찬성 요건은 조합원 과반수다(노조법 제41조 제1항). 현행법은 종사근로자인 조합원 과반수로 정한다.","c":"상","v":1},"공인노2019_28-43-5":{"f":"근로자가 유급휴가를 이용하여 파업에 참여하는 것은 정당한 유급휴가권의 행사로 볼 수 없으므로 파업기간 중에 포함된 유급휴가에 대한 임금청구권이 발생하지 않는다.","w":"판례는 파업 중에는 근로제공의무가 정지되므로, 유급휴가를 써서 파업에 참여해도 그 휴가에 대한 임금청구권은 생기지 않는다고 본다.","c":"상","v":1},"공인노2019_28-44-3":{"f":"직장폐쇄의 개시 자체가 정당하더라도 근로자의 쟁의행위에 대한 방어적인 목적에서 벗어나 공격적 직장폐쇄의 성격으로 변질되었다면 그 이후의 직장폐쇄는 정당성을 상실한다.","w":"판례는 처음에 정당했던 직장폐쇄도 공격적 직장폐쇄로 바뀐 뒤부터는 정당성을 잃는다고 본다.","c":"상","v":1},"공인노2022_31-40-1":{"f":"사용자의 직장폐쇄가 정당한 쟁의행위로 평가받는 경우에도 사업장 내의 노조사무실 등 정상적인 노조활동에 필요한 시설에 대한 조합원의 출입은 허용된다.","w":"판례는 정당한 직장폐쇄라도 노조사무실처럼 정상적인 노조활동에 필요한 시설에는 조합원 출입을 허용해야 한다고 본다.","c":"상","v":1},"공인노2022_31-42-1":{"f":"근로자는 쟁의행위 기간중에는 현행범외에는 노동조합 및 노동관계조정법 위반을 이유로 구속되지 아니한다.","w":"현행범은 쟁의행위 기간 중에도 구속될 수 있다(노조법 제39조).","c":"상","v":1},"공인노2022_31-42-3":{"f":"노동조합은 사용자의 점유를 배제하여 조업을 방해하는 형태로 쟁의행위를 해서는 아니 된다.","w":"2021년 개정 노조법은 사용자의 점유를 배제해 조업을 방해하는 형태의 쟁의행위를 금지한다(제37조 제3항).","c":"상","v":1},"공인노2022_31-42-4":{"f":"노동조합은 쟁의행위 기간에 대한 임금의 지급을 요구하여 이를 관철할 목적으로 쟁의 행위를 하여서는 아니된다.","w":"쟁의기간 임금 지급을 관철하려는 쟁의행위는 금지된다(노조법 제44조 제2항).","c":"상","v":1},"공인노2022_31-42-5":{"f":"필수공익사업의 사용자는 쟁의행위 기간중 그 쟁의행위로 중단된 업무의 수행을 위하여 당해 사업 또는 사업장 파업참가자의 100분의 50을 초과하지 않는 범위 안에서 당해 사업과 관계없는 자를 채용 또는 대체할 수 있다.","w":"필수공익사업은 대체근로 금지의 예외로, 파업참가자의 100분의 50 범위에서 외부 인력을 채용·대체하거나 도급을 줄 수 있다(노조법 제43조 제3항·제4항).","c":"상","v":1},"공인노2022_31-43-5":{"f":"노동조합이 사용자가 수용할 수 없는 과다한 요구를 하였다는 사정만으로는 그 쟁의행위의 목적의 정당성이 부정되지 않는다.","w":"판례는 요구가 과다하다는 것만으로 쟁의행위 목적의 정당성을 부정하지 않는다. 과다한 요구는 교섭으로 조정될 수 있다고 보기 때문이다.","c":"상","v":1},"공인노2024_33-57-2":{"f":"사용자는 쟁의행위가 그 쟁의행위와 관계없는 자의 정상적인 업무를 방해하는 방법으로 행하여지는 경우 즉시 그 상황을 행정관청과 관할 노동위원회에 신고하여야 한다.","w":"위법한 쟁의행위 상황을 신고하는 주체는 사용자이고, 신고처는 행정관청과 관할 노동위원회다(노조법 시행령 제18조).","c":"상","v":1},"공인노2024_33-58-5":{"f":"행정관청은 쟁의행위가 안전보호시설에 대하여 정상적인 유지ㆍ운영을 정지ㆍ폐지 또는 방해하는 행위에 해당한다고 인정하는 경우에는 노동위원회의 의결을 얻어 그 행위를 중지할 것을 통보하여야 한다.","w":"안전보호시설 방해 쟁의행위에 중지 통보를 하는 것은 행정관청이다. 원칙적으로 노동위원회 의결을 얻어야 하고, 급박하면 의결 없이 바로 통보한 뒤 사후 승인을 받는다(노조법 제42조 제3항·제4항).","c":"상","v":1},"공인노2024_33-59-4":{"f":"노동조합은 필수유지업무협정이 체결된 경우 필수유지업무에 근무하는 조합원 중 쟁의 행위기간 동안 근무하여야 할 조합원을 사용자에게 통보하여야 한다.","w":"근무할 조합원 명단은 노동조합이 사용자에게 통보하고 사용자는 그에 따라 지명한다. 노동조합이 통보하지 않으면 사용자가 지명해 노동조합과 근로자에게 알린다(노조법 제42조의6).","c":"상","v":1},"공인노2025_34-55-1":{"f":"노동조합은 쟁의행위를 하고자 할 경우에는 고용노동부령이 정하는 바에 따라 행정관청과 관할 노동위원회에 쟁의행위의 일시ㆍ장소ㆍ참가인원 및 그 방법을 미리 서면으로 신고하여야 한다.","w":"쟁의행위 신고는 행정관청과 관할 노동위원회 두 곳에 미리 서면으로 하고, 신고 사항은 일시·장소·참가인원·방법이다(노조법 시행령 제17조).","c":"상","v":1},"공인노2025_34-56-1":{"f":"도시철도의 안전 운행을 위하여 필요한 차량의 일상적인 점검 업무는 필수유지업무이다.","w":"철도·도시철도 사업의 필수유지업무에는 안전 운행에 필요한 차량의 일상적인 점검이나 정비 업무가 들어간다(노조법 시행령 별표 1).","c":"중","v":1},"공인노2025_34-56-2":{"f":"노동위원회는 필수유지업무 수준 등 결정을 하면 지체 없이 이를 서면으로 노동관계 당사자에게 통보하여야 한다.","w":"노동위원회는 필수유지업무 수준 등 결정을 하면 지체 없이 서면으로 노동관계 당사자에게 통보한다(노조법 시행령 제22조의3 제2항).","c":"상","v":1},"공인노2025_34-56-4":{"f":"필수유지업무 수준 등 결정신청은 노동관계 당사자 쌍방 또는 일방이 할 수 있다.","w":"필수유지업무협정이 체결되지 않으면 노사 쌍방 또는 일방이 노동위원회에 결정을 신청한다(노조법 제42조의4 제1항).","c":"상","v":1},"공인노2025_34-56-5":{"f":"필수유지업무의 정당한 유지ㆍ운영을 정지ㆍ폐지 또는 방해하는 행위는 쟁의행위로서 이를 행할 수 없다.","w":"정지·폐지뿐 아니라 방해하는 행위도 쟁의행위로 할 수 없다(노조법 제42조의2 제2항).","c":"상","v":1},"공인노2025_34-57-2":{"f":"사업장의 안전보호시설에 대하여 정상적인 유지ㆍ운영을 방해하는 쟁의행위에 대하여 행정관청은 노동위원회의 의결을 얻어 그 행위를 중지할 것을 통보하여야 한다.","w":"중지 통보 주체는 행정관청이고, 노동위원회는 그 전에 의결을 한다(노조법 제42조 제3항).","c":"상","v":1},"공인노2025_34-59-1":{"f":"사용자의 직장폐쇄가 정당한 쟁의행위로 인정되지 아니하는 때에는 적법한 쟁의행위로서 사업장을 점거 중인 근로자들이 직장폐쇄를 단행한 사용자로부터 퇴거 요구를 받고 이에 불응하더라도 퇴거불응죄가 성립하지 아니한다.","w":"판례는 직장폐쇄가 정당하지 않으면 적법하게 사업장을 점거 중인 근로자가 퇴거 요구에 응하지 않아도 퇴거불응죄가 되지 않는다고 본다.","c":"상","v":1},"공인노2025_34-59-2":{"f":"직장폐쇄를 할 경우 사용자는 미리 행정관청 및 노동위원회에 각각 신고하여야 한다.","w":"직장폐쇄 신고는 행정관청과 노동위원회 두 곳에 미리 해야 한다(노조법 제46조 제2항).","c":"상","v":1},"공인노2025_34-59-3":{"f":"근로자가 쟁의행위를 중단하고 진정으로 업무에 복귀할 의사를 표시하였음에도 사용자가 적극적으로 노동조합의 조직력을 약화시키기 위한 목적으로 공격적 직장폐쇄를 유지한다면 그 정당성을 잃는다.","w":"판례는 근로자가 복귀 의사를 밝혔는데도 노조 약화 목적으로 직장폐쇄를 이어가면 그때부터 정당성을 잃는다고 본다.","c":"상","v":1},"공인노2025_34-59-5":{"f":"사용자는 직장폐쇄가 정당한 쟁의행위로 평가받을 때에만 직장폐쇄 기간 동안의 대상 근로자에 대한 임금지불의무를 면한다.","w":"직장폐쇄가 정당해야 임금지불의무를 면한다. 정당하지 않으면 그 기간의 임금을 지급해야 한다는 것이 판례다.","c":"상","v":1},"공인노2026_35-58-3":{"f":"근로를 불완전하게 제공하는 형태의 쟁의행위인 태업은 근로제공이 일부 정지되는 것이라고 할 수 있으므로, 여기에도 무노동 무임금 원칙이 적용된다.","w":"판례는 태업도 근로제공이 일부 정지된 것이므로 무노동 무임금 원칙이 적용되어, 태업 정도에 비례해 임금을 깎을 수 있다고 본다.","c":"상","v":1},"공인노2026_35-59-1":{"f":"노동관계 당사자는 노동쟁의가 발생한 때에는 어느 일방이 이를 상대방에게 서면으로 통보하여야 한다.","w":"노동쟁의 발생 통보는 상대방에게 서면으로 한다(노조법 제45조 제1항).","c":"상","v":1},"공인노2026_35-65-1":{"f":"사용자의 불법행위에 대하여 근로자의 이익을 방위하기 위하여 부득이 사용자에게 손해를 가한 근로자는 노동조합과 마찬가지로 배상할 책임이 없다.","w":"사용자의 불법행위에 맞서 노동조합이나 근로자의 이익을 지키려고 부득이 사용자에게 손해를 입힌 경우 노동조합과 근로자 모두 배상 책임이 없다(노조법 제3조 제2항, 2025.9.9 신설).","c":"상","v":1},"공인노2026_35-65-3":{"f":"사용자는 그 밖의 노동조합의 활동으로 인한 노동조합의 손해배상 등 책임을 면제할 수 있다.","w":"사용자는 단체교섭·쟁의행위 그 밖의 노동조합 활동으로 인한 노동조합이나 근로자의 손해배상 등 책임을 면제할 수 있다. 면제가 의무는 아니다(노조법 제3조의2).","c":"상","v":1},"공인노2026_35-65-4":{"f":"사용자는 현행 「노동조합 및 노동관계조정법」 시행 전 발생한 쟁의행위로 인한 노동조합의 손해배상 책임을 면제할 수 있다.","w":"책임 면제를 정한 제3조의2는 개정법 시행 전에 생긴 손해에도 적용되므로, 사용자는 시행 전 쟁의행위로 인한 노동조합의 손해배상 책임도 면제할 수 있다(노조법 제3조의2, 부칙 제2조 단서).","c":"상","v":1},"공인노2026_35-65-5":{"f":"신원보증인은 쟁의행위 중 근로자의 고의로 인한 행위로 발생한 손해를 배상할 책임이 없다.","w":"「신원보증법」 제6조와 관계없이 신원보증인은 단체교섭·쟁의행위 그 밖의 노동조합 활동으로 생긴 손해를 배상할 책임이 없다(노조법 제3조 제5항, 2025.9.9 신설).","c":"상","v":1},"공인노2017_26-35-2":{"f":"노동관계 당사자는 사적조정등에 의하여 노동쟁의를 해결하기로 한 때에는 이를 노동위원회에 신고하여야 한다.","w":"사적 조정·중재로 해결하기로 하면 노동위원회에 신고한다(노조법 제52조 제2항).","c":"상","v":1},"공인노2019_28-40-1":{"f":"공익사업에 있어서의 노동쟁의의 조정은 우선적으로 취급하고 신속히 처리하여야 한다.","w":"공익사업 노동쟁의의 우선·신속 처리는 노력 규정이 아니라 의무 규정이다(노조법 제51조).","c":"상","v":1},"공인노2019_28-41-2":{"f":"노동쟁의가 노동위원회의 중재에 회부된 때에는 그 날부터 15일간은 쟁의행위를 할 수 없다.","w":"중재 회부 뒤 쟁의행위 금지기간은 15일이다(노조법 제63조).","c":"상","v":1},"공인노2019_28-41-3":{"f":"노동쟁의의 중재를 위하여 당해 노동위원회의 공익을 대표하는 위원 중에서 관계 당사자의 합의로 선정한 자 3인으로 구성된 중재위원회를 둔다.","w":"중재위원회는 공익위원 3명으로만 구성한다. 노·사·공익 위원 각 1명으로 짜는 것은 조정위원회다(노조법 제55조, 제64조).","c":"상","v":1},"공인노2019_28-41-4":{"f":"고용노동부장관은 긴급조정의 결정을 하고자 할 때에는 미리 중앙노동위원회 위원장의 의견을 들어야 한다.","w":"긴급조정 결정권자는 고용노동부장관이고, 결정 전에 중앙노동위원회 위원장의 의견을 듣는다(노조법 제76조).","c":"상","v":1},"공인노2019_28-41-5":{"f":"관계 당사자는 긴급조정의 결정이 공표된 때에는 즉시 쟁의행위를 중지하여야 하며, 공표일부터 30일이 경과하지 아니하면 쟁의행위를 재개할 수 없다.","w":"긴급조정 공표 뒤 쟁의행위 재개 금지기간은 30일이다(노조법 제77조).","c":"상","v":1},"공인노2022_31-37-3":{"f":"노동위원회는 조정신청 전이라도 교섭을 주선하는 등 관계 당사자의 자주적인 분쟁 해결을 지원할 수 있다.","w":"노동위원회는 조정신청 전에도 교섭 주선 등으로 자주적 해결을 지원할 수 있다(노조법 제53조 제2항).","c":"상","v":1},"공인노2022_31-38-1":{"f":"노동쟁의가 중재에 회부된 때에는 그 날부터 15일간은 쟁의행위를 할 수 없다.","w":"금지기간은 15일이다(노조법 제63조).","c":"상","v":1},"공인노2022_31-38-3":{"f":"중재는 조정을 거치지 않더라도 신청할 수 있다.","w":"중재는 당사자 쌍방이 함께 신청하거나 단체협약에 따라 일방이 신청하면 개시된다. 조정을 먼저 거칠 필요는 없다(노조법 제62조).","c":"상","v":1},"공인노2022_31-38-4":{"f":"관계 당사자는 지방노동위원회의 중재재정이 월권에 의한 것이라고 인정하는 경우에는 중앙노동위원회에 재심을 신청할 수 있다.","w":"지방노동위원회 중재재정이 위법하거나 월권이면 송달받은 날부터 10일 이내에 중앙노동위원회에 재심을 신청할 수 있다(노조법 제69조 제1항).","c":"상","v":1},"공인노2022_31-38-5":{"f":"중재재정의 내용은 관계 당사자의 동의가 없더라도 단체협약과 동일한 효력을 가진다.","w":"중재재정의 내용은 당사자 동의 없이 그대로 단체협약과 같은 효력을 가진다(노조법 제70조 제1항). 당사자가 수락해야 효력이 생기는 것은 조정안이다.","c":"상","v":1},"공인노2024_33-60-1":{"f":"사적 조정의 신고는 노동위원회의 조정이 진행 중인 경우에도 할 수 있다.","w":"사적 조정·중재 신고는 노동위원회의 조정이나 중재가 진행 중일 때도 할 수 있다(노조법 시행령 제23조 제2항).","c":"상","v":1},"공인노2024_33-62-1":{"f":"중재위원회의 중재위원은 당해 노동위원회의 공익을 대표하는 위원중에서 관계 당사자의 합의로 선정한 자에 대하여 그 노동위원회의 위원장이 지명한다.","w":"공익위원 중 당사자 합의로 선정한 사람을 지명하는 방식은 중재위원 선정 방법이다. 조정위원회는 근로자·사용자·공익을 대표하는 위원 각 1명으로, 근로자 대표 위원은 사용자가, 사용자 대표 위원은 노동조합이 추천한 위원 중에서 지명한다(노조법 제55조).","c":"상","v":1},"공인노2024_33-62-2":{"f":"노동위원회의 위원장은 조정위원회의 구성이 어려운 경우 노동위원회의 공익을 대표하는 위원 중에서 3인을 조정위원으로 지명할 수 있다.","w":"근로자·사용자 대표 위원의 불참 등으로 조정위원회 구성이 어려우면 위원장은 공익위원 중에서 3명을 조정위원으로 지명할 수 있다(노조법 제55조 제4항).","c":"상","v":1},"공인노2024_33-62-3":{"f":"단독조정인은 그 노동위원회의 위원중에서 관계 당사자의 쌍방의 합의로 선정된 자를 그 노동위원회의 위원장이 지명한다.","w":"단독조정인은 당사자 쌍방이 합의로 고른 노동위원회 위원을 위원장이 지명한다(노조법 제57조 제2항). 순차배제 방식은 공익위원 위촉 절차다.","c":"상","v":1},"공인노2024_33-62-4":{"f":"중재위원회의 중재위원은 당해 노동위원회의 공익을 대표하는 위원중에서 관계 당사자의 합의로 선정한 자에 대하여 그 노동위원회의 위원장이 지명한다.","w":"중재위원 3명은 모두 공익위원 중에서 뽑는다. 합의가 안 되면 위원장이 공익위원 중에서 지명한다(노조법 제64조).","c":"상","v":1},"공인노2024_33-63-4":{"f":"관계 당사자는 중앙노동위원회의 중재재정이나 재심결정이 위법이거나 월권에 의한 것이라고 인정하는 경우에는 그 중재재정서 또는 재심결정서의 송달을 받은 날부터 15일 이내에 행정소송을 제기할 수 있다.","w":"행정소송 기간은 결정을 한 날이 아니라 중재재정서·재심결정서를 송달받은 날부터 15일이다(노조법 제69조 제2항).","c":"상","v":1},"공인노2025_34-60-5":{"f":"조정위원회 또는 단독조정인이 관계 당사자가 수락을 거부하여 더 이상 조정이 이루어질 여지가 없다고 판단되어 조정의 종료를 결정한 이후에도 노동위원회는 노동쟁의의 해결을 위하여 조정을 할 수 있다.","w":"조정 종료가 결정된 뒤에도 노동위원회는 쟁의 해결을 위해 사후조정을 할 수 있다(노조법 제61조의2).","c":"상","v":1},"공인노2025_34-61-5":{"f":"노동관계 당사자는 단체협약에 노동관계의 적정화를 위한 노사협의 기타 단체교섭의 절차와 방식을 규정하고 노동쟁의가 발생한 때에는 이를 자주적으로 해결하도록 노력하여야 한다.","w":"자주적 해결은 노력의무로 정해져 있다(노조법 제48조).","c":"상","v":1},"공인노2025_34-64-4":{"f":"중재위원회의 위원장은 중재위원 중에서 호선한다.","w":"중재위원회 위원장은 중재위원끼리 호선한다(노조법 제65조 제2항).","c":"상","v":1},"공인노2025_34-66-5":{"f":"노동위원회의 중재재정 또는 재심결정은 중앙노동위원회에의 재심신청 또는 행정소송의 제기에 의하여 그 효력이 정지되지 아니한다.","w":"재심신청이나 행정소송을 내도 중재재정·재심결정의 효력은 멈추지 않는다(노조법 제70조 제2항).","c":"상","v":1},"공인노2025_34-69-3":{"f":"관계 당사자는 긴급조정의 결정이 공표된 때에는 즉시 쟁의행위를 중지하여야 한다.","w":"긴급조정이 공표되면 즉시 쟁의행위를 멈춰야 하고, 공표일부터 30일이 지나야 재개할 수 있다(노조법 제77조).","c":"상","v":1},"공인노2026_35-60-1":{"f":"노동위원회는 관계 당사자의 일방이 노동쟁의의 조정을 신청한 때에는 지체없이 조정을 개시하여야 하며 관계 당사자 쌍방은 이에 성실히 임하여야 한다.","w":"조정은 신청이 있으면 지체 없이 개시한다. 10일·15일은 조정을 끝내야 하는 기간이다(노조법 제53조, 제54조).","c":"상","v":1},"공인노2026_35-61-4":{"f":"노동위원회의 중재재정은 중앙노동위원회에의 재심신청의 제기에 의하여 그 효력이 정지되지 아니한다.","w":"재심신청을 해도 중재재정의 효력은 정지되지 않는다(노조법 제70조 제2항).","c":"상","v":1},"공인노2026_35-62-2":{"f":"노동쟁의가 중재에 회부된 때에는 그 날부터 15일간은 쟁의행위를 할 수 없다.","w":"중재 회부 뒤 쟁의행위 금지기간은 15일이다(노조법 제63조).","c":"상","v":1},"공인노2019_28-45-3":{"f":"불이익 취급의 부당노동행위는 현실적인 행위나 조치로 나타날 것을 요하므로 그 근로자에게 향후 불이익한 대우를 하겠다는 의사를 말로써 표시하는 것만으로는 성립하지 않는다.","w":"판례는 불이익취급(제81조 제1항 제1호)이 성립하려면 해고 등 현실적인 불이익 조치가 있어야 하고, 불이익을 주겠다는 말만으로는 부족하다고 본다.","c":"상","v":1},"공인노2019_28-46-4":{"f":"","w":"노조법에는 부당노동행위 구제명령 불이행에 대한 이행강제금 제도가 없다. 이행강제금은 근로기준법상 부당해고 등 구제명령에 대한 제도다. 노조법은 확정된 구제명령 위반에 형벌을, 긴급이행명령 위반에 과태료를 둔다.","c":"상","v":1},"공인노2022_31-44-1":{"f":"근로시간 면제한도를 초과하여 사용자가 급여를 지급하면 부당노동행위가 성립한다.","w":"근로시간 면제한도를 넘는 급여 지급은 부당노동행위다(노조법 제81조 제1항 제4호).","c":"상","v":1},"공인노2022_31-46-1":{"f":"사용자의 부당노동행위로 인하여 그 권리를 침해당한 근로자는 노동위원회에 그 구제를 신청할 수 있다.","w":"구제신청은 근로자와 노동조합 모두 할 수 있다(노조법 제82조 제1항).","c":"상","v":1},"공인노2022_31-46-2":{"f":"노동위원회가 관계 당사자의 심문을 할 때에는 관계당사자의 신청 없이도 직권으로 증인을 출석하게 하여 필요한 사항을 질문할 수 있다.","w":"노동위원회는 신청이 있거나 직권으로 증인을 출석시켜 질문할 수 있다(노조법 제83조 제2항).","c":"상","v":1},"공인노2022_31-46-4":{"f":"지방노동위원회의 기각결정에 불복이 있는 관계 당사자는 그 결정서의 송달을 받은 날부터 10일 이내에 중앙노동위원회에 그 재심을 신청할 수 있다.","w":"재심 신청 기간 10일은 결정이 있은 날이 아니라 명령서·결정서를 송달받은 날부터 센다(노조법 제85조 제1항).","c":"상","v":1},"공인노2022_31-46-5":{"f":"중앙노동위원회의 재심판정은 행정소송의 제기에 의하여 그 효력이 정지되지 아니한다.","w":"행정소송을 내도 재심판정의 효력은 멈추지 않는다(노조법 제86조).","c":"상","v":1},"공인노2024_33-52-2":{"f":"노동조합 및 노동관계조정법 제81조(부당노동행위) 제1항 제4호 단서에 따른 “노동조합의 자주적인 운영 또는 활동을 침해할 위험” 여부를 판단할 때 원조된 운영비 금액과 원조방법을 고려하여야 한다.","w":"자주성 침해 위험은 운영비 원조의 목적과 경위, 횟수와 기간, 금액과 방법, 노조 총수입 대비 비율, 관리방법과 사용처를 고려해 판단한다(노조법 제81조 제2항).","c":"상","v":1},"공인노2025_34-62-1":{"f":"부당노동행위 구제의 신청은 부당노동행위가 있은 날(계속하는 행위는 그 종료일)부터 3월 이내에 이를 행하여야 한다.","w":"구제신청 기간은 3개월이다(노조법 제82조 제2항).","c":"상","v":1},"공인노2025_34-63-1":{"f":"회사 대표이사가 조합원에게 해고 또는 불이익한 대우를 하겠다는 의사표시를 하였으나 이를 현실화하지 않았다면 이 법제81조제1항제1호에서 정한 부당노동행위에 해당하지 않는다.","w":"판례는 불이익취급이 성립하려면 현실적인 불이익 조치가 있어야 한다고 본다. 의사표시에 그쳤다면 제1호 불이익취급은 아니고, 지배·개입이 되는지는 따로 따진다.","c":"상","v":1},"공인노2026_35-63-1":{"f":"부당노동행위구제신청에 따른 구제명령이 객관적으로 보아 그 실현이 불능인 경우에는 중앙노동위원회 판정의 취소를 구할 소의 이익이 없다고 보아야 한다.","w":"판례는 구제명령이 객관적으로 실현될 수 없게 되면 재심판정 취소를 구할 법률상 이익이 없다고 본다.","c":"중","v":1},"공인노2026_35-63-2":{"f":"확정된 부당노동행위 구제명령에 위반한 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.","w":"확정된 구제명령 위반은 3년 이하 징역 또는 3천만원 이하 벌금이다(노조법 제89조).","c":"상","v":1},"공인노2026_35-63-3":{"f":"유니언 숍 협정이 있는 사업장의 일부 조합원이 노동조합에 불만을 품고 탈퇴하였다가 다시 재가입 신청을 하였으나, 노동조합이 그들 중 일부만의 가입을 승인하고 나머지에 대하여는 승인을 거부한 것은 권리남용으로서 허용되지 않는다.","w":"판례는 유니언 숍 사업장에서 노동조합이 탈퇴자 일부의 재가입만 받아들이고 나머지를 거부하는 것은 권리남용이라 보고, 그 거부를 이유로 한 해고도 효력이 없다고 했다.","c":"중","v":1},"공인노2026_35-63-4":{"f":"노동위원회의 사용자에 대한 부당노동행위 구제명령은 사용자에게 공법상의 의무를 부담시킬 뿐, 직접 노사간의 사법상의 법률관계를 발생 또는 변경시키는 것은 아니다.","w":"판례는 구제명령이 사용자에게 공법상 의무만 지울 뿐, 노사 간 사법상 법률관계를 직접 만들거나 바꾸지 않는다고 본다.","c":"상","v":1},"공인노2026_35-64-1":{"f":"지배ㆍ개입으로서의 부당노동행위의 성립에는 반드시 근로자의 단결권 침해라는 결과의 발생까지 요하는 것은 아니다.","w":"판례는 지배·개입은 단결권을 침해할 위험만 있어도 성립하고, 실제 침해 결과까지 필요하지 않다고 본다.","c":"상","v":1},"공인노2026_35-64-2":{"f":"노동위원회의 구제명령은 행정소송의 제기에 의하여 그 효력이 정지되지 아니한다.","w":"재심신청이나 행정소송으로 구제명령의 효력은 정지되지 않는다(노조법 제86조).","c":"상","v":1},"공인노2026_35-64-4":{"f":"지방노동위원회의 구제명령에 불복이 있는 관계 당사자는 그 명령서의 송달을 받은 날부터 10일 이내에 중앙노동위원회에 그 재심을 신청할 수 있다.","w":"재심 신청 기간은 송달받은 날부터 10일이다(노조법 제85조 제1항).","c":"상","v":1},"공인노2026_35-64-5":{"f":"중앙노동위원회의 재심판정에 대하여 관계 당사자는 그 재심판정서의 송달을 받은 날부터 15일 이내에 「행정소송법」이 정하는 바에 의하여 소를 제기할 수 있다.","w":"재심판정에 대한 행정소송 기간은 송달받은 날부터 15일이다(노조법 제85조 제2항).","c":"상","v":1},"공인노2019_28-48-2":{"f":"노동위원회는 관계 행정기관으로 하여금 근로조건의 개선에 필요한 조치를 하도록 권고할 수 있다.","w":"노동위원회는 관계 행정기관에 근로조건 개선 조치를 권고할 수 있을 뿐, 권고받은 기관이 따라야 한다는 규정은 없다. 특별한 사유가 없으면 따라야 하는 것은 노동위원회의 협조 요청이다(노동위원회법 제22조 제1항·제2항).","c":"상","v":1},"공인노2022_31-47-3":{"f":"노동위원회 위원의 임기는 3년으로 하되, 연임할 수 있다.","w":"노동위원회 위원의 임기는 3년이고 연임할 수 있다(노동위원회법 제7조 제1항).","c":"상","v":1},"공인노2024_33-68-5":{"f":"화해에 관여한 부문별 위원회의 위원 전원(단독심판의 경우에는 해당 단독심판 위원)은 화해조서에 모두 서명하거나 날인하여야 한다.","w":"화해조서에는 관계 당사자와 화해에 관여한 부문별 위원회 위원 전원이 서명·날인하고, 여기에는 단독심판 위원도 들어간다(노동위원회법 제16조의3 제4항).","c":"상","v":1},"공인노2024_33-69-1":{"f":"노동위원회는 서류의 송달을 받아야 할 자의 주소가 분명하지 아니한 경우에는 공시 송달을 할 수 있다.","w":"주소가 분명하지 않으면 공시송달을 할 수 있다. 반드시 해야 하는 것은 아니다(노동위원회법 제17조의3 제1항 제1호).","c":"상","v":1},"공인노2024_33-69-2":{"f":"노동위원회는 서류의 송달을 받아야 할 자의 주소가 통상적인 방법으로 확인할 수 없어 서류의 송달이 곤란한 경우에는 공시송달을 할 수 있다.","w":"주소를 통상적인 방법으로 확인할 수 없어 송달이 곤란하면 공시송달을 할 수 있다. 의무 규정이 아니다(노동위원회법 제17조의3 제1항 제2호).","c":"상","v":1},"공인노2024_33-69-4":{"f":"노동위원회는 서류의 송달을 받아야 할 자에게 등기우편 등으로 송달하였으나 송달을 받아야 할 자가 없는 것으로 확인되어 반송되는 경우에는 공시송달을 할 수 있다.","w":"등기우편 송달이 수취인 없음으로 반송된 경우에도 공시송달은 할 수 있는 것이지 해야 하는 것이 아니다(노동위원회법 제17조의3 제1항 제3호).","c":"상","v":1},"공인노2024_33-69-5":{"f":"노동위원회는 서류의 송달을 받아야 할 자의 주소가 국외에 있어서 서류의 송달이 곤란한 경우에는 공시송달을 할 수 있다.","w":"주소가 국외에 있어 송달이 곤란한 경우에도 공시송달을 할 수 있을 뿐 반드시 해야 하는 것은 아니다(노동위원회법 제17조의3 제1항 제2호).","c":"상","v":1},"공인노2024_33-70-2":{"f":"노동위원회는 관계 행정기관으로 하여금 근로조건의 개선에 필요한 조치를 하도록 권고할 수 있다.","w":"노동위원회가 관계 행정기관에 할 수 있는 것은 권고다. 명령할 권한은 없다(노동위원회법 제22조 제2항).","c":"상","v":1},"공인노2025_34-75-2":{"f":"부문별 위원회를 소집할 수 있는 권한은 부문별 위원회 위원장뿐만 아니라 노동위원회 위원장에게도 있다.","w":"부문별 위원회는 부문별 위원회 위원장이 소집하지만, 노동위원회 위원장도 필요하다고 인정하면 소집할 수 있다(노동위원회법 제16조 제2항).","c":"상","v":1},"공인노2025_34-75-3":{"f":"부문별 위원회 위원장은 부문별 위원회를 구성하는 위원의 과반수가 회의 소집을 요구하는 경우에 이에 따라야 한다.","w":"부문별 위원회 위원장이 따라야 하는 소집 요구는 구성위원 과반수의 요구다(노동위원회법 제16조 제3항).","c":"상","v":1},"공인노2025_34-75-4":{"f":"부문별 위원회 위원장은 업무수행과 관련된 조사 등 노동위원회의 원활한 운영을 위하여 필요한 경우 노동위원회가 설치된 위치 외의 장소에서 부문별 위원회를 소집하게 할 수 있다.","w":"조사 등 원활한 운영에 필요하면 노동위원회가 설치된 곳 밖에서도 부문별 위원회를 소집하게 할 수 있다(노동위원회법 제16조 제4항).","c":"상","v":1},"공인노2025_34-75-5":{"f":"부문별 위원회 회의는 구성위원 전원의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.","w":"부문별 위원회는 구성위원 전원이 출석해야 회의를 열고 출석위원 과반수 찬성으로 의결한다(노동위원회법 제17조 제2항). 재적 과반수 출석으로 여는 것은 전원회의다.","c":"상","v":1},"공인노2025_34-76-5":{"f":"노동위원회 위원장 또는 상임위원이 궐위(闕位)되어 후임자를 임명한 경우 후임자의 임기는 새로 시작된다.","w":"일반 위원의 보궐 임기는 전임자의 남은 기간이지만, 위원장이나 상임위원의 후임자는 임기가 새로 시작된다(노동위원회법 제7조 제2항 단서).","c":"상","v":1},"공인노2026_35-70-4":{"f":"특별노동위원회는 관계 법률에서 정하는 사항을 관장하기 위하여 필요한 경우에 해당 사항을 관장하는 중앙행정기관의 장 소속으로 둔다.","w":"특별노동위원회는 그 사항을 관장하는 중앙행정기관의 장 소속이다(노동위원회법 제2조 제3항). 예로 선원노동위원회는 해양수산부장관 소속이다.","c":"상","v":1},"공인노2026_35-73-5":{"f":"「노동위원회법」에 따라 작성된 화해조서는 「민사소송법」에 따른 재판상 화해의 효력을 갖는다.","w":"노동위원회 화해조서는 민사소송법상 재판상 화해와 같은 효력이 있다(노동위원회법 제16조의3 제5항).","c":"상","v":1},"공인노2017_26-47-5":{"f":"근로자와 사용자를 대표하는 같은 수의 위원으로 구성하되, 각 3명 이상 10명 이하로 한다.","w":"노사협의회는 노사 같은 수로 각 3명 이상 10명 이하로 구성한다(근로자참여법 제6조 제1항). 근로자위원에 여성근로자를 반드시 1명 이상 넣으라는 규정은 없다.","c":"상","v":1},"공인노2022_31-50-5":{"f":"근로조건 기타 노사관계에 관한 합의가 노사협의회의 협의를 거쳐서 단체협약의 실질적 ㆍ형식적 요건을 갖추었다면 이는 단체협약이라고 볼 수 있다.","w":"판례는 노사협의회를 거친 합의라도 단체협약의 실질적·형식적 요건을 갖추면 단체협약으로 본다.","c":"상","v":1},"공인노2024_33-65-3":{"f":"노사협의회는 그 조직과 운영에 관한 규정을 제정하고 노사협의회를 설치한 날부터 15일 이내에 고용노동부장관에게 제출하여야 한다.","w":"협의회규정 제출 기한은 설치한 날부터 15일이다(근로자참여법 제18조 제1항).","c":"상","v":1},"공인노2024_33-66-4":{"f":"사용자가 정당한 사유 없이 제11조(시정명령)에 따른 시정명령을 이행하지 아니하면 500만원 이하의 벌금에 처한다.","w":"근로자위원 불이익 처분·선출 개입에 대한 시정명령을 정당한 사유 없이 이행하지 않으면 500만원 이하 벌금이다(근로자참여법 제31조). 1천만원 이하 벌금은 협의회 설치 거부·방해, 의결사항 불이행, 중재결정 불이행이다(제30조).","c":"상","v":1},"공인노2024_33-72-2":{"f":"고충처리위원은 노사를 대표하는 3명 이내의 위원으로 구성한다.","w":"고충처리위원은 3명 이내다(근로자참여법 제27조 제1항).","c":"상","v":1},"공인노2024_33-72-3":{"f":"고충처리위원은 근로자로부터 고충사항을 청취한 경우에는 10일 이내에 조치 사항과 그 밖의 처리결과를 해당 근로자에게 통보하여야 한다.","w":"고충 처리결과 통보 기한은 10일이다(근로자참여법 제28조 제1항).","c":"상","v":1},"공인노2024_33-72-4":{"f":"고충처리위원은 임기가 끝난 경우라도 후임자가 선출될 때까지 계속 그 직무를 담당한다.","w":"고충처리위원 임기는 노사협의회 위원과 같이 3년이고, 임기가 끝나도 후임자가 선출될 때까지 직무를 계속한다(근로자참여법 제27조 제2항, 제8조).","c":"상","v":1},"공인노2024_33-72-5":{"f":"상시 30명 이상의 근로자를 사용하는 사업 또는 사업장에는 근로자의 고충을 청취하고 이를 처리하기 위하여 고충처리위원을 두어야 한다.","w":"고충처리위원 설치 의무는 상시 30명 이상 사업장에만 있다(근로자참여법 제26조).","c":"상","v":1},"공인노2025_34-67-5":{"f":"근로자를 대표하는 위원의 결원이 생기면 30일 이내에 보궐위원을 위촉하거나 선출한다.","w":"근로자위원 결원은 30일 이내에 보궐위원을 위촉하거나 선출해 채운다(근로자참여법 시행령 제4조).","c":"상","v":1},"공인노2025_34-70-1":{"f":"“노사협의회”란 근로자와 사용자가 참여와 협력을 통하여 근로자의 복지증진과 기업의 건전한 발전을 도모하기 위하여 구성하는 협의기구를 말한다.","w":"노동3권을 보장해 근로조건 유지·개선을 꾀하는 것은 노조법의 목적이다. 노사협의회는 참여와 협력으로 근로자 복지증진과 기업의 건전한 발전을 꾀하는 기구다(근로자참여법 제3조).","c":"상","v":1},"공인노2025_34-70-2":{"f":"“근로자”란 「근로기준법」 제2조에 따른 근로자를 말한다.","w":"근로자참여법의 근로자는 근로기준법상 근로자다(근로자참여법 제3조).","c":"상","v":1},"공인노2025_34-70-3":{"f":"노사협의회는 상시(常時) 30명 이상의 근로자를 사용하는 근로조건에 대한 결정권이 있는 사업이나 사업장 단위로 설치하여야 한다.","w":"설치 의무는 상시 30명 이상 사업장에 있다(근로자참여법 제4조 제1항).","c":"상","v":1},"공인노2025_34-70-5":{"f":"노사 쌍방은 회의 결과의 기록 등 사무를 담당하는 간사 1명을 각각 둔다.","w":"간사는 위원 중에서 1명을 뽑는 것이 아니라 노사가 각각 1명씩 둔다(근로자참여법 제7조 제3항).","c":"상","v":1},"공인노2025_34-71-2":{"f":"노사협의회 위원의 임기는 3년으로 하되, 연임할 수 있다.","w":"위원 임기는 3년이고 연임할 수 있다(근로자참여법 제8조 제1항).","c":"상","v":1},"공인노2026_35-66-2":{"f":"회의는 근로자위원과 사용자위원 각 과반수의 출석으로 개최하고 출석위원 3분의 2 이상의 찬성으로 의결한다.","w":"노사협의회 의결은 출석위원 3분의 2 이상 찬성이 필요하다(근로자참여법 제15조).","c":"상","v":1},"공인노2026_35-68-5":{"f":"고충처리위원은 노사협의회가 설치되어 있지 아니한 사업이나 사업장의 경우에는 사용자가 위촉한다.","w":"노사협의회가 있으면 협의회가 위원 중에서 선임하고, 없으면 사용자가 위촉한다(근로자참여법 제27조 제1항).","c":"상","v":1},"공인노2017_26-48-1":{"f":"교원은 시ㆍ도 단위 또는 전국 단위로 노동조합을 설립할 수 있다.","w":"출제 당시에도 교원 노조는 시·도 단위나 전국 단위로 설립할 수 있었다. 현행법은 유아·초중등 교원은 시·도 또는 전국 단위로, 고등교육법상 교원은 개별학교 단위로도 설립할 수 있게 한다(교원노조법 제4조).","c":"상","v":1},"공인노2017_26-48-2":{"f":"노동조합을 설립하려는 사람은 고용노동부장관에게 설립신고서를 제출해야 한다.","w":"교원 노조의 설립신고는 고용노동부장관에게 한다(교원노조법 제4조).","c":"상","v":1},"공인노2017_26-48-3":{"f":"교원은 임용권자의 동의를 받아 노동조합의 업무에만 종사할 수 있다.","w":"전임 승인 주체는 교육부장관이 아니라 임용권자다. 출제 당시에는 임용권자의 허가였고, 현행법은 임용권자의 동의를 받아 노동조합으로부터 급여를 받으며 노조 업무에만 종사할 수 있게 한다(교원노조법 제5조 제1항).","c":"상","v":1},"공인노2017_26-48-5":{"f":"교원 노동관계 조정위원회는 중앙노동위원회 위원장이 지명하는 조정담당 공익위원 3명으로 구성된다.","w":"교원 노동관계 조정위원회는 중앙노동위원회 위원장이 지명하는 조정담당 공익위원 3명으로 구성한다. 당사자가 합의해 조정담당 공익위원이 아닌 사람을 추천하면 그 사람을 지명한다(교원노조법 제11조 제2항).","c":"상","v":1},"공인노2017_26-49-2":{"f":"노동조합은 단체교섭을 위하여 노동조합의 조합원 외의 자를 교섭위원으로 구성할 수 없다.","w":"공무원 노조는 단체교섭을 위해 노동조합의 대표자와 조합원으로 교섭위원을 구성해야 한다(공무원노조법 제9조 제1항).","c":"상","v":1},"공인노2019_28-49-1":{"f":"노동조합은 어떠한 정치활동도 하여서는 아니 된다.","w":"교원 노조는 목적과 관계없이 일체의 정치활동이 금지된다(교원노조법 제3조).","c":"상","v":1},"공인노2019_28-49-2":{"f":"노동조합을 설립하려는 사람은 고용노동부장관에게 설립신고서를 제출하여야 한다.","w":"교원 노조 설립신고처는 고용노동부장관이다(교원노조법 제4조).","c":"상","v":1},"공인노2019_28-49-3":{"f":"노동조합과 그 조합원은 파업, 태업 또는 그 밖에 업무의 정상적인 운영을 방해하는 어떠한 쟁의행위도 하여서는 아니 된다.","w":"교원 노조는 파업뿐 아니라 태업 등 모든 쟁의행위가 금지된다(교원노조법 제8조).","c":"상","v":1},"공인노2019_28-49-5":{"f":"단체교섭이 결렬된 경우에는 당사자 어느 한쪽 또는 양쪽은 중앙노동위원회에 조정을 신청할 수 있고, 조정은 신청을 받은 날부터 30일 이내에 마쳐야 한다.","w":"교원 노동쟁의 조정은 신청을 받은 날부터 30일 이내에 마쳐야 한다(교원노조법 제9조 제3항).","c":"상","v":1},"공인노2019_28-50-5":{"f":"정부교섭대표는 효율적인 교섭을 위하여 필요한 경우 관계 기관의 장을 교섭에 참여하게 할 수 있다.","w":"관계 기관의 장을 교섭에 참여하게 하는 것은 필요할 때 할 수 있는 재량이다(공무원노조법 제8조 제4항).","c":"상","v":1},"공인노2022_31-48-1":{"f":"정부교섭대표는 다른 정부교섭대표와 공동으로 교섭하거나, 다른 정부교섭대표에게 교섭 및 단체협약 체결 권한을 위임할 수 있다.","w":"정부교섭대표는 공동교섭도, 교섭·체결 권한의 위임도 할 수 있다(공무원노조법 제8조 제3항).","c":"상","v":1},"공인노2022_31-49-1":{"f":"고등교육법에 따른 교원은 개별학교 단위로 노동조합을 설립할 수 있다.","w":"개별학교 단위 설립은 고등교육법상 교원만 할 수 있다. 유아·초중등 교원은 시·도 단위나 전국 단위로 설립한다(교원노조법 제4조).","c":"상","v":1},"공인노2022_31-49-2":{"f":"교원으로 임용되어 근무하였던 사람은 규약에 정함이 있으면 노동조합에 가입할 수 있다.","w":"교원으로 임용되어 근무했던 사람도 노동조합 규약으로 정하면 교원 노조에 가입할 수 있다(교원노조법 제4조의2 제2호).","c":"상","v":1},"공인노2022_31-49-3":{"f":"노동조합과 그 조합원은 파업, 태업 또는 그 밖에 업무의 정상적인 운영을 방해하는 어떠한 쟁의행위도 하여서는 아니 된다.","w":"교원 노조의 쟁의행위는 전면 금지된다(교원노조법 제8조).","c":"상","v":1},"공인노2022_31-49-5":{"f":"교원은 임용권자의 동의를 받아 노동조합으로부터 급여를 지급받으면서 노동조합의 업무에만 종사할 수 있다.","w":"전임자는 임용권자의 동의를 받아 노동조합으로부터 급여를 받는다(교원노조법 제5조 제1항). 출제 당시 법은 임용권자의 허가를 받게 하고 전임기간 중 봉급을 받지 못한다고 정했는데, 2022년 개정으로 지금 문언으로 바뀌었다.","c":"상","v":1},"공인노2024_33-73-3":{"f":"교원의 노동조합과 그 조합원은 파업, 태업 또는 그 밖에 업무의 정상적인 운영을 방해하는 어떠한 쟁의행위도 하여서는 아니 된다.","w":"교원노조법이 금지하는 것은 쟁의행위다(제8조). 이 법은 노동운동 등 집단행위를 금지하는 「국가공무원법」 제66조 제1항에도 불구하고 교원 노조의 설립과 활동을 인정한다(교원노조법 제1조).","c":"상","v":1},"공인노2024_33-74-2":{"f":"「고등교육법」에 따른 교원에 대해서는 개별학교 단위를 기준으로 근무시간 면제 한도를 심의ㆍ의결한다.","w":"근무시간 면제 한도는 유아·초중등 교원은 시·도 단위, 고등교육법상 교원은 개별학교 단위를 기준으로 심의·의결한다(교원노조법 제5조의2 제3항).","c":"상","v":1},"공인노2024_33-75-1":{"f":"교원은 공무원의 노동조합에 가입할 수 없으나, 교원이 아닌 교육공무원은 가입할 수 있다.","w":"공무원 노조 가입 대상에는 교육공무원이 들어가고, 그중 교원만 빠진다(공무원노조법 제6조 제1항 제2호).","c":"상","v":1},"공인노2024_33-75-3":{"f":"교정ㆍ수사 등 공공의 안녕과 국가안전보장에 관한 업무에 종사하는 공무원은 공무원의 노동조합에 가입할 수 없다.","w":"교정·수사 등 공공 안녕과 국가안전보장 업무 종사자는 공무원 노조 가입이 제한된다(공무원노조법 제6조 제2항).","c":"상","v":1},"공인노2024_33-75-4":{"f":"공무원의 노동조합이 있는 경우에도 공무원이 공무원직장협의회를 설립ㆍ운영할 수 있다.","w":"공무원노조법은 공무원직장협의회의 설립·운영을 막지 않는다(제17조 제1항).","c":"상","v":1},"공인노2024_33-75-5":{"f":"공무원은 임용권자의 동의를 받아 노동조합으로부터 급여를 지급받으면서 노동조합의 업무에만 종사할 수 있으며, 임용권자는 그 기간 중 휴직명령을 하여야 한다.","w":"공무원 전임자에게는 「국가공무원법」 제71조나 「지방공무원법」 제63조에 따라 휴직명령을 해야 한다(공무원노조법 제7조 제2항). 휴직명령을 받은 것으로 보는 규정은 교원노조법(제5조 제2항)에 있다.","c":"상","v":1},"공인노2024_33-76-1":{"f":"","w":"공무원노조법은 개별교섭만 인정하지 않는다. 정부교섭대표의 공동교섭과 권한 위임, 복수노조의 교섭창구 단일화도 정해 두었다(공무원노조법 제8조, 제9조).","c":"상","v":1},"공인노2024_33-77-1":{"f":"단체교섭이 결렬된 경우 이를 조정ㆍ중재하기 위하여 중앙노동위원회에 공무원 노동관계 조정위원회를 둔다.","w":"공무원 노동쟁의는 중앙노동위원회의 공무원 노동관계 조정위원회가 조정·중재한다(공무원노조법 제14조). 특별조정위원회는 노조법상 공익사업 조정 기구다.","c":"상","v":1},"공인노2024_33-77-2":{"f":"공무원 노동관계 조정위원회 전원회의에서 중재에 회부한다는 결정을 하는 경우 지체 없이 중재를 한다.","w":"공무원 노조의 중재 개시 사유는 양쪽이 함께 신청한 경우와 공무원 노동관계 조정위원회 전원회의에서 중재 회부를 결정한 경우다. 중앙노동위원회 위원장의 직권 회부는 교원노조법에 있는 사유다(공무원노조법 제13조).","c":"상","v":1},"공인노2024_33-77-3":{"f":"관계 당사자는 중앙노동위원회의 중재재정이 위법하거나 월권에 의한 것이라고 인정하는 경우에는 중재재정서를 송달받은 날부터 15일 이내에 중앙노동위원회 위원장을 피고로 하여 행정소송을 제기할 수 있다.","w":"중재재정에 대한 행정소송 기간은 송달받은 날부터 15일이다(공무원노조법 제16조 제1항).","c":"상","v":1},"공인노2024_33-77-5":{"f":"중앙노동위원회의 중재재정에 대한 행정소송이 제기되더라도 중재재정의 효력은 정지되지 아니한다.","w":"행정소송을 내도 중재재정의 효력은 정지되지 않는다(공무원노조법 제16조 제4항).","c":"상","v":1},"공인노2024_33-78-1":{"f":"","w":"공정대표의무(노조법 제29조의4)는 공무원노조법과 교원노조법이 적용을 배제하는 노조법 조항이다(공무원노조법 제17조 제3항, 교원노조법 제14조 제2항).","c":"상","v":1},"공인노2024_33-78-3":{"f":"","w":"조정의 전치(노조법 제45조)는 공무원·교원 노조에 적용되지 않는 조항이다(공무원노조법 제17조 제3항, 교원노조법 제14조 제2항). 두 노조는 쟁의행위 자체가 금지되어 있다.","c":"상","v":1},"공인노2024_33-78-4":{"f":"","w":"사적 조정·중재(노조법 제52조)는 공무원·교원 노조에 적용되지 않는다(공무원노조법 제17조 제3항, 교원노조법 제14조 제2항). 이들의 조정·중재는 중앙노동위원회의 전담 조정위원회가 맡는다.","c":"상","v":1},"공인노2024_33-78-5":{"f":"","w":"긴급조정(노조법 제76조)은 공무원·교원 노조에 적용되지 않는다(공무원노조법 제17조 제3항, 교원노조법 제14조 제2항).","c":"상","v":1},"공인노2024_33-79-5":{"f":"교섭노동조합이 둘 이상인 경우 교섭창구 단일화 합의가 이루어지지 않으면 교섭노동조합의 조합원 수에 비례하여 교섭위원을 선임한다.","w":"교원 노조는 합의가 안 되면 과반수 노조가 교섭대표가 되는 방식이 아니라, 각 교섭노동조합의 조합원 수에 비례해 교섭위원을 선임한다(교원노조법 시행령 제3조의2 제3항).","c":"상","v":1},"공인노2024_33-80-2":{"f":"","w":"교원노조법에는 단독조정인 제도가 없다. 노조법의 단독조정 규정(제57조)은 교원 노조에 적용되지 않고, 조정은 교원 노동관계 조정위원회가 맡는다(교원노조법 제14조 제2항).","c":"상","v":1},"공인노2024_33-80-3":{"f":"조정은 신청을 받은 날부터 30일 이내에 마쳐야 한다.","w":"교원 노동쟁의 조정은 30일 이내에 마쳐야 하고, 합의로 연장하는 규정은 없다(교원노조법 제9조 제3항). 30일 이내 연장 단서는 공무원노조법 제12조 제4항에 있다.","c":"상","v":1},"공인노2024_33-80-4":{"f":"관계 당사자 쌍방이 함께 중재를 신청한 때 중앙노동위원회는 중재를 한다.","w":"교원 노조의 중재 개시 사유는 쌍방이 함께 신청한 경우, 조정안을 어느 한쪽이라도 거부한 경우, 중앙노동위원회 위원장의 회부 결정이다. 단체협약에 따른 일방 신청은 사유가 아니다(교원노조법 제10조).","c":"상","v":1},"공인노2024_33-80-5":{"f":"중앙노동위원회 위원장은 직권으로 중재에 회부한다는 결정을 할 수 있다.","w":"중앙노동위원회 위원장은 직권으로 또는 고용노동부장관의 요청으로 중재 회부를 결정할 수 있다(교원노조법 제10조).","c":"상","v":1},"공인노2025_34-77-4":{"f":"단체교섭이 결렬되어 관계 당사자 양쪽이 함께 중재를 신청한 경우 중앙노동위원회는 지체 없이 중재(仲裁)를 한다.","w":"공무원 노조의 중재는 양쪽이 함께 신청해야 개시된다. 한쪽 신청만으로는 안 된다(공무원노조법 제13조).","c":"상","v":1},"공인노2025_34-78-5":{"f":"노동조합을 설립하려는 사람은 고용노동부장관에게 설립신고서를 제출하여야 한다.","w":"교원 노조 설립신고처는 고용노동부장관이다(교원노조법 제4조).","c":"상","v":1},"공인노2025_34-79-2":{"f":"교원의 노동쟁의를 조정·중재하기 위하여 중앙노동위원회에 교원 노동관계 조정 위원회를 둔다.","w":"교원 노동관계 조정위원회는 중앙노동위원회에만 둔다(교원노조법 제11조 제1항).","c":"상","v":1},"공인노2025_34-79-3":{"f":"관계당사자는 중재재정서를 송달받은 날부터 15일 이내에 행정소송을 제기할 수 있다.","w":"중재재정이 위법·월권이면 중재재정서를 송달받은 날부터 15일 이내에 행정소송을 낼 수 있다(교원노조법 제12조 제1항).","c":"상","v":1},"공인노2025_34-79-4":{"f":"중앙노동위원회 위원장은 직권으로 중재에 회부한다는 결정을 할 수 있다.","w":"교원 노조 사건에서는 중앙노동위원회 위원장이 직권으로 또는 고용노동부장관의 요청으로 중재 회부를 결정할 수 있다(교원노조법 제10조).","c":"상","v":1},"공인노2025_34-79-5":{"f":"확정된 중재재정은 관계당사자를 구속하며 단체협약과 같은 효력을 가진다.","w":"중재재정은 당사자 수락 없이 확정되면 단체협약과 같은 효력을 가진다(교원노조법 제12조).","c":"상","v":1},"공인노2025_34-80-1":{"f":"공무원 노동조합이 있는 경우에도 공무원이 공무원직장협의회를 설립ㆍ운영할 수 있다.","w":"공무원노조법은 직장협의회의 설립·운영을 막지 않는다(제17조 제1항).","c":"상","v":1},"공인노2025_34-80-3":{"f":"공무원은 근무시간 면제한도를 초과하지 아니하는 범위에서 보수의 손실 없이 정부교섭대표와의 협의ㆍ교섭, 고충처리, 안전·보건활동 등 업무를 할 수 있다.","w":"보수 손실 없이 노조 업무를 할 수 있는 범위는 근무시간 면제 한도 안이다(공무원노조법 제7조의2 제1항).","c":"상","v":1},"공인노2025_34-80-4":{"f":"근무시간 면제심의위원회는 근무시간 면제 한도를 심의·의결하고 3년마다 그 적정성 여부를 재심의하여 의결할 수 있다.","w":"재심의 주기는 3년이고, 재심의는 할 수 있는 것이지 의무가 아니다(공무원노조법 제7조의2 제3항).","c":"상","v":1},"공인노2025_34-80-5":{"f":"정부교섭대표는 전년도에 노동조합별로 근무시간을 면제받은 시간 및 사용인원, 지급된 보수 등에 관한 정보를 대통령령으로 정하는 바에 따라 공개하여야 한다.","w":"정부교섭대표는 근무시간 면제 사용 정보를 국회에 보고하는 것이 아니라 국민이 알 수 있도록 공개해야 한다(공무원노조법 제7조의3).","c":"상","v":1},"공인노2026_35-74-1":{"f":"","w":"공무원 노동관계 조정위원회는 단체교섭이 결렬된 경우의 조정·중재를 맡는다. 부당노동행위 구제신청은 일반 노동위원회의 심판 절차에서 다룬다.","c":"중","v":1},"공인노2026_35-74-2":{"f":"행정안전부 공무원으로부터 구제신청을 받았을 때에는 노동위원회는 지체 없이 그 사실을 상대방인 행정관청과 소관 소청심사위원회에 알려야 한다.","w":"공무원이나 공무원 노조의 부당노동행위 구제신청을 받은 노동위원회는 그 사실을 상대방인 행정관청과 소관 소청심사위원회에 알린다. 고용노동부장관에게 알리는 규정은 없다(공무원노조법 시행령 제13조).","c":"상","v":1},"공인노2026_35-74-3":{"f":"","w":"유니언 숍 예외(노조법 제81조 제1항 제2호 단서)는 공무원노조법이 적용을 배제한다. 공무원 노조와 이런 단체협약을 맺으면 부당노동행위가 된다(공무원노조법 제17조 제3항).","c":"상","v":1},"공인노2026_35-74-5":{"f":"","w":"확정된 구제명령 위반을 처벌하는 노조법 벌칙(제88조~제92조)은 공무원 노조에 적용되지 않는다(공무원노조법 제17조 제3항).","c":"상","v":1},"공인노2026_35-75-1":{"f":"","w":"공무원노조법에는 단독조정인 제도가 없다. 노조법의 단독조정 규정(제57조)은 공무원 노조에 적용되지 않고, 조정은 공무원 노동관계 조정위원회가 한다(공무원노조법 제17조 제3항).","c":"상","v":1},"공인노2026_35-75-2":{"f":"공무원 노동관계 조정위원회 위원은 공무원 노동관계의 조정ㆍ중재를 전담하는 중앙노동위원회의 공익위원으로 구성한다.","w":"공무원 노동관계 조정위원회는 노·사·공익 3자 구성이 아니라 공무원 노동관계의 조정·중재를 전담하는 7명 이내의 공익위원으로 구성한다(공무원노조법 제14조 제2항).","c":"상","v":1},"공인노2026_35-75-3":{"f":"공무원 노동관계 조정위원회 전원회의에서 중재에 회부한다는 결정을 한 경우 중앙노동위원회는 지체 없이 중재를 한다.","w":"조정안 거부만으로 중재가 개시되는 것은 교원 노조다. 공무원 노조는 양쪽이 함께 신청하거나 전원회의가 중재 회부를 결정해야 중재한다(공무원노조법 제13조).","c":"상","v":1},"공인노2026_35-75-5":{"f":"관계당사자는 중앙노동위원회의 중재재정이 위법하거나 월권에 의한 것이라고 인정하는 경우에는 행정소송을 제기할 수 있다.","w":"행정소송은 중재재정이 위법한 경우뿐 아니라 월권인 경우에도 낼 수 있다(공무원노조법 제16조 제1항).","c":"상","v":1},"공인노2026_35-76-5":{"f":"","w":"단체협약 위반을 처벌하는 노조법 제92조는 공무원 노조에 적용되지 않는다(공무원노조법 제17조 제3항).","c":"상","v":1},"공인노2026_35-77-2":{"f":"교섭노동조합이 둘 이상인 경우 자율적 합의로 교섭창구를 단일화하지 못하면 교섭노동조합의 조합원 수에 비례하여 교섭위원을 선임한다.","w":"교원 노조는 합의가 안 되면 각 교섭노동조합의 조합원 수에 비례해 교섭위원을 선임한다. 과반수 노조를 교섭대표로 하는 노조법 방식은 쓰지 않는다(교원노조법 시행령 제3조의2 제3항).","c":"상","v":1},"공인노2026_35-78-2":{"f":"임용권자는 근무시간면제자가 업무 외의 목적으로 근무시간 면제 시간을 사용하는 경우 해당 근무시간면제자의 변경을 노동조합의 대표자에게 요청할 수 있다.","w":"근무시간면제자 변경 요청은 교원근무시간면제심의위원회가 아니라 노동조합의 대표자에게 하고, 대표자는 특별한 사정이 없으면 따라야 한다(교원노조법 시행령 제2조의3 제4항).","c":"상","v":1},"공인노2026_35-78-3":{"f":"「고등교육법」에 따른 교원이 개별학교 단위로 노동조합을 설립할 경우 고용노동부장관에게 설립신고서를 제출하여야 한다.","w":"교원 노조는 단위와 관계없이 고용노동부장관에게 설립신고를 한다(교원노조법 제4조).","c":"상","v":1},"공인노2026_35-78-4":{"f":"교원은 임용권자의 동의를 받아 노동조합으로부터 급여를 지급받으면서 노동조합의 업무에만 종사할 수 있다.","w":"전임자의 급여는 노동조합이 준다. 임용권자에게서 보수를 받으며 노조 일을 하는 것은 근무시간 면제 한도 안에서만 된다(교원노조법 제5조, 제5조의2).","c":"상","v":1},"공인노2026_35-78-5":{"f":"교원으로 임용되어 근무하였던 사람은 노동조합 규약으로 정하면 교원의 노동조합에 가입할 수 있다.","w":"교원으로 임용되어 근무했던 사람도 노동조합 규약으로 정하면 교원 노조에 가입할 수 있다(교원노조법 제4조의2 제2호).","c":"상","v":1},"공인노2026_35-79-4":{"f":"교원 노동관계 조정위원회 위원은 중앙노동위원회 위원장이 조정담당 공익위원 중에서 지명한다.","w":"교원 노동관계 조정위원회 위원은 중앙노동위원회 위원장이 조정담당 공익위원 중에서 3명을 지명한다(교원노조법 제11조 제2항). 중앙노동위원회 위원장의 추천과 고용노동부장관의 제청으로 대통령이 위촉하는 방식은 공무원 노동관계 조정위원회 공익위원의 위촉 절차다(공무원노조법 제14조 제3항).","c":"중","v":1},"공인노2017_26-27-3":{"f":"","w":"(1948 제헌헌법 개정 전 기준 X. 현행 헌법 제32조 제1항에는 국가의 고용 증진 노력 의무가 들어 있다.) 이 문항은 1948년 제헌헌법의 근로 조항을 물었다. 근로조건 법정, 여자·소년 근로 보호, 근로3권, 사기업 근로자의 이익분배 균점권은 제헌헌법에 있었고, 고용 증진 노력 의무는 뒤의 개헌에서 들어왔다.","c":"중","v":1,"old":1,"ow":"(1948 제헌헌법 개정 전 기준 X. 현행 헌법 제32조 제1항에는 국가의 고용 증진 노력 의무가 들어 있다.) 이 문항은 1948년 제헌헌법의 근로 조항을 물었다. 근로조건 법정, 여자·소년 근로 보호, 근로3권, 사기업 근로자의 이익분배 균점권은 제헌헌법에 있었고, 고용 증진 노력 의무는 뒤의 개헌에서 들어왔다."},"공인노2019_28-27-5":{"f":"근로자는 근로조건의 향상을 위하여 자주적인 단결권ㆍ단체교섭권 및 단체행동권을 가진다.","w":"노동3권의 주체는 모든 국민이 아니라 근로자다(헌법 제33조 제1항).","c":"상","v":1},"공인노2022_31-26-5":{"f":"헌법재판소는 노동3권 제한에 관한 개별적 제한규정을 두고 있지 않는 경우에도, 헌법 제37조제2항의 일반유보조항에 따라 노동3권을 제한할 수 있다는 입장을 취하고 있다.","w":"헌법재판소는 개별 제한규정이 없어도 노동3권을 헌법 제37조 제2항에 따라 법률로 제한할 수 있다고 본다.","c":"상","v":1},"공인노2024_33-41-1":{"f":"1963년 개정된 「노동조합법」에는 복수노조 금지조항이 있었다.","w":"1953년 제정 노동조합법에는 복수노조 금지조항이 없었다. 복수노조 금지는 1963년 개정 때 들어왔다.","c":"중","v":1},"공인노2024_33-42-3":{"f":"근로자의 단결하지 않을 자유, 즉 소극적 단결권보다 노동조합의 적극적 단결권이 중시된다는 것이 헌법재판소의 입장이다.","w":"헌법재판소는 소극적 단결권을 단결권이 아닌 일반적 행동자유나 결사의 자유에서 찾고, 노동조합의 적극적 단결권을 더 중시한다.","c":"상","v":1},"공인노2025_34-41-3":{"f":"단체교섭권은 단체교섭을 행할 권한뿐만 아니라 교섭한 결과에 따라 단체협약을 체결할 권한도 포함한다.","w":"헌법재판소는 헌법에 명시되지 않았어도 단체교섭권에 단체협약체결권이 들어 있다고 본다.","c":"상","v":1},"공인노2026_35-80-3":{"f":"근로3권은 법률의 제정이 없더라도 헌법의 규정만으로 직접 법규범으로서 효력을 발휘할 수 있는 구체적 권리이다.","w":"헌법재판소는 근로3권이 법률이 없어도 헌법 규정만으로 효력을 발휘하는 구체적 권리라고 본다.","c":"상","v":1},"공인노2017_26-26":{"w":"④ 헌법재판소는 단체교섭권에 단체협약 체결권이 포함된다고 본다(헌재 1998. 2. 27. 94헌바13 등). 교섭만 하고 협약을 맺지 못하면 교섭권이 의미를 잃기 때문이다.\n① 개인택시운전자는 자기 계산으로 영업하는 사업자여서 근로자가 아니다.\n② 헌법재판소는 단결하지 않을 자유(소극적 단결권)는 단결권이 아니라 일반적 행동의 자유나 결사의 자유에서 나온다고 본다.\n③ 노동조합법 제3조·제4조\n⑤ 헌법 제37조 제2항","c":"상","v":1},"공인노2017_26-39":{"w":"⑤ 제76조 제3항: 고용노동부장관은 긴급조정을 결정하면 지체 없이 공표하고 중앙노동위원회와 관계 당사자에게 통고한다. 통고 방식으로 서면을 요구하지 않는다.\n① 제31조 제1항 단체협약은 서면으로 작성한다.\n② 시행령 제17조 쟁의행위 일시·장소·참가인원·방법을 서면으로 신고한다.\n③ 제45조 제1항 노동쟁의 발생은 서면으로 통보한다.\n④ 제84조 제2항 판정·명령·결정은 서면으로 한다.","c":"상","v":1},"공인노2017_26-42":{"w":"ㄱ 벌칙 없음 제9조(차별대우 금지)를 위반해도 처벌 조항이 없다.\nㄴ 벌칙 있음 단체교섭 거부는 제81조 제1항 제3호 부당노동행위로 제90조에 따라 2년 이하 징역 또는 2천만원 이하 벌금.\nㄷ 벌칙 있음 단체협약 중 휴일 등에 관한 사항 위반은 제92조 제2호에 따라 1천만원 이하 벌금.\nㄹ 벌칙 있음 노동조합 명칭 사용 금지(제7조 제3항) 위반은 제93조에 따라 500만원 이하 벌금.","c":"상","v":1},"공인노2019_28-26":{"w":"제정 연도: 파견근로자법 1998년 2월, 교원노조법 1999년 1월, 공무원노조법 2005년 1월, 기간제법 2006년 12월.\nㄱ → ㄹ → ㄷ → ㄴ","c":"상","v":1},"공인노2024_33-56":{"w":"③ 제37조 제3항(2021년 신설)은 사용자의 점유를 배제하여 조업을 방해하는 형태의 쟁의행위를 금지하지만 벌칙 규정이 없다.\n① 제37조 제2항 위반: 제89조 제1호(3년 이하 징역 또는 3천만원 이하 벌금)\n② 제7조 제3항 위반: 제93조(500만원 이하 벌금)\n④ 확정된 구제명령 위반: 제89조 제2호\n⑤ 제41조 제1항 위반: 제91조(1년 이하 징역 또는 1천만원 이하 벌금)","c":"상","v":1},"공인노2025_34-42":{"w":"ㄱ O 제19호(산재보상 내외국인 평등대우)는 2001년 비준했다.\nㄴ O 제87호는 2021년 비준, 2022년 발효\nㄷ O 제98호는 2021년 비준, 2022년 발효\nㄹ X 제105호(강제노동 철폐)는 비준하지 않았다. 2021년에는 강제근로 협약 제29호만 함께 비준했다.","c":"상","v":1},"공인노2017_26-28":{"w":"채무적 부분은 협약 당사자인 노동조합과 사용자 사이의 권리·의무를 정한 부분으로, 평화조항·숍조항·조합활동 조항·교섭 절차 조항 등이 여기에 든다.\n휴가, 승진·승급, 퇴직금, 재해보상은 개별 근로자의 근로조건을 정하는 규범적 부분이다.","c":"상","v":1},"공인노2019_28-38":{"w":"제92조 제2호의 처벌 대상은 단체협약 중 임금·복리후생비·퇴직금, 근로 및 휴게시간·휴일·휴가, 징계 및 해고의 사유와 중요한 절차, 안전보건 및 재해부조, 시설·편의제공 및 근무시간 중 회의참석, 쟁의행위에 관한 사항이다.\n조직강제(숍조항)에 관한 사항은 들어 있지 않다.","c":"상","v":1},"공인노2022_31-35":{"w":"ㄱ 2 시행령 제14조의10 제1항: 교섭대표노동조합은 첫 단체협약 효력 발생일부터 2년이 되는 날까지 지위를 유지한다.\nㄴ 6 제32조 제3항 단서: 자동연장 약정이 있어도 해지하려는 날의 6개월 전까지 통고하면 종전 협약을 해지할 수 있다.","c":"상","v":1},"공인노2017_26-29":{"w":"법외노조도 헌법상 단결체로서 단체교섭과 단체협약 체결은 할 수 있다.\nㄱ X, ㄴ X 법외노조에도 인정된다.\nㄷ O, ㄹ O 제7조 제1항: 노동조합법에 따라 설립된 노동조합이 아니면 노동위원회에 노동쟁의 조정과 부당노동행위 구제를 신청할 수 없다.\nㅁ O 제6조: 법인격 취득도 설립신고를 마친 노동조합만 할 수 있다.","c":"상","v":1},"공인노2019_28-29":{"w":"첫째 O 제7조 제1항\n둘째 O 제6조 제1항\n셋째 O 제7조 제3항\n넷째 X 제8조: 노동조합의 '사업체를 제외하고는' 조세를 부과하지 않는다. 사업체에는 과세한다.\n옳은 것은 3개.","c":"상","v":1},"공인노2017_26-30":{"w":"ㄱ 15 제18조 제4항: 소집권자가 없을 때 조합원·대의원 3분의 1 이상이 지명을 요구하면 행정관청은 15일 이내에 소집권자를 지명한다.\nㄴ 7 제19조: 총회·대의원회는 회의개최일 7일 전까지 부의사항을 공고하고 소집한다.","c":"상","v":1},"공인노2019_28-30":{"w":"제11조의 규약 기재사항은 명칭, 목적과 사업, 주된 사무소의 소재지, 조합원에 관한 사항, 소속 연합단체 명칭, 대의원회, 회의, 대표자와 임원, 조합비와 회계, 규약변경, 해산, 쟁의행위 찬반투표 결과 공개 등, 대표자·임원 탄핵, 임원·대의원 선거절차, 규율과 통제다.\n단체협약에 관한 사항은 없다.","c":"상","v":1},"공인노2022_31-27":{"w":"ㄱ 3 시행령 제6조: 법인 등기사항 변경은 3주 이내에 변경등기\nㄴ 20 시행령 제9조 제1항: 설립신고서 보완요구 기간은 20일 이내\nㄷ 1 제15조 제1항: 매년 1회 이상 총회 개최","c":"상","v":1},"공인노2022_31-29":{"w":"① 제21조 제3항: 시정명령을 받은 노동조합은 30일 이내에 이행해야 한다.\n②~⑤는 모두 15일이다.\n② 제18조 제4항: 소집권자가 없을 때 행정관청은 15일 이내에 소집권자를 지명한다.\n③ 제18조 제3항: 대표자가 소집을 기피·해태하면 행정관청은 15일 이내에 노동위원회의 의결을 요청한다.\n④ 제28조 제2항: 해산한 날부터 15일 이내 신고\n⑤ 제31조 제2항: 체결일부터 15일 이내 신고","c":"상","v":1},"공인노2025_34-46":{"w":"제11조 규약 기재사항에 대표자·임원의 규약위반 탄핵(제13호), 쟁의행위 찬반투표 결과 공개(제12호), 규율과 통제(제15호), 회의(제7호)가 있다.\n직장 내 괴롭힘 예방·조치는 근로기준법 제76조의2·제76조의3에서 사용자에게 지운 의무이고 규약 기재사항이 아니다.","c":"상","v":1},"공인노2025_34-48":{"w":"제12조 제3항의 반려 사유는 제2조 제4호 각 목(사용자 또는 항상 사용자의 이익을 대표하는 자의 참가 허용 등)에 해당하는 경우와, 보완요구를 받고도 기간 내에 보완하지 않은 경우 두 가지다.\n첫째 O, 넷째 O 반려 사유\n둘째·셋째·다섯째 X 허위 기재, 기재사항 누락, 규약 미첨부는 시행령 제9조 제1항의 보완요구 사유다.\n반려 사유는 2개.","c":"상","v":1},"공인노2026_35-41":{"w":"제13조 제1항의 30일 내 변경신고 사항은 명칭, 주된 사무소의 소재지, 대표자의 성명, 소속된 연합단체의 명칭이다.\n보기 중 주된 사무소, 소속 연합단체 명칭, 대표자 성명 3개가 해당한다.\n목적과 사업, 탄핵에 관한 사항은 규약 기재사항이고, 조합원수는 매년 1월 31일까지 통보하는 사항(제13조 제2항)이다.","c":"상","v":1},"공인노2017_26-31":{"w":"ㄱ X 특정 노동조합만 유일한 교섭주체로 인정하는 협약은 다른 노동조합의 단체교섭권을 침해하므로 무효다(판례).\nㄴ X 제29조 제3항·시행령 제14조: 교섭 권한을 위임할 때는 교섭사항과 권한 범위를 정해 위임하고 상대방에게 통보한다.\nㄷ X 대표자가 합의한 뒤에도 교섭위원 연명 서명이 없으면 협약을 체결할 수 없도록 한 규약은 대표자의 협약체결권을 전면적·포괄적으로 제한해 제29조 제1항에 위반된다(판례).\nㄹ O 위임 후에도 노동조합의 교섭권한은 수임자의 권한과 중복해 경합적으로 남는다(판례).","c":"상","v":1},"공인노2017_26-33":{"w":"ㄱ O 노동조합에 매월 상당한 금액을 주는 것은 제81조 제1항 제4호의 운영비 원조다.\nㄴ O 근로시간 면제자로 지정되지 않은 근로자에게 급여를 지원하는 것은 근로시간 면제 한도를 넘는 급여 지원이어서 부당노동행위다.\nㄷ X, ㄹ X 같은 호 단서: 최소한 규모의 노동조합사무소 제공, 근로자 후생자금·재해 구제 기금 기부는 허용된다.","c":"상","v":1},"공인노2022_31-45":{"w":"제81조 제2항의 고려 사항은 운영비 원조의 목적과 경위, 원조된 운영비 횟수와 기간, 금액과 원조방법, 원조된 운영비가 노동조합의 '총수입'에서 차지하는 비율, 관리방법 및 사용처다.\n기준은 총지출이 아니라 총수입이다.","c":"상","v":1},"공인노2024_33-51":{"w":"첫째 O 제82조 제1항\n둘째 O 제83조 제1항\n셋째 O 제81조 제1항 제1호\n넷째 O 제82조 제2항: 부당노동행위가 있은 날(계속하는 행위는 종료일)부터 3월 이내\n4개 모두 옳다.","c":"상","v":1},"공인노2026_35-46":{"w":"제81조 제2항의 고려 사항(운영비 원조의 목적과 경위, 횟수와 기간, 금액과 원조방법, 노동조합 총수입 대비 비율, 관리방법 및 사용처)에 ㄱ·ㄴ·ㄷ·ㄹ이 모두 들어 있다.","c":"상","v":1},"공인노2024_33-61":{"w":"ㄱ 7 제60조 제3항: 조정안의 해석·이행방법에 대한 견해는 요청받은 날부터 7일 이내 제시\nㄴ 15 제63조: 중재에 회부된 날부터 15일간 쟁의행위 금지\nㄷ 30 제77조: 긴급조정 공표일부터 30일이 지나야 쟁의행위 재개 가능","c":"상","v":1},"공인노2017_26-36":{"w":"③ 제42조의3: 필수유지업무협정은 서면으로 작성하고 쌍방이 서명 또는 날인한다.\n① 제89조 제1호: 3년 이하 징역 또는 3천만원 이하 벌금\n② 제42조의2 제1항: 필수공익사업의 업무 중 정지·폐지되면 공중의 생명·건강·신체의 안전이나 공중의 일상생활을 현저히 위태롭게 하는 업무로서 대통령령으로 정한 업무다. 국민경제 영향은 기준이 아니다.\n④ 제42조의4: 결정 신청은 노동위원회에 한다.\n⑤ 제42조의2 제2항: 정지·폐지하는 행위와 방해하는 행위 모두 금지된다.","c":"상","v":1},"공인노2017_26-43":{"w":"첫째 X 제37조 제2항: 조합원은 노동조합이 주도하지 않는 쟁의행위를 할 수 없다.\n둘째 O 제39조\n셋째 X 제42조 제3항: 행정관청은 노동위원회 의결을 얻어 중지를 통보한다. 의결 없이 즉시 통보할 수 있는 것은 사태가 급박한 경우뿐이다.\n넷째 X 단체협약에 파업기간 임금 지급 규정이 있으면 사용자는 그에 따라 지급할 의무가 있다. 제44조 제1항은 그런 약정이 없을 때의 원칙이다.\n다섯째 X 제41조 제2항: 주요방위산업체 근로자 중 전력·용수 및 주로 방산물자를 생산하는 업무에 종사하는 자만 쟁의행위가 금지된다.\n옳은 것은 1개.","c":"상","v":1},"공인노2017_26-44":{"w":"ㄱ 30 제13조 제1항: 명칭 등 변경은 30일 이내 변경신고\nㄴ 50 제43조 제4항: 필수공익사업 사용자는 파업참가자의 100분의 50을 넘지 않는 범위에서 대체근로·도급이 가능하다.","c":"상","v":1},"공인노2017_26-45":{"w":"제71조 제2항의 필수공익사업은 철도·도시철도, 항공운수, 수도·전기·가스·석유정제·석유공급, 병원, 혈액공급, 한국은행, 통신사업이다.\n조폐사업은 제71조 제1항의 공익사업일 뿐 필수공익사업이 아니다.","c":"상","v":1},"공인노2017_26-46":{"w":"시행령 제21조의 점거 금지 시설은 전기·전산·통신시설, 철도(도시철도 포함)의 차량·선로, 건조·수리·정박 중인 선박, 항공기·항행안전시설·항공기 이착륙 및 여객 승하선 시설, 화약·폭약 등 위험물 저장시설, 유해물질 저장·보관시설 등이다. 네 개 모두 해당한다.","c":"상","v":1},"공인노2022_31-39":{"w":"필수공익사업(제71조 제2항)은 철도·도시철도, 항공운수, 수도·전기·가스·석유정제·석유공급, 병원, 혈액공급, 한국은행, 통신이다.\nㄴ 통신 O, ㄹ 한국은행 O, ㅂ 병원 O\nㄱ 공중위생, ㄷ 방송, ㅁ 조폐는 공익사업(같은 조 제1항)에만 해당한다.","c":"상","v":1},"공인노2022_31-41":{"w":"시행령 제17조: 노동조합은 쟁의행위의 일시·장소·참가인원 및 그 방법을 미리 행정관청과 관할 노동위원회에 서면으로 신고한다. 목적은 신고 사항이 아니다.","c":"상","v":1},"공인노2024_33-64":{"w":"ㄱ 철도, ㄴ 수도는 필수공익사업이다.\nㄷ 공중위생, ㄹ 조폐, ㅁ 방송은 공익사업일 뿐 필수공익사업이 아니다.","c":"상","v":1},"공인노2019_28-47":{"w":"근로자참여법 제22조의 보고 사항은 경영계획 전반 및 실적, 분기별 생산계획과 실적, 인력계획, 기업의 경제적·재정적 상황이다.\n사내근로복지기금의 설치는 제21조의 의결 사항이다.","c":"상","v":1},"공인노2024_33-67":{"w":"② 근로자의 복지증진은 제20조 제1항의 협의 사항이다.\n① 인력계획은 제22조 보고 사항이다.\n③ 사내근로복지기금 설치, ④ 각종 노사공동위원회 설치, ⑤ 복지시설 설치와 관리는 제21조 의결 사항이다.","c":"상","v":1},"공인노2025_34-65":{"w":"시행령 제5조의 협의회규정 내용은 협의회 위원의 '수', 근로자위원 선출 절차와 후보 등록, 사용자위원의 자격, 회의 소집·회기 등 운영, 임의 중재의 방법·절차, 고충처리위원의 수와 고충처리 절차다.\n위원의 성명은 규정에 넣는 사항이 아니다.","c":"상","v":1},"공인노2025_34-74":{"w":"제21조의 의결 사항은 교육훈련·능력개발 기본계획 수립, 복지시설의 설치와 관리, 사내근로복지기금의 설치, 고충처리위원회에서 의결되지 아니한 사항, 각종 노사공동위원회의 설치다.\n③ 안전·보건 등 작업환경 개선과 근로자 건강증진은 제20조 협의 사항이다.","c":"상","v":1},"공인노2026_35-67":{"w":"② 인력계획은 제22조 보고 사항이다.\n① 생산성 향상과 성과 배분, ③ 근로자의 복지증진, ④ 신기계·기술 도입과 작업 공정 개선, ⑤ 인사·노무관리 제도 개선은 제20조 협의 사항이다.","c":"상","v":1},"공인노2026_35-69":{"w":"근로자참여법 제33조: 협의회 규정을 제출하지 않은 사용자(제18조 위반)에게는 200만원 이하의 과태료를 부과한다.","c":"상","v":1},"공인노2017_26-50":{"w":"① 노동위원회법 제3조 제2항: 둘 이상의 관할구역에 걸친 사건은 주된 사업장의 소재지를 관할하는 지방노동위원회가 관장한다. 신청인의 주소지가 기준이 아니다.\n② 제3조의2 사건 이송\n③ 제6조 제3항\n④ 제6조의2 사회취약계층 권리구제 대리\n⑤ 제8조 여성 위촉 노력","c":"상","v":1},"공인노2024_33-71":{"w":"노동위원회법 제21조 제1항의 제척 사유에 네 개 모두 있다.\nㄱ 당사자와 친족이거나 친족이었던 경우\nㄴ 해당 사건에 관하여 진술이나 감정을 한 경우\nㄷ 당사자의 대리인으로서 업무에 관여하거나 관여하였던 경우\nㄹ 위원 또는 위원이 속한 법인·단체·법률사무소가 사건의 원인이 된 처분·부작위에 관여한 경우","c":"상","v":1},"공인노2025_34-72":{"w":"노동위원회법 제8조 제2항 제1호 라목: 노동관계 업무에 '10년' 이상 종사한 사람으로서 4급 또는 4급 상당 이상의 공무원으로 재직한 사람이다. 4년이 아니다.\n① 가목(조교수 이상), ② 나목(판사·검사·군법무관·변호사·공인노무사 3년 이상), ③ 다목(3년 이상, 3급 이상 또는 고위공무원단), ⑤ 마목(노동관계 업무 10년 이상)은 법문 그대로다.","c":"상","v":1},"공인노2025_34-73":{"w":"노동위원회법 제2조의2의 소관 사무에 네 개 모두 있다.\nㄱ 노동조합법 등에 따른 판정·결정\nㄴ 노동쟁의 조정·중재\nㄷ 관계 당사자의 자주적인 노동쟁의 해결 지원\nㄹ 조정·중재 업무와 관련된 조사·연구·교육·홍보","c":"상","v":1},"공인노2026_35-71":{"w":"노동위원회법 시행령 제9조의2 제2항: 6급·7급 공무원으로서 고용노동부 또는 그 소속기관 근무 경력이 1년 미만이면 중앙노동위원회 위원장이 정하는 교육을 이수하거나 조사관의 직무를 보조하는 직위에서 6개월 이상 근무한 경력을 갖춰야 조사관이 될 수 있다.","c":"상","v":1},"공인노2026_35-72":{"w":"노동위원회법 제15조의3: 사건 처리와 관련하여 선정대표자, 당사자의 지위 승계, 대리인의 선임에 관하여는 행정심판법을 준용한다.\nㄱ O, ㄷ O, ㄹ O\nㄴ X 대리의 흠과 추인은 준용 대상에 없다.","c":"상","v":1},"공인노2017_26-32-1":{"w":"대법원 전원합의체 판례(2015년)는 취업자격 없는 외국인도 사용종속관계에서 근로를 제공하고 임금으로 생활하면 노조법상 근로자이고 노동조합을 결성·가입할 수 있다고 보았다. 출입국관리법상 취업제한은 취업 자체를 막는 규정이지 노동3권 주체성까지 부정하는 것은 아니다.","c":"중","v":1},"공인노2019_28-28-1":{"w":"노조법상 근로자는 노동3권 보장 필요성으로 판단하므로 일시적 실업자나 구직 중인 사람도 포함된다는 것이 대법원 판례다(서울여성노조 사건). 근로기준법상 근로자보다 넓은 개념이다.","c":"중","v":1},"공인노2019_28-28-2":{"w":"노조법 제2조 제1호의 근로자 정의 그대로다. 근로기준법과 달리 사용종속관계에서 현실로 근로를 제공하는지를 요건으로 하지 않는다.","c":"상","v":1},"공인노2019_28-28-4":{"w":"노조법 제2조 제2호의 「사업주를 위하여 행동하는 자」에 대해 판례는 인사·급여·후생·노무관리 등 근로조건 결정이나 업무상 지휘감독에 관하여 사업주로부터 일정한 권한과 책임을 부여받은 자를 말한다고 본다.","c":"중","v":1},"공인노2019_28-28-5":{"w":"대법원은 학습지교사 사건(2018년) 등에서 노조법상 근로자 여부를 노무제공관계의 실질과 노동3권 보장 필요성으로 판단하며 근로기준법상 근로자에 한정되지 않는다고 했다. 두 법의 입법목적이 다르기 때문이다.","c":"중","v":1},"공인노2025_34-58-1":{"w":"노조법 제7조 제3항에 따라 이 법에 의하여 설립된 노동조합만 노동조합이라는 명칭을 쓸 수 있다. 위반하면 제93조 제1호로 500만원 이하 벌금이다.","c":"상","v":1},"공인노2025_34-58-2":{"w":"노조법 제7조 제1항은 이 법에 의하여 설립된 노동조합이 아니면 노동쟁의 조정을 신청할 수 없다고 정하므로 설립신고를 마친 노동조합은 조정을 신청할 수 있다.","c":"상","v":1},"공인노2025_34-58-4":{"w":"노조법 제6조 제1항에 따라 노동조합은 규약이 정하는 바에 의하여 법인으로 할 수 있고 이때는 대통령령에 따라 등기해야 한다(같은 조 제2항).","c":"상","v":1},"공인노2025_34-58-5":{"w":"노조법 제7조 제1항과 제82조 제1항에 따라 이 법에 의하여 설립된 노동조합은 부당노동행위로 권리를 침해당하면 노동위원회에 구제를 신청할 수 있다.","c":"상","v":1},"공인노2026_35-49-1":{"w":"노조법 제2조 제4호의 실질적 요건(자주성·목적 등)을 갖추지 못한 단체는 설립신고가 수리되었더라도 노동조합의 지위를 갖지 못한다는 것이 대법원 판례다. 신고 수리는 실질적 요건 흠결을 치유하지 못한다.","c":"중","v":1},"공인노2026_35-49-2":{"w":"대법원 전원합의체 판례(2016년, 발레오만도 사건)는 산업별 노조의 지회라도 기업별 노조에 준하는 독립성이 있어 법인 아닌 사단으로 볼 수 있으면 노조법 제16조의 조직형태 변경 결의로 기업별 노조로 전환할 수 있다고 보았다.","c":"중","v":1},"공인노2026_35-49-4":{"w":"대법원은 노조법상 근로자 여부를 노무제공관계의 실질에 비추어 노동3권 보장 필요성이 있는지라는 관점에서 판단한다(학습지교사 사건 등). 노조법이 근로조건 개선을 위한 단결권 보장을 목적으로 하기 때문이다.","c":"중","v":1},"공인노2026_35-49-5":{"w":"대법원 전원합의체 판례(2020년, 전교조 사건)는 법외노조 통보가 노동3권을 실질적으로 제약하는 중대한 침익적 처분이므로 법률의 명확한 위임이 있어야 한다고 보고 시행령의 통보 규정을 무효로 판단했다.","c":"중","v":1},"공인노2017_26-41-3":{"w":"판례는 노조 전임자도 사용자와의 근로계약관계가 유지되므로 단체협약에 특별한 규정이나 관행이 없으면 출퇴근에 관한 사규의 적용을 받는다고 본다. 근로제공의무만 면제될 뿐이다.","c":"중","v":1},"공인노2017_26-41-4":{"w":"판례는 근로시간면제자에게 지급하는 급여가 근로제공의무가 면제되는 시간에 상응하는 것이어야 하고 타당한 근거 없이 과다하면 그 초과 부분은 노조 운영비 원조가 될 수 있다고 본다. 노조법 제24조 제2항은 면제자가 임금 손실 없이 업무를 수행하도록 정한다.","c":"중","v":1},"공인노2019_28-31-2":{"w":"노조법 제24조 제2항은 근로시간면제자가 한도 안에서 임금 손실 없이 노조 업무를 하도록 정하고 제81조 제1항 제4호는 한도를 초과한 급여 지급만 부당노동행위로 본다. 한도 내 급여 지급은 원칙적으로 부당노동행위가 아니다.","c":"상","v":1},"공인노2019_28-31-4":{"w":"노조법 제24조의2 제2항에 따라 근로시간면제심의위원회는 면제 한도를 심의·의결하고 3년마다 적정성 여부를 재심의하여 의결할 수 있다.","c":"상","v":1},"공인노2019_28-33-1":{"w":"판례는 사업장 내 조합활동이 정당하려면 취업규칙·단체협약에 별도 허용 규정이 없는 한 근무시간 외에 해야 하고 사용자의 시설관리권에 바탕을 둔 합리적 규율이나 제약에 따라야 한다고 본다.","c":"중","v":1},"공인노2019_28-33-2":{"w":"노조법 제81조 제1항 제1호의 「노동조합의 업무를 위한 정당한 행위」에 대해 판례는 그 목적이 근로조건 유지·개선과 경제적 지위 향상을 도모하기 위해 필요하고 단결 강화에 도움이 되는 것이어야 한다고 본다.","c":"중","v":1},"공인노2019_28-33-4":{"w":"판례는 유인물 배포에 허가제를 둔 경우라도 허가 여부만으로 정당성을 정하지 않고 유인물의 내용·배포 시기·방법 등 제반 사정을 따져 판단한다. 허가 없는 배포라도 정당한 조합활동이 될 수 있다.","c":"중","v":1},"공인노2019_28-33-5":{"w":"판례는 조합원이 조합 결의에 따라 한 조직적 활동이 아니더라도 행위의 성질상 노동조합 활동으로 볼 수 있거나 노동조합의 묵시적 수권 또는 승인을 받았다고 볼 수 있으면 노동조합의 업무를 위한 행위로 본다.","c":"중","v":1},"공인노2022_31-28-1":{"w":"노조법 제21조 제2항 단서에 따라 결의·처분이 규약에 위반된 경우의 시정명령은 이해관계인의 신청이 있을 때만 할 수 있다. 법령 위반이면 신청 없이도 노동위원회 의결을 얻어 시정을 명할 수 있다.","c":"상","v":1},"공인노2022_31-28-2":{"w":"노조법 제16조 제1항 제7호(합병·분할 또는 해산)와 제8호(조직형태의 변경)가 총회 의결사항이다.","c":"상","v":1},"공인노2022_31-28-3":{"w":"노조법 제16조 제2항 단서는 규약의 제정·변경, 임원의 해임, 합병·분할·해산, 조직형태 변경을 재적조합원 과반수 출석과 출석조합원 3분의 2 이상 찬성의 특별의결사항으로 정한다.","c":"상","v":1},"공인노2022_31-28-4":{"w":"노조법 제16조 제1항 제3호가 단체협약에 관한 사항을 총회 의결사항으로 정한다. 다만 판례는 협약 체결 전 총회 인준을 반드시 거치게 하는 규약은 대표자의 체결권한을 전면 제한하므로 허용되지 않는다고 본다.","c":"상","v":1},"공인노2022_31-30-1":{"w":"노조법 제24조 제1항(2021년 개정)에 따라 단체협약이나 사용자 동의가 있으면 사용자 또는 노동조합으로부터 급여를 받으면서 노조 업무에 종사할 수 있다.","c":"상","v":1},"공인노2022_31-30-2":{"w":"판례는 노동조합의 하부단체인 분회·지부가 독자적인 규약과 집행기관을 가지고 독립된 조직체로 활동하면 그 조직이나 조합원에 고유한 사항에 관하여 독자적으로 단체교섭과 단체협약 체결을 할 수 있다고 본다. 설립신고 여부와는 상관없다.","c":"중","v":1},"공인노2022_31-30-3":{"w":"노조법 시행령 제7조가 근로조건 결정권이 있는 독립된 사업 또는 사업장에 조직된 노동단체는 지부·분회 등 명칭과 관계없이 노조법 제10조 제1항의 설립신고를 할 수 있다고 정한다.","c":"상","v":1},"공인노2022_31-30-5":{"w":"노조법 제10조 제1항은 설립신고서에 명칭·주된 사무소 소재지·조합원수 등을 적고 규약을 첨부하도록 하며 연합단체인 노동조합은 고용노동부장관에게 제출하도록 정한다.","c":"상","v":1},"공인노2024_33-44-2":{"w":"노조법 제13조 제2항 제3호에 따라 노동조합은 매년 1월 31일까지 전년도 12월 31일 현재 조합원수(연합단체는 구성단체별 조합원수)를 행정관청에 통보해야 한다.","c":"상","v":1},"공인노2024_33-44-3":{"w":"노조법 제12조 제4항에 따라 신고증을 교부받으면 설립신고서가 접수된 때로 소급하여 설립된 것으로 본다.","c":"상","v":1},"공인노2024_33-44-4":{"w":"노조법 제12조 제2항에 따라 기재사항 누락 등으로 보완이 필요하면 20일 이내의 기간을 정해 보완을 요구해야 하고 보완된 신고서를 받으면 3일 이내에 신고증을 내준다.","c":"상","v":1},"공인노2024_33-45-3":{"w":"노조법 제17조 제3항(2021년 신설)에 따라 기업별 노조의 대의원은 그 사업 또는 사업장에 종사하는 조합원 중에서 선출해야 한다.","c":"상","v":1},"공인노2024_33-46-4":{"w":"노조법 시행령 제11조의5 제3항에 따라 근로시간면제심의위원회 위원은 임기(2년)가 끝나도 후임자가 위촉될 때까지 직무를 계속 수행한다.","c":"상","v":1},"공인노2024_33-47-1":{"w":"노조법 제24조 제1항에 따라 근로자는 단체협약으로 정하거나 사용자의 동의가 있으면 사용자 또는 노동조합으로부터 급여를 받으며 노조 업무에 종사할 수 있다.","c":"상","v":1},"공인노2024_33-47-2":{"w":"노조법 제20조(표결권의 특례)에 따라 특정 조합원에 관한 사항을 의결할 때 그 조합원은 표결권이 없다. 이해관계 있는 조합원을 표결에서 빼 공정성을 지키려는 규정이다.","c":"상","v":1},"공인노2024_33-47-4":{"w":"노조법 제26조에 따라 대표자는 회계연도마다 결산결과와 운영상황을 공표하고 조합원이 요구하면 열람하게 해야 한다. 시행령 제11조의8은 회계연도 종료 후 2개월(공인회계사 감사 시 3개월) 이내에 게시판·홈페이지 등으로 공표하도록 한다.","c":"상","v":1},"공인노2024_33-47-5":{"w":"노조법 시행령 제12조에 따라 행정관청이 노조법 제27조의 결산결과·운영상황 보고를 받으려면 사유 등을 적은 서면으로 10일 이전에 요구해야 한다.","c":"상","v":1},"공인노2025_34-44-2":{"w":"노조법 시행령 제8조 제2항에 따라 총연합단체나 산업별 연합단체인 노동조합은 가입한 노동조합의 활동을 협조·지원 또는 지도할 수 있다.","c":"상","v":1},"공인노2025_34-44-3":{"w":"노조법 시행령 제8조 제1항에 따라 단위노동조합이 산업별 연합단체에 가입하면 그 연합단체 규약이 정하는 의무를 성실하게 이행해야 한다.","c":"상","v":1},"공인노2025_34-44-4":{"w":"노조법 제10조 제2항의 연합단체 정의다. 산업별 연합단체는 동종산업 단위노조로, 총연합단체는 산업별 연합단체나 전국규모 산업별 단위노조로 구성된다.","c":"상","v":1},"공인노2025_34-44-5":{"w":"노조법 제14조 제1항 제1호에 따라 노동조합은 설립일부터 30일 이내에 조합원 명부를 비치해야 하고 연합단체인 노동조합은 그 구성단체의 명칭을 적은 명부를 둔다.","c":"상","v":1},"공인노2025_34-47-1":{"w":"노조법 제25조 제2항에 따라 회계감사원은 6개월마다 하는 정기 감사(제1항)와 별도로 필요하다고 인정하면 회계감사를 하고 결과를 공개할 수 있다.","c":"상","v":1},"공인노2025_34-50-1":{"w":"판례는 법인 아닌 노동조합의 조합원이 1인만 남아 증가할 일반적 가능성이 없으면 단체성을 잃어 청산 목적과 관련되지 않는 한 당사자능력이 없다고 본다. 노동조합은 2인 이상의 단결체이기 때문이다.","c":"중","v":1},"공인노2025_34-50-2":{"w":"판례는 노동조합이 단결권 확보에 필요하고 합리적인 범위에서 조합원에게 규제와 강제를 할 수 있는 내부통제권을 가진다고 본다. 노조법 제11조 제15호도 규약에 규율과 통제에 관한 사항을 적도록 한다.","c":"중","v":1},"공인노2025_34-50-3":{"w":"대법원(2021년)은 사용자의 지배·개입으로 설립된 어용노조는 설립신고가 수리되었어도 자주성 등 실질적 요건이 흠결되어 하자가 치유되는 등 특별한 사정이 없는 한 설립이 무효라고 보았다. 다른 노조는 그 설립무효 확인을 구하는 소를 낼 수 있다.","c":"중","v":1},"공인노2025_34-50-4":{"w":"헌법재판소는 실질적 요건은 갖추었으나 설립신고를 하지 않은 법외노조도 아무 활동을 못 하는 것은 아니고 어느 정도의 단체교섭이나 협약체결 능력을 가진다고 보았다. 노조법상 보호(조정신청·구제신청·명칭 사용)만 받지 못한다.","c":"중","v":1},"공인노2025_34-68-2":{"w":"노조법 제24조의2 제5항이 근로시간면제심의위원회를 근로자·사용자·공익 대표 위원 각 5명씩 성별을 고려하여 구성하도록 정한다.","c":"상","v":1},"공인노2026_35-42-1":{"w":"노조법 제14조 제1항 제4호에 따라 회의록은 조합설립일부터 30일 이내에 작성하여 주된 사무소에 비치해야 하는 서류다.","c":"상","v":1},"공인노2026_35-42-2":{"w":"노조법 제14조 제2항에 따라 회의록과 재정에 관한 장부·서류는 3년간 보존해야 한다.","c":"상","v":1},"공인노2026_35-42-3":{"w":"노조법 제17조 제3항이 하나의 사업 또는 사업장을 대상으로 조직된 노조의 대의원은 그 사업장에 종사하는 조합원 중에서 선출하도록 정한다.","c":"상","v":1},"공인노2026_35-42-4":{"w":"노조법 제17조 제4항에 따라 대의원 임기는 규약으로 정하되 3년을 넘을 수 없다. 임원 임기도 같다(제23조 제2항).","c":"상","v":1},"공인노2026_35-43-4":{"w":"노조법 제18조 제4항에 따라 소집권자가 없을 때 조합원 3분의 1 이상이 부의사항을 제시하고 지명을 요구하면 행정관청은 15일 이내에 소집권자를 지명해야 한다. 이 경우는 노동위원회 의결이 필요 없다.","c":"상","v":1},"공인노2026_35-44-2":{"w":"노조법 제25조 제1항이 대표자로 하여금 회계감사원을 통해 6개월에 1회 이상 모든 재원·용도 등을 감사하고 그 내용과 결과를 전체 조합원에게 공개하도록 정한다.","c":"상","v":1},"공인노2026_35-44-3":{"w":"노조법 제25조 제2항에 따라 회계감사원은 필요하다고 인정하면 스스로 회계감사를 하고 그 결과를 공개할 수 있다.","c":"상","v":1},"공인노2026_35-44-4":{"w":"노조법 제26조가 대표자에게 회계연도마다 결산결과와 운영상황을 공표하고 조합원이 요구하면 열람하게 할 의무를 지운다.","c":"상","v":1},"공인노2026_35-44-5":{"w":"노조법 시행령 제11조의9 제1항에 따라 고용노동부장관은 노동조합 회계 공시시스템을 구축·운영할 수 있다. 대표자가 매년 4월 30일까지 여기에 공표하면 결산결과를 공표한 것으로 본다(같은 조 제2항).","c":"상","v":1},"공인노2026_35-45-3":{"w":"노조법 시행령 제11조 제1항 제3호와 제2항에 따라 위법한 단체협약 시정명령(노조법 제31조 제3항)은 노동조합 대표자에게 서면으로 통보하고 사용자나 사용자단체에도 통보해야 한다.","c":"상","v":1},"공인노2026_35-47-1":{"w":"노조법 제21조 제2항 단서에 따라 규약 위반을 이유로 한 결의·처분 시정명령은 이해관계인의 신청이 있는 경우에만 할 수 있다.","c":"상","v":1},"공인노2026_35-47-3":{"w":"노조법 시행령 제13조 제3항에 따라 휴면노조 해산 의결 시 노동위원회는 해산사유 발생일 이후의 활동을 고려해서는 안 된다. 해산사유 발생 뒤 형식적 활동으로 해산을 피하는 것을 막는 규정이다.","c":"상","v":1},"공인노2026_35-47-4":{"w":"노조법 제28조 제1항 제2호(합병 또는 분할로 소멸)로 해산하면 같은 조 제2항에 따라 대표자는 해산한 날부터 15일 이내에 행정관청에 신고해야 한다.","c":"상","v":1},"공인노2026_35-47-5":{"w":"노조법 시행령 제12조에 따라 행정관청이 결산결과 또는 운영상황 보고를 받으려면 사유 등을 적은 서면으로 10일 이전에 요구해야 한다.","c":"상","v":1},"공인노2026_35-48-2":{"w":"노조법 시행령 제9조 제3항에 따라 행정관청은 신고증을 교부하면 지체 없이 관할 노동위원회와 해당 사업장의 사용자나 사용자단체에 통보해야 한다.","c":"상","v":1},"공인노2017_26-37-1":{"w":"판례는 조합원 범위를 바꾸는 조직변경을 변경 전후 노동조합의 실질적 동일성이 인정되는 범위에서만 허용한다. 동일성이 있어야 재산과 협약상 지위가 승계되기 때문이다.","c":"중","v":1},"공인노2017_26-37-2":{"w":"판례는 어느 사업장 근로자로 구성된 노동조합이 다른 사업장의 노동조합을 결성하거나 그 조직형태를 결정할 수 없다고 본다. 조직형태는 그 노동조합 조합원이 스스로 정할 일이다.","c":"중","v":1},"공인노2017_26-37-3":{"w":"노조법 제16조 제1항 제8호와 제2항 단서에 따라 조직형태 변경은 재적조합원 과반수 출석과 출석조합원 3분의 2 이상 찬성의 특별의결로 한다.","c":"상","v":1},"공인노2017_26-37-4":{"w":"판례는 조직변경이 유효하면 변경 후 노동조합이 변경 전 노동조합의 재산관계와 단체협약 주체로서의 지위를 그대로 승계한다고 본다. 해산·신설 절차를 거치지 않아도 되는 것이 조직변경 제도의 취지다.","c":"중","v":1},"공인노2019_28-32-1":{"w":"노조법 제28조 제1항 제1호가 규약에서 정한 해산사유 발생을 해산사유로 정한다.","c":"상","v":1},"공인노2019_28-32-2":{"w":"노조법 제28조 제1항 제4호의 휴면노조 해산사유다. 시행령 제13조 제1항은 1년 이상 조합비 징수나 총회·대의원회 개최 사실이 없는 경우를 활동하지 않은 것으로 본다.","c":"상","v":1},"공인노2019_28-32-3":{"w":"노조법 제28조 제1항 제2호가 합병 또는 분할로 소멸한 경우를 해산사유로 정한다.","c":"상","v":1},"공인노2019_28-32-5":{"w":"노조법 제28조 제2항에 따라 제1항 제1호~제3호(규약상 해산사유, 합병·분할 소멸, 총회·대의원회 해산결의)로 해산하면 대표자는 15일 이내에 행정관청에 신고해야 한다. 휴면노조 해산(제4호)은 신고 대상이 아니다.","c":"상","v":1},"공인노2024_33-48-1":{"w":"노조법 제28조 제1항 제4호와 시행령 제13조 제1항에 따라 임원이 없고 계속하여 1년 이상 조합비를 징수한 사실이 없으면 활동을 하지 않은 것으로 보아 노동위원회 의결로 해산한다.","c":"상","v":1},"공인노2024_33-48-2":{"w":"노조법 제28조 제1항 제2호의 해산사유다.","c":"상","v":1},"공인노2024_33-48-3":{"w":"노조법 제28조 제1항 제3호가 총회 또는 대의원회의 해산결의를 해산사유로 정한다. 이 결의는 제16조 제2항 단서의 특별의결(출석 3분의 2 이상 찬성)이 필요하다.","c":"상","v":1},"공인노2024_33-48-4":{"w":"노조법 제28조 제2항은 제1항 제1호(규약상 해산사유) 등으로 해산하면 대표자가 해산한 날부터 15일 이내에 행정관청에 신고하도록 정한다.","c":"상","v":1},"공인노2025_34-43-1":{"w":"노조법 제22조 본문은 조합원의 균등한 참여 권리·의무를, 단서는 조합비 미납 조합원의 권리를 규약으로 제한할 수 있음을 정한다.","c":"상","v":1},"공인노2025_34-43-2":{"w":"노조법 제20조에 따라 특정 조합원에 관한 사항을 의결할 때 그 조합원은 표결권이 없다.","c":"상","v":1},"공인노2025_34-43-3":{"w":"노조법 제5조 제2항(2021년 신설)에 따라 종사근로자가 아닌 조합원도 사용자의 효율적인 사업 운영에 지장을 주지 않는 범위에서 사업장 내 조합활동을 할 수 있다.","c":"상","v":1},"공인노2025_34-43-5":{"w":"노조법 제9조(차별대우의 금지)가 인종·종교·성별·연령·신체적 조건·고용형태·정당·신분에 의한 차별을 금지한다.","c":"상","v":1},"공인노2025_34-45-1":{"w":"노조법 제28조 제1항 제3호의 해산사유다.","c":"상","v":1},"공인노2025_34-45-2":{"w":"노조법 제28조 제1항 제4호의 해산사유다. 시행령 제13조 제2항에 따라 노동위원회 의결을 얻은 때 해산된 것으로 본다.","c":"상","v":1},"공인노2025_34-45-4":{"w":"노조법 시행령 제13조 제4항에 따라 행정관청은 합병 등으로 인한 해산신고(노조법 제28조 제2항)를 받으면 지체 없이 관할 노동위원회와 해당 사업장의 사용자나 사용자단체에 통보해야 한다.","c":"상","v":1},"공인노2025_34-45-5":{"w":"분할은 노조법 제16조 제2항 단서의 특별의결사항(재적 과반수 출석, 출석 3분의 2 이상 찬성)이고 분할로 소멸하면 제28조 제1항 제2호에 따라 해산한다.","c":"상","v":1},"공인노2017_26-34-1":{"w":"노조법 제29조 제2항이 교섭대표노동조합 대표자에게 교섭을 요구한 모든 노동조합과 조합원을 위하여 교섭하고 협약을 체결할 권한을 준다.","c":"상","v":1},"공인노2017_26-34-2":{"w":"노조법 제29조의4 제1항의 공정대표의무다. 교섭대표노동조합과 사용자 모두가 이 의무를 진다.","c":"상","v":1},"공인노2017_26-34-4":{"w":"노조법 시행령 제14조의10 제2항에 따라 지위 유지기간이 끝났는데 새 교섭대표노조가 정해지지 않으면 기존 교섭대표노조는 기존 단체협약 이행과 관련해서만 지위를 유지한다.","c":"상","v":1},"공인노2017_26-34-5":{"w":"노조법 시행령 제14조의6 제2항에 따라 자율적으로 정한 교섭대표노조를 사용자에게 통지한 뒤에는 일부 노조가 이후 절차에 빠져도 교섭대표노조 지위가 유지된다.","c":"상","v":1},"공인노2019_28-34-1":{"w":"노조법 제29조 제1항이 노동조합 대표자에게 노동조합 또는 조합원을 위하여 사용자나 사용자단체와 교섭하고 단체협약을 체결할 권한을 준다.","c":"상","v":1},"공인노2019_28-34-3":{"w":"노조법 제30조 제1항의 성실교섭의무다. 노동조합과 사용자 양쪽이 진다.","c":"상","v":1},"공인노2019_28-34-4":{"w":"노조법 제30조 제2항이 정당한 이유 없는 교섭·체결 거부와 해태를 금지한다. 사용자의 거부·해태는 제81조 제1항 제3호의 부당노동행위가 된다.","c":"상","v":1},"공인노2019_28-34-5":{"w":"판례는 노동조합의 지부·분회가 독자적인 규약과 집행기관을 갖추고 독립된 조직체로 활동하면 그 조직이나 조합원에 고유한 사항은 독자적으로 단체교섭하고 협약을 체결할 수 있다고 본다. 설립신고 여부는 영향이 없다.","c":"중","v":1},"공인노2019_28-35-1":{"w":"노조법 제29조의4 제1항은 교섭대표노동조합과 사용자 모두에게 공정대표의무를 지운다.","c":"상","v":1},"공인노2019_28-35-3":{"w":"노조법 제29조의4 제1항 위반 자체를 처벌하는 규정은 없다. 노동위원회 시정명령이 확정된 뒤 이를 위반하면 제89조 제2호(제29조의4 제4항에서 준용하는 제85조 제3항)로 처벌한다.","c":"상","v":1},"공인노2019_28-35-4":{"w":"대법원은 교섭대표노동조합이나 사용자가 다른 노동조합 또는 조합원을 차별한 것으로 인정되면 그 차별에 합리적 이유가 있다는 점은 교섭대표노조나 사용자가 주장·증명해야 한다고 본다.","c":"중","v":1},"공인노2019_28-35-5":{"w":"판례는 공정대표의무가 교섭창구 단일화 제도로 교섭권을 제한받는 소수노조를 보호하려는 것이므로 단체교섭 과정과 단체협약 내용뿐 아니라 협약 이행 과정에서도 지켜야 한다고 본다.","c":"중","v":1},"공인노2019_28-36-5":{"w":"노조법 시행령 제14조의10 제2항에 따라 지위 유지기간이 끝났는데 새 교섭대표노조가 정해지지 않으면 기존 교섭대표노조는 기존 협약 이행과 관련해서만 지위를 유지한다. 유지기간은 첫 협약 효력 발생일부터 2년이다(같은 조 제1항).","c":"상","v":1},"공인노2022_31-31-1":{"w":"노조법 제30조 제2항은 노동조합과 사용자 양쪽에 정당한 이유 없는 교섭·체결 거부·해태를 금지한다.","c":"상","v":1},"공인노2022_31-31-2":{"w":"노조법 제29조 제3항에 따라 사용자로부터 교섭·체결 권한을 위임받은 자는 위임받은 범위에서 그 권한을 행사한다. 위임한 쪽은 상대방에게 그 사실을 통보해야 한다(같은 조 제4항).","c":"상","v":1},"공인노2022_31-31-3":{"w":"대법원 판례는 교섭창구 단일화 제도의 취지상 교섭대표노동조합 대표자가 협약 체결 여부에 대해 원칙적으로 소수노조나 그 조합원의 의사에 기속되지 않는다고 본다. 다만 절차적 공정대표의무에 따라 소수노조에 정보를 제공하고 의견을 수렴할 의무는 있다.","c":"중","v":1},"공인노2022_31-31-5":{"w":"노조법 제30조 제3항(2021년 신설)이 국가와 지방자치단체에 다양한 교섭방식 선택 지원과 단체교섭 활성화 노력 의무를 지운다.","c":"상","v":1},"공인노2022_31-32-1":{"w":"노조법 제29조의2 제1항 본문의 교섭창구 단일화 원칙이다.","c":"상","v":1},"공인노2022_31-32-2":{"w":"노조법 제29조의2 제2항에 따라 사용자가 개별교섭에 동의하면 교섭을 요구한 모든 노동조합과 성실히 교섭해야 하고 차별해서는 안 된다.","c":"상","v":1},"공인노2022_31-32-4":{"w":"노조법 제29조의2 제6항에 따라 공동교섭대표단 구성에 합의하지 못하면 노동위원회가 노조 신청으로 조합원 비율을 고려해 결정한다. 시행령 제14조의9 제2항은 총 10명 이내에서 노조별 인원을 정하도록 한다.","c":"상","v":1},"공인노2022_31-32-5":{"w":"노조법 시행령 제14조의8 제2항에 따라 공동교섭대표단을 사용자에게 통지한 뒤에는 일부 노조가 이후 절차에 빠져도 교섭대표노조 지위가 유지된다.","c":"상","v":1},"공인노2022_31-33-4":{"w":"노조법 시행령 제14조의11 제5항에 따라 노동위원회는 신청을 받은 날부터 30일 이내에 교섭단위 분리·통합 결정을 하고 해당 사업장의 모든 노동조합과 사용자에게 통지해야 한다.","c":"상","v":1},"공인노2024_33-49-2":{"w":"노조법 시행령 제14조의11 제2항에 따라 분리·통합 신청을 받은 노동위원회는 해당 사업장의 모든 노동조합과 사용자에게 내용을 통지하고 이들은 지정 기간까지 의견을 낼 수 있다.","c":"상","v":1},"공인노2024_33-49-3":{"w":"노조법 제29조의3 제2항이 정한 교섭단위 분리 요건과 신청권자(노동관계 당사자 양쪽 또는 어느 한쪽)다.","c":"상","v":1},"공인노2024_33-49-4":{"w":"노조법 시행령 제14조의11 제1항 제2호에 따라 사용자가 교섭요구 사실을 공고한 경우에는 교섭대표노조가 결정된 날 이후에 분리 신청을 할 수 있다. 공고 전이면 제1호에 따라 언제든 신청할 수 있다.","c":"상","v":1},"공인노2024_33-49-5":{"w":"노조법 시행령 제14조의11 제6항에 따라 분리 결정을 통지받은 노조는 자기 교섭단위 협약의 유효기간 만료일 이전 3개월이 되는 날부터 교섭을 요구할 수 있다. 요구는 제14조의2 제2항의 사항(노조 명칭, 종사근로자인 조합원 수 등)을 적은 서면으로 한다.","c":"상","v":1},"공인노2024_33-54-1":{"w":"노조법 제29조의4 제1항의 공정대표의무다.","c":"상","v":1},"공인노2024_33-54-2":{"w":"대법원은 교섭대표노조에 상시 사용할 사무실을 제공했다면 특별한 사정이 없는 한 다른 노조에도 일률적·비례적이지는 않더라도 상시 사용할 일정한 공간을 제공해야 하고 그렇지 않으면 공정대표의무 위반이라고 보았다.","c":"중","v":1},"공인노2024_33-54-3":{"w":"노조법 제30조 제1항의 성실교섭·권한남용 금지 원칙이다.","c":"상","v":1},"공인노2024_33-54-4":{"w":"노조법 제30조 제3항이 정한 국가·지방자치단체의 교섭방식 지원 의무다.","c":"상","v":1},"공인노2024_33-55-1":{"w":"노조법 시행령 제14조의2 제1항 단서에 따라 단체협약이 2개 이상이면 먼저 이르는 협약의 유효기간 만료일 이전 3개월이 되는 날부터 교섭을 요구할 수 있다.","c":"상","v":1},"공인노2024_33-55-2":{"w":"대법원 판례는 교섭창구 단일화 절차는 복수 노조를 전제로 하므로 사업장에 유일하게 존재하는 노조는 법령의 절차를 형식적으로 거쳤더라도 교섭대표노동조합 지위를 취득할 수 없다고 본다.","c":"중","v":1},"공인노2024_33-55-3":{"w":"노조법 시행령 제14조의3 제1항이 정한 교섭요구 사실 공고(7일간) 의무다.","c":"상","v":1},"공인노2024_33-55-5":{"w":"노조법 시행령 제14조의10 제3항에 따라 교섭대표노조가 결정된 날부터 1년 동안 협약을 체결하지 못하면 어느 노동조합이든 사용자에게 교섭을 요구할 수 있다.","c":"상","v":1},"공인노2025_34-52-1":{"w":"노조법 시행령 제14조의11 제7항에 따라 분리·통합 결정 전에 교섭 요구가 있으면 결정이 있을 때까지 교섭요구 사실 공고 등 단일화 절차 진행이 정지된다.","c":"상","v":1},"공인노2025_34-52-3":{"w":"노조법 시행령 제14조의11 제1항 제1호에 따라 분리된 교섭단위를 통합하려는 노동조합 또는 사용자는 사용자가 교섭요구 사실을 공고하기 전에 노동위원회에 통합 결정을 신청할 수 있다.","c":"상","v":1},"공인노2025_34-52-4":{"w":"대법원 판례는 차별로 인정되는 경우 그 차별에 합리적 이유가 있다는 점의 주장·증명책임을 사용자(또는 교섭대표노조)에게 지운다.","c":"중","v":1},"공인노2025_34-52-5":{"w":"노조법 시행령 제14조의12 제3항에 따라 공정대표의무 시정 신청 심문에서 노동위원회는 당사자 신청이나 직권으로 증인을 출석시켜 질문할 수 있다.","c":"상","v":1},"공인노2025_34-53-1":{"w":"노조법 시행령 제14조의6 제2항에 따라 자율적으로 정한 교섭대표노조를 사용자에게 통지한 뒤에는 일부 노조가 이후 절차에 빠져도 교섭대표노조 지위가 유지된다.","c":"상","v":1},"공인노2025_34-53-2":{"w":"노조법 시행령 제14조 제1항이 노동관계당사자가 교섭·체결 권한을 위임할 때 교섭사항과 권한범위를 정하도록 한다.","c":"상","v":1},"공인노2025_34-53-4":{"w":"노조법 시행령 제14조의3 제1항의 교섭요구 사실 공고 의무다.","c":"상","v":1},"공인노2025_34-53-5":{"w":"노조법 시행령 제14조의3 제2항에 따라 공고를 하지 않거나 다르게 하면 노동조합은 노동위원회에 시정을 요청할 수 있고 노동위원회는 10일 이내에 결정한다(같은 조 제3항).","c":"상","v":1},"공인노2026_35-50-1":{"w":"노조법 제29조의4 제1항의 공정대표의무다.","c":"상","v":1},"공인노2026_35-50-2":{"w":"노조법 제29조의4 제2항에 따라 협약 내용이 공정대표의무에 어긋나면 단체협약 체결일부터 3개월 이내에 노동위원회에 시정을 요청할 수 있다.","c":"상","v":1},"공인노2026_35-50-3":{"w":"노조법 시행령 제14조의12 제3항에 따라 노동위원회는 당사자 신청이나 직권으로 증인을 출석시켜 질문할 수 있다.","c":"상","v":1},"공인노2026_35-50-4":{"w":"대법원 판례는 차별에 합리적 이유가 있다는 점의 주장·증명책임을 교섭대표노동조합이나 사용자에게 지운다.","c":"중","v":1},"공인노2026_35-51-1":{"w":"노조법 제29조 제1항이 정한 노동조합 대표자의 교섭·체결 권한이다.","c":"상","v":1},"공인노2026_35-51-3":{"w":"대법원 판례는 교섭대표노조 대표자가 협약 체결 여부에 관하여 원칙적으로 소수노조나 그 조합원의 의사에 기속되지 않는다고 본다. 교섭대표노조에 통일적 교섭 권한을 준 단일화 제도의 취지 때문이다.","c":"중","v":1},"공인노2026_35-51-4":{"w":"노조법 제2조 제3호는 사용자단체를 노동관계에 관하여 구성원인 사용자에 대해 조정 또는 규제할 수 있는 권한을 가진 사용자의 단체로 정의한다.","c":"상","v":1},"공인노2026_35-51-5":{"w":"노조법 시행령 제14조 제1항에 따라 노동관계당사자는 교섭·체결 권한을 위임할 때 교섭사항과 권한범위를 정해야 한다. 상대방에 위임 사실을 통보할 때도 이를 포함한다(같은 조 제2항).","c":"상","v":1},"공인노2026_35-54-1":{"w":"노조법 시행령 제14조의2 제2항이 교섭 요구를 노동조합 명칭, 요구한 날 현재의 종사근로자인 조합원 수 등을 적은 서면으로 하도록 정한다.","c":"상","v":1},"공인노2026_35-56-1":{"w":"노조법 제29조의3 제2항이 정한 교섭단위 분리 결정이다.","c":"상","v":1},"공인노2026_35-56-2":{"w":"노조법 시행령 제14조의11 제2항이 정한 통지 의무다.","c":"상","v":1},"공인노2026_35-56-4":{"w":"노조법 시행령 제14조의11 제1항이 분리 신청 시기를 교섭요구 사실 공고 전(제1호)과 공고한 경우 교섭대표노조 결정일 이후(제2호)로 정한다.","c":"상","v":1},"공인노2026_35-56-5":{"w":"노조법 시행령 제14조의11 제7항이 정한 단일화 절차 정지다.","c":"상","v":1},"공인노2026_35-57-1":{"w":"노조법 제29조의2 제1항 단서에 따라 자율 결정 기한 내에 사용자가 단일화 절차를 거치지 않기로 동의하면 교섭대표노조를 정하지 않고 개별교섭을 할 수 있다.","c":"상","v":1},"공인노2026_35-57-2":{"w":"노조법 시행령 제14조의3 제1항에 따라 교섭 요구를 받은 날부터 7일간 공고해야 한다.","c":"상","v":1},"공인노2026_35-57-3":{"w":"노조법 시행령 제14조의7 제2항에 따라 과반수노동조합 통지를 받은 사용자는 받은 날부터 5일간 공고해야 한다.","c":"상","v":1},"공인노2026_35-57-5":{"w":"노조법 시행령 제14조의10 제3항에 따라 교섭대표노조가 결정된 날부터 1년 동안 협약을 체결하지 못하면 어느 노동조합이든 사용자에게 교섭을 요구할 수 있다.","c":"상","v":1},"공인노2017_26-38-2":{"w":"노조법 제33조의 규범적 효력이다. 협약 기준에 위반하는 취업규칙·근로계약 부분은 무효가 되고 그 부분과 근로계약에 없는 사항은 협약 기준에 따른다.","c":"상","v":1},"공인노2019_28-37-1":{"w":"노조법 제31조 제1항이 정한 단체협약의 요식성이다. 체결일부터 15일 이내에 당사자 쌍방이 연명으로 행정관청에 신고해야 한다(제31조 제2항, 시행령 제15조).","c":"상","v":1},"공인노2019_28-37-2":{"w":"노조법 제33조 제2항에 따라 근로계약에 규정되지 않은 사항은 단체협약에 정한 기준에 의한다.","c":"상","v":1},"공인노2019_28-37-3":{"w":"노조법 제31조 제3항이 정한 위법 단체협약 시정명령이다. 이 명령을 위반하면 제93조 제2호로 500만원 이하 벌금이다.","c":"상","v":1},"공인노2019_28-37-4":{"w":"대법원 판례는 대표자의 협약체결권을 전면적·포괄적으로 제한하는 규약은 노조법 제29조 제1항 취지에 어긋나지만 조합원 의사를 반영하고 대표자를 통제하기 위한 절차적 제한은 허용된다고 본다.","c":"중","v":1},"공인노2019_28-39-1":{"w":"판례는 단체협약이 근로자의 근로조건을 유지·개선하려고 체결된 것이므로 명문 규정을 근로자에게 불리하게 변형 해석할 수 없다고 본다.","c":"중","v":1},"공인노2019_28-39-2":{"w":"노조법 제34조 제3항에 따라 노동위원회가 제시한 해석 견해는 중재재정과 같은 효력을 가지므로 판례는 그 불복도 중재재정 불복 규정인 제69조에 따라 위법·월권을 이유로 중앙노동위원회 재심을 신청할 수 있다고 본다.","c":"중","v":1},"공인노2019_28-39-4":{"w":"노조법 제34조 제2항에 따라 노동위원회는 해석 요청을 받은 날부터 30일 이내에 명확한 견해를 제시해야 한다.","c":"상","v":1},"공인노2019_28-39-5":{"w":"노조법 제34조 제3항에 따라 노동위원회가 제시한 해석·이행방법 견해는 중재재정과 같은 효력을 가진다.","c":"상","v":1},"공인노2022_31-34-1":{"w":"노조법 제31조 제3항이 정한 위법 단체협약 시정명령이다.","c":"상","v":1},"공인노2022_31-34-3":{"w":"노조법 제32조 제2항에 따라 유효기간을 정하지 않았거나 3년을 넘겨 정하면 유효기간은 3년이다.","c":"상","v":1},"공인노2022_31-34-4":{"w":"노조법 시행령 제15조가 노조법 제31조 제2항의 단체협약 신고를 당사자 쌍방이 연명으로 하도록 정한다.","c":"상","v":1},"공인노2022_31-34-5":{"w":"노조법 제34조 제3항에 따라 해석뿐 아니라 이행방법에 관한 견해도 중재재정과 같은 효력을 가진다.","c":"상","v":1},"공인노2022_31-36-1":{"w":"노조법 제30조 제1항이 노동조합과 사용자 양쪽에 성실교섭·성실체결 의무와 권한남용 금지를 정한다.","c":"상","v":1},"공인노2022_31-36-2":{"w":"노조법 제33조 제1항의 규범적 효력이다.","c":"상","v":1},"공인노2022_31-36-3":{"w":"판례는 협약 당사자인 노동조합이 유효기간 중 협약에서 정한 근로조건 등의 변경·폐지를 요구하는 쟁의행위를 하지 않을 평화의무를 진다고 보고 이를 위반한 쟁의행위는 정당성이 없다고 본다.","c":"중","v":1},"공인노2022_31-36-4":{"w":"판례는 인사처분에 노조의 사전 동의나 승낙을 얻도록 협약에 정한 경우 그 절차를 거치지 않은 처분은 원칙적으로 무효로 본다. 다만 노조가 동의권을 남용하거나 스스로 포기한 경우에는 예외다.","c":"중","v":1},"공인노2024_33-50-1":{"w":"노조법 제30조 제2항이 노동조합과 사용자 양쪽에 정당한 이유 없는 교섭·체결 거부와 해태를 금지한다.","c":"상","v":1},"공인노2024_33-50-3":{"w":"판례는 노조법 제35조의 「동종의 근로자」를 협약 규정상 적용이 예상되는 자로 보므로 협약상 조합원 자격이 없는 자에게는 일반적 구속력이 미치지 않는다고 본다.","c":"중","v":1},"공인노2024_33-50-4":{"w":"노조법 제32조 제2항에 따라 유효기간을 정하지 않으면 3년이다.","c":"상","v":1},"공인노2024_33-50-5":{"w":"노조법 제29조 제4항이 교섭·체결 권한을 위임한 노동조합과 사용자에게 상대방 통보 의무를 지운다.","c":"상","v":1},"공인노2024_33-53-2":{"w":"노조법 제29조 제1항이 정한 노동조합 대표자의 권한이다.","c":"상","v":1},"공인노2024_33-53-3":{"w":"노조법 제31조 제2항에 따라 체결일부터 15일 이내에 신고해야 하고 시행령 제15조에 따라 쌍방 연명으로 한다.","c":"상","v":1},"공인노2024_33-53-4":{"w":"노조법 제34조 제1항에 따라 당사자 쌍방이 함께 하거나 단체협약에 정하는 바에 따라 어느 일방(사용자 포함)이 견해 제시를 요청할 수 있다.","c":"상","v":1},"공인노2024_33-53-5":{"w":"노조법 제34조 제2항이 요청받은 날부터 30일 이내의 견해 제시 의무를 정한다.","c":"상","v":1},"공인노2025_34-49-1":{"w":"판례는 교섭 거부·해태에 정당한 이유가 있는지를 교섭 주체·시간·장소·사항·태도 등을 종합해 사회통념상 사용자에게 교섭의무 이행을 기대하기 어려운지로 판단한다.","c":"중","v":1},"공인노2025_34-49-2":{"w":"대법원은 헌법 제33조 제1항의 단체교섭권이 법률 없이도 헌법 규정만으로 직접 법규범으로서 효력을 발휘하는 구체적 권리라고 본다. 그래서 교섭 거부에 대해 불법행위 손해배상도 인정된다.","c":"중","v":1},"공인노2025_34-49-4":{"w":"대법원 전원합의체 판례(2020년)는 업무상 재해로 사망한 조합원의 직계가족 등을 채용하기로 한 산재 유족 특별채용 조항이 채용의 자유를 과도하게 제한하거나 채용 공정성을 현저히 해치는 등 특별한 사정이 없으면 민법 제103조 위반이 아니라고 보았다.","c":"중","v":1},"공인노2025_34-49-5":{"w":"노조법 제31조 제3항의 시정명령을 위반하면 제93조 제2호로 500만원 이하 벌금에 처한다.","c":"상","v":1},"공인노2025_34-51-1":{"w":"노조법 제32조 제1항은 유효기간을 3년 넘지 않는 범위에서 정하도록 하고 제2항은 이를 넘긴 경우 유효기간을 3년으로 본다.","c":"상","v":1},"공인노2025_34-51-2":{"w":"노조법 제32조 제3항 단서에 따라 자동연장 약정이 있으면 그에 따른다. 다만 당사자 일방은 해지하려는 날의 6개월 전까지 통고해 종전 협약을 해지할 수 있다.","c":"상","v":1},"공인노2025_34-51-3":{"w":"판례는 노사가 일정한 조건이 성취되거나 기한이 올 때까지 특정 협약 조항의 효력이 유지되도록 명시해 협약을 체결할 수 있다고 본다. 이 경우 그 조항은 조건 성취·기한 도래로 효력을 잃는다.","c":"중","v":1},"공인노2025_34-51-5":{"w":"판례는 노조법 제32조 제3항 단서의 해지권 규정이 성질상 강행규정이어서 합의로 해지권 행사를 막는 등 그 적용을 배제할 수 없다고 본다.","c":"중","v":1},"공인노2025_34-54-1":{"w":"노조법 제34조 제1항·제3항에 따라 당사자 쌍방이 요청해 노동위원회가 제시한 해석은 중재재정과 같은 효력을 가진다.","c":"상","v":1},"공인노2025_34-54-2":{"w":"노조법 제35조(일반적 구속력)가 정한 요건과 효과다.","c":"상","v":1},"공인노2025_34-54-3":{"w":"노조법 제36조 제1항에 따라 행정관청은 당사자 쌍방 또는 일방의 신청이나 직권으로 노동위원회 의결을 얻어 지역적 구속력 결정을 할 수 있다.","c":"상","v":1},"공인노2025_34-54-4":{"w":"판례는 경영권에 속하는 사항은 원칙적으로 의무적 교섭대상이 아니지만 노사가 임의로 교섭하여 협약을 체결하는 것은 허용되고 그 협약은 유효하다고 본다.","c":"중","v":1},"공인노2026_35-52-1":{"w":"판례는 근로조건뿐 아니라 조합활동·교섭절차 등 단체적 노사관계 운영에 관한 사항도 사용자가 처분할 수 있는 것이면 단체교섭 대상이 된다고 본다.","c":"중","v":1},"공인노2026_35-52-2":{"w":"노조법 제33조 제1항의 규범적 효력이다.","c":"상","v":1},"공인노2026_35-52-3":{"w":"노조법 제30조 제2항이 노동조합과 사용자 양쪽에 정당한 이유 없는 교섭·체결 거부와 해태를 금지한다. 사용자 쪽 위반은 제81조 제1항 제3호의 부당노동행위가 된다.","c":"상","v":1},"공인노2026_35-52-4":{"w":"판례는 노사가 일정한 조건이 성취될 때까지 특정 협약 조항의 효력이 유지되도록 명시해 체결했다면 그 조항은 노사의 합치된 의사에 따라 해제조건이 성취되면 효력을 잃는다고 본다.","c":"중","v":1},"공인노2026_35-53-1":{"w":"대법원 판례는 지역적 구속력(노조법 제36조)이 그 지역에서 독자적으로 교섭해 별도의 단체협약을 적용받는 근로자에게는 미치지 않는다고 본다. 그 노조의 단체교섭권을 침해할 수 있기 때문이다.","c":"중","v":1},"공인노2026_35-55-1":{"w":"노조법 제31조 제1항에 따라 단체협약은 서면으로 작성하고 쌍방이 서명 또는 날인해야 한다. 판례는 이 요식을 갖추지 않은 합의는 단체협약의 효력이 없다고 본다.","c":"상","v":1},"공인노2026_35-55-2":{"w":"노조법 제31조 제2항(15일 이내 신고)과 시행령 제15조(쌍방 연명)를 합친 내용이다.","c":"상","v":1},"공인노2026_35-55-3":{"w":"노조법 제34조 제1항에 따라 단체협약에 정하는 바에 의하여 어느 일방도 견해 제시를 요청할 수 있다.","c":"상","v":1},"공인노2026_35-55-5":{"w":"판례는 협약 당사자인 노동조합이 유효기간 중 협약에서 정한 근로조건 등의 변경·폐지를 요구하는 쟁의행위를 하지 않을 평화의무를 진다고 본다. 이를 위반한 쟁의행위는 정당성이 없다.","c":"중","v":1},"공인노2017_26-40-1":{"w":"노조법 제41조 제1항 전단이 정한 쟁의행위 찬반투표 요건이다. 조합원 수는 종사근로자인 조합원 기준이다(같은 항 후단).","c":"상","v":1},"공인노2017_26-40-2":{"w":"노조법 제41조 제1항에 따라 교섭대표노조가 결정된 경우 그 절차에 참여한 노동조합 전체 조합원의 과반수 찬성이 필요하고 조합원 수는 종사근로자인 조합원을 기준으로 센다.","c":"상","v":1},"공인노2017_26-40-3":{"w":"판례는 지역별·산업별·업종별 노조가 총파업이 아니라 특정 지부·분회에서만 쟁의행위를 하려는 경우에는 그 지부·분회 소속 조합원 과반수 찬성이 있으면 절차적으로 적법하다고 본다.","c":"중","v":1},"공인노2017_26-40-5":{"w":"판례는 찬반투표를 거쳐 정당하게 쟁의행위를 개시한 뒤 쟁의사항과 밀접한 새로운 쟁의사항이 덧붙여진 경우 그 부가 사항에 대해 다시 찬반투표를 거칠 의무는 없다고 본다.","c":"중","v":1},"공인노2019_28-42-1":{"w":"노조법 제39조는 쟁의행위 기간 중 이 법 위반을 이유로 한 구속을 현행범인 경우로만 허용한다.","c":"상","v":1},"공인노2019_28-42-2":{"w":"노조법 제41조 제2항에 따라 주요방위산업체의 전력·용수·주로 방산물자를 생산하는 업무 종사자는 쟁의행위를 할 수 없다. 위반하면 제88조로 5년 이하 징역 또는 5천만원 이하 벌금에 처한다.","c":"상","v":1},"공인노2019_28-42-3":{"w":"노조법 제38조 제2항이 정한 보안작업 유지 의무다.","c":"상","v":1},"공인노2019_28-42-4":{"w":"노조법 제38조 제3항이 정한 노동조합의 지도·관리·통제 책임이다.","c":"상","v":1},"공인노2019_28-43-1":{"w":"노조법 제44조 제1항의 무노동 무임금 원칙이다.","c":"상","v":1},"공인노2019_28-43-2":{"w":"대법원 판례는 파업으로 근로제공의무가 정지되면 휴직과 같이 임금청구권이 생기지 않으므로 파업기간 중 포함된 유급휴일에 대한 임금청구권도 생기지 않는다고 본다.","c":"중","v":1},"공인노2019_28-43-3":{"w":"대법원 판례는 태업도 근로제공이 일부 정지되는 쟁의행위이므로 무노동 무임금 원칙이 적용되어 태업 정도에 비례해 임금을 삭감할 수 있다고 본다.","c":"중","v":1},"공인노2019_28-43-4":{"w":"노조법 제44조 제2항이 쟁의기간 임금 지급 관철 목적의 쟁의행위를 금지한다. 위반하면 제90조로 처벌한다.","c":"상","v":1},"공인노2019_28-44-1":{"w":"판례는 직장폐쇄가 정당한 쟁의행위로 인정되면 사용자가 그 기간 동안 대상 근로자에 대한 임금지불의무를 면한다고 본다.","c":"중","v":1},"공인노2019_28-44-2":{"w":"판례는 직장폐쇄가 노사 간 교섭태도·경과·쟁의행위 태양 등에 비추어 근로자의 쟁의행위에 대한 방어수단으로서 상당성이 있어야 정당하다고 본다.","c":"중","v":1},"공인노2019_28-44-4":{"w":"헌법 제33조 제1항은 근로자의 단결권·단체교섭권·단체행동권만 명시하고 사용자의 쟁의권은 규정하지 않는다. 판례는 사용자의 직장폐쇄를 노사 간 힘의 균형을 위한 방어수단으로서만 인정한다.","c":"상","v":1},"공인노2019_28-44-5":{"w":"판례는 정당한 직장폐쇄가 이루어지면 사용자의 사업장에 대한 물권적 지배권이 전면적으로 회복되어 사용자가 사업장 출입을 제한할 수 있다고 본다.","c":"중","v":1},"공인노2022_31-40-2":{"w":"판례는 직장폐쇄 개시가 정당했더라도 근로자가 쟁의행위를 중단하고 진정으로 업무 복귀 의사를 밝혔는데 계속 유지해 공격적 직장폐쇄로 변질되면 그 이후의 직장폐쇄는 정당성을 잃는다고 본다.","c":"중","v":1},"공인노2022_31-40-3":{"w":"판례는 직장폐쇄가 근로자 쟁의행위에 대한 대항·방위 수단으로서 상당성이 있어야만 정당한 쟁의행위가 된다고 본다.","c":"중","v":1},"공인노2022_31-40-4":{"w":"판례는 직장폐쇄가 정당하지 않으면 사용자의 물권적 지배권이 회복되지 않으므로 적법하게 사업장을 점거 중인 근로자가 퇴거 요구에 응하지 않아도 퇴거불응죄가 성립하지 않는다고 본다.","c":"중","v":1},"공인노2022_31-40-5":{"w":"판례는 직장폐쇄가 정당한 쟁의행위로 평가될 때에만 사용자가 그 기간의 임금지불의무를 면한다고 본다.","c":"중","v":1},"공인노2022_31-42-2":{"w":"노조법 제41조 제1항(2021년 개정)에 따라 찬반투표의 조합원 수는 종사근로자인 조합원을 기준으로 한다.","c":"상","v":1},"공인노2022_31-43-1":{"w":"판례는 쟁의행위 목적이 근로조건 향상을 위한 노사 간 자치적 교섭을 조성하는 데 있어야 정당하다고 본다. 주체·목적·시기와 절차·수단과 방법이 모두 정당해야 한다.","c":"중","v":1},"공인노2022_31-43-2":{"w":"판례는 시행령 제17조의 쟁의행위 신고 규정이 쟁의행위 일시·장소 등을 알려 행정관청이 대비하게 하려는 것이어서 적법 절차를 거친 쟁의행위를 신고절차 미준수만으로 부당하다고 볼 수 없다고 본다.","c":"중","v":1},"공인노2022_31-43-3":{"w":"판례는 피케팅이 파업에 가담하지 않고 조업을 계속하려는 사람에게 평화적 설득이나 구두·문서에 의한 언어적 설득의 범위에서 해야 정당하다고 본다. 노조법 제38조 제1항도 폭행·협박을 금지한다.","c":"중","v":1},"공인노2022_31-43-4":{"w":"판례는 조정전치 규정(노조법 제45조 제2항)의 취지가 쟁의행위를 피하려는 데 있으므로 조정절차를 거치지 않았다고 무조건 정당성을 잃지는 않고 사회·경제적 안정 등 제반 사정을 따져 판단한다고 본다.","c":"중","v":1},"공인노2024_33-57-1":{"w":"노조법 제38조 제2항의 보안작업 유지 의무다.","c":"상","v":1},"공인노2024_33-57-3":{"w":"노조법 제38조 제1항이 쟁의행위와 관계없는 자나 근로를 제공하려는 자의 출입·조업 방해를 금지한다.","c":"상","v":1},"공인노2024_33-57-4":{"w":"노조법 제39조는 쟁의행위 기간 중 이 법 위반을 이유로 한 구속을 현행범인 경우로만 허용한다.","c":"상","v":1},"공인노2024_33-57-5":{"w":"노조법 제46조 제1항에 따라 직장폐쇄는 노동조합이 쟁의행위를 개시한 뒤에만 할 수 있다. 선제적 직장폐쇄는 허용되지 않는다.","c":"상","v":1},"공인노2024_33-58-1":{"w":"노조법 제44조 제2항이 쟁의기간 임금 지급 요구를 관철할 목적의 쟁의행위를 금지한다. 위반하면 제90조로 2년 이하 징역 또는 2천만원 이하 벌금이다.","c":"상","v":1},"공인노2024_33-58-2":{"w":"노조법 제41조 제2항에 따라 주요방위산업체의 전력·용수·주로 방산물자를 생산하는 업무 종사자는 쟁의행위를 할 수 없다. 방산물자 생산 업무의 범위는 시행령 제20조가 정한다.","c":"상","v":1},"공인노2024_33-58-3":{"w":"노조법 제42조 제1항이 생산 기타 주요업무 관련 시설 등의 점거 형태 쟁의행위를 금지한다. 점거 금지 시설은 시행령 제21조(전기·전산·통신시설, 철도 차량·선로 등)가 정한다.","c":"상","v":1},"공인노2024_33-58-4":{"w":"노조법 제45조 제1항이 노동쟁의 발생 시 어느 일방이 상대방에게 서면으로 통보하도록 정한다.","c":"상","v":1},"공인노2024_33-59-1":{"w":"노조법 시행령 제22조의2와 별표 1이 항공운수사업의 필수유지업무로 객실승무 업무를 정한다.","c":"중","v":1},"공인노2024_33-59-2":{"w":"노조법 제42조의2 제2항이 필수유지업무의 정당한 유지·운영을 정지·폐지·방해하는 쟁의행위를 금지한다. 위반하면 제89조 제1호로 처벌한다.","c":"상","v":1},"공인노2024_33-59-3":{"w":"노조법 제42조의3이 필수유지업무협정을 서면으로 체결하고 쌍방이 서명 또는 날인하도록 정한다.","c":"상","v":1},"공인노2024_33-59-5":{"w":"노조법 시행령 제22조의3 제1항에 따라 관할 노동위원회는 필수유지업무 수준 등 결정 신청을 받으면 지체 없이 특별조정위원회를 구성한다. 노조법 제42조의4 제3항이 이 결정을 특별조정위원회 담당으로 정한다.","c":"상","v":1},"공인노2025_34-55-2":{"w":"노조법 시행령 제18조에 따라 쟁의행위가 노조법 제38조 제1항 등에 위반되면 사용자는 즉시 행정관청과 관할 노동위원회에 신고해야 하고 신고는 서면·구두·전화 등 적당한 방법으로 할 수 있다.","c":"상","v":1},"공인노2025_34-55-3":{"w":"노조법 제41조 제1항에 따라 쟁의행위는 조합원의 직접·비밀·무기명투표로 조합원 과반수 찬성을 얻어 결정한다.","c":"상","v":1},"공인노2025_34-55-4":{"w":"노조법 제41조 제2항과 시행령 제20조에 따라 주로 방산물자를 생산하는 업무에는 방산물자 완성에 필요한 정비 업무가 포함되어 이 업무 종사자는 쟁의행위를 할 수 없다.","c":"상","v":1},"공인노2025_34-55-5":{"w":"노조법 제39조는 쟁의행위 기간 중 이 법 위반을 이유로 한 구속을 현행범인 경우로만 제한한다. 다른 법률 위반이나 현행범 구속은 막지 않는다.","c":"상","v":1},"공인노2025_34-56-3":{"w":"노조법 제42조의4 제5항은 필수유지업무 결정의 불복절차에 제69조를 준용하므로 지방노동위원회 결정이 위법·월권이면 송달받은 날부터 10일 이내에 중앙노동위원회에 재심을 신청할 수 있다.","c":"상","v":1},"공인노2025_34-57-1":{"w":"노조법 제43조 제3항·제4항에 따라 필수공익사업의 사용자는 쟁의기간 중 파업참가자의 100분의 50을 넘지 않는 범위에서 중단된 업무를 도급·하도급 줄 수 있다.","c":"상","v":1},"공인노2025_34-57-3":{"w":"대법원(2020년)은 수급인 근로자의 정당한 쟁의행위가 도급인 사업장에서 이루어져 도급인의 법익을 침해해도 항상 위법하지 않고 사회통념상 용인되는 행위로서 형법 제20조의 정당행위에 해당할 수 있다고 보았다.","c":"중","v":1},"공인노2025_34-57-4":{"w":"판례는 쟁의행위 찬반투표를 조정절차 전에 실시했다는 사정만으로 정당성이 상실되지 않는다고 본다. 노조법 제45조 제2항은 쟁의행위 자체의 개시 시점을 제한할 뿐 투표 시기를 정하지 않는다.","c":"중","v":1},"공인노2025_34-57-5":{"w":"대법원 전원합의체 판례(2011년)는 파업이 전격적으로 이루어져 사업운영에 심대한 혼란이나 막대한 손해를 초래할 위험이 있어 사용자의 사업계속에 관한 자유의사가 제압·혼란될 수 있다면 집단적 노무제공 거부가 위력에 해당해 업무방해죄가 성립한다고 보았다.","c":"중","v":1},"공인노2025_34-59-4":{"w":"판례는 직장폐쇄가 구체적 사정에 비추어 형평의 견지에서 근로자 쟁의행위에 대한 대항·방위 수단으로서 상당성이 인정될 때만 정당하다고 본다.","c":"중","v":1},"공인노2026_35-58-1":{"w":"노조법 제38조 제1항이 쟁의행위와 관계없는 자의 출입·조업 등 정상적 업무 방해를 금지한다.","c":"상","v":1},"공인노2026_35-58-2":{"w":"노조법 제38조 제2항은 작업시설 손상이나 원료·제품의 변질·부패를 막는 보안작업을 쟁의기간에도 계속하도록 한다. 위반하면 제91조로 처벌한다.","c":"상","v":1},"공인노2026_35-58-4":{"w":"판례는 사업장시설 점거가 일부분에 그치고 사용자 측의 출입이나 관리지배를 배제하지 않는 병존적 점거라면 정당한 쟁의행위로 볼 수 있다고 본다. 전면적·배타적 점거는 정당성이 없다.","c":"중","v":1},"공인노2026_35-58-5":{"w":"노조법 시행령 제20조가 주로 방산물자를 생산하는 업무에 성능검사 업무를 포함하므로 노조법 제41조 제2항에 따라 그 종사자는 쟁의행위를 할 수 없다.","c":"상","v":1},"공인노2026_35-59-2":{"w":"노조법 제43조 제3항·제4항에 따라 필수공익사업 사용자는 쟁의기간 중에 한해 파업참가자의 100분의 50 이내에서 대체채용할 수 있다.","c":"상","v":1},"공인노2026_35-59-3":{"w":"노조법 제43조 제4항 후단의 위임에 따라 시행령 제22조의4 제1항은 파업참가자 수를 근로의무가 있는 시간 중 파업 참가로 근로의 일부나 전부를 제공하지 않은 사람 수로 1일 단위로 센다고 정한다.","c":"상","v":1},"공인노2026_35-59-4":{"w":"노조법 제42조의4 제1항에 따라 필수유지업무협정이 체결되지 않으면 당사자 쌍방 또는 일방이 노동위원회에 결정을 신청해야 한다.","c":"상","v":1},"공인노2026_35-59-5":{"w":"노조법 시행령 제22조의3 제1항에 따라 관할 노동위원회는 결정 신청을 받으면 지체 없이 특별조정위원회를 구성한다. 노조법 제42조의4 제3항이 이 결정을 특별조정위원회 담당으로 정하기 때문이다.","c":"상","v":1},"공인노2026_35-65-2":{"w":"노조법 제3조 제1항(2025.9.9 개정, 2026.3.10 시행)은 이 법에 따른 단체교섭·쟁의행위·그 밖의 노동조합 활동으로 손해를 입은 사용자가 노동조합 또는 근로자에게 배상을 청구할 수 없다고 정한다.","c":"상","v":1},"공인노2017_26-35-1":{"w":"노조법 제52조 제3항 제2호에 따라 사적 중재로 해결하기로 하면 제63조의 쟁의행위 금지기간(15일)을 중재를 개시한 날부터 센다.","c":"상","v":1},"공인노2017_26-35-3":{"w":"노조법 제72조 제1항이 공익사업 노동쟁의 조정을 위해 노동위원회에 특별조정위원회를 두도록 한다.","c":"상","v":1},"공인노2017_26-35-4":{"w":"노조법 제61조의2 제1항이 정한 조정종료 결정 후의 조정(사후조정)이다.","c":"상","v":1},"공인노2017_26-35-5":{"w":"노조법 제52조 제3항 제1호에 따라 사적 조정에는 제54조(일반 10일, 공익 15일)가 적용되고 조정기간은 조정을 개시한 날부터 센다.","c":"상","v":1},"공인노2019_28-40-2":{"w":"노조법 제48조가 노동관계 당사자에게 노동쟁의를 자주적으로 해결하도록 노력할 책무를 지운다.","c":"상","v":1},"공인노2019_28-40-3":{"w":"노조법 제49조가 정한 국가·지방자치단체의 책무다.","c":"상","v":1},"공인노2019_28-40-4":{"w":"노조법 제50조는 조정 시 노동관계 당사자와 노동위원회 기타 관계기관이 사건을 신속히 처리하도록 노력하라고 정한다.","c":"상","v":1},"공인노2019_28-40-5":{"w":"노조법 제47조는 제5장 조정 규정이 당사자의 직접 노사협의나 단체교섭에 의한 자주적 해결을 방해하지 않는다고 정한다.","c":"상","v":1},"공인노2019_28-41-1":{"w":"노조법 제61조의2 제1항에 따라 노동위원회는 제60조 제2항의 조정 종료 결정 뒤에도 노동쟁의 해결을 위해 조정을 할 수 있다. 이 사후조정을 거치지 않아도 쟁의행위는 할 수 있다(제45조 제2항 괄호).","c":"상","v":1},"공인노2022_31-37-1":{"w":"노조법 제53조 제1항에 따라 노동위원회는 일방이 조정을 신청하면 지체 없이 조정을 개시하고 당사자 쌍방은 성실히 임해야 한다.","c":"상","v":1},"공인노2022_31-37-2":{"w":"노조법 제54조 제1항이 정한 조정기간이다. 합의로 일반사업 10일, 공익사업 15일 이내에서 연장할 수 있다(같은 조 제2항).","c":"상","v":1},"공인노2022_31-37-4":{"w":"노조법 제57조 제1항이 정한 단독조정이다.","c":"상","v":1},"공인노2022_31-37-5":{"w":"노조법 제92조 제3호에 따라 제61조 제1항의 조정서 내용을 준수하지 않은 자는 1천만원 이하 벌금에 처한다.","c":"상","v":1},"공인노2022_31-38-2":{"w":"노조법 제62조 제2호가 정한 중재 개시 사유다.","c":"상","v":1},"공인노2024_33-60-2":{"w":"노조법 제52조 제2항이 정한 신고 의무다. 시행령 제23조 제1항은 관할 노동위원회에 신고하도록 한다.","c":"상","v":1},"공인노2024_33-60-3":{"w":"노조법 제52조 제4항에 따라 사적 조정·중재가 이루어지면 그 내용은 단체협약과 같은 효력을 가진다.","c":"상","v":1},"공인노2024_33-60-4":{"w":"노조법 제52조 제1항은 당사자가 합의나 단체협약에 따라 노동위원회 조정·중재 대신 다른 방법(사적조정·중재)을 택할 수 있게 한다.","c":"상","v":1},"공인노2024_33-60-5":{"w":"노조법 제52조 제5항에 따라 사적조정인은 노동위원회법 제8조 제2항 제2호 각 목의 자격을 갖춰야 하고 당사자로부터 수수료·수당·여비 등을 받을 수 있다.","c":"상","v":1},"공인노2024_33-62-5":{"w":"노조법 제72조 제3항 단서에 따라 당사자가 합의로 노동위원회 위원이 아닌 사람을 추천하면 위원장은 그 사람을 특별조정위원으로 지명한다. 원칙은 공익위원 중 순차배제하고 남은 4~6인 중에서 지명하는 것이다(같은 항 본문).","c":"상","v":1},"공인노2024_33-63-1":{"w":"노조법 제68조 제1항이 중재재정을 서면으로 하고 효력발생 기일을 적도록 정한다.","c":"상","v":1},"공인노2024_33-63-2":{"w":"노조법 제68조 제2항에 따라 중재재정의 해석·이행방법에 다툼이 있으면 그 중재위원회의 해석에 따르고 그 해석은 중재재정과 같은 효력을 가진다.","c":"상","v":1},"공인노2024_33-63-3":{"w":"노조법 시행령 제29조 제2항에 따라 중앙노동위원회는 재심결정서를 관계 당사자와 관계 노동위원회에 지체 없이 송달한다.","c":"상","v":1},"공인노2024_33-63-5":{"w":"노조법 제70조 제2항에 따라 재심신청이나 행정소송을 제기해도 중재재정·재심결정의 효력은 정지되지 않는다.","c":"상","v":1},"공인노2025_34-60-1":{"w":"노조법 제60조 제3항에 따라 수락된 조정안의 해석·이행방법에 다툼이 있으면 당사자는 그 조정위원회나 단독조정인에게 견해 제시를 요청해야 한다.","c":"상","v":1},"공인노2025_34-60-2":{"w":"노조법 시행령 제27조가 조정안 해석·이행방법 견해 요청을 조정안 내용과 당사자 의견을 적은 서면으로 하도록 정한다.","c":"상","v":1},"공인노2025_34-60-3":{"w":"노조법 제60조 제3항·제4항에 따라 수락된 조정안의 해석·이행방법에 다툼이 있어 단독조정인에게 견해 제시를 요청하면 단독조정인은 요청받은 날부터 7일 이내에 견해를 제시해야 한다.","c":"상","v":1},"공인노2025_34-60-4":{"w":"노조법 제60조 제5항에 따라 해석·이행방법 견해가 나올 때까지 당사자는 그 조정안의 해석·이행에 관하여 쟁의행위를 할 수 없다.","c":"상","v":1},"공인노2025_34-61-1":{"w":"노조법 제47조는 노동쟁의 조정 규정(제5장)이 당사자의 직접 노사협의나 단체교섭에 의한 자주적 해결을 방해하지 않는다고 정한다.","c":"상","v":1},"공인노2025_34-61-2":{"w":"노조법 제50조는 조정 시 노동관계 당사자와 노동위원회 기타 관계기관에 신속 처리 노력 의무를 지운다.","c":"상","v":1},"공인노2025_34-61-3":{"w":"노조법 제51조가 국가·지방자치단체·국공영기업체·방위산업체·공익사업 노동쟁의 조정을 우선 취급하도록 정한다.","c":"상","v":1},"공인노2025_34-61-4":{"w":"노조법 제49조는 국가와 지방자치단체가 당사자의 자주적 조정을 돕고 쟁의행위 예방과 신속·공정한 해결에 노력하도록 정한다.","c":"상","v":1},"공인노2025_34-64-1":{"w":"노조법 제67조에 따라 중재위원회 위원장은 관계 당사자와 참고인 외의 사람의 회의 출석을 금할 수 있다. 조정에도 같은 규정이 있다(제59조).","c":"상","v":1},"공인노2025_34-64-2":{"w":"노조법 제63조에 따라 노동쟁의가 중재에 회부되면 그날부터 15일간 쟁의행위를 할 수 없다. 위반하면 제91조로 처벌한다.","c":"상","v":1},"공인노2025_34-64-3":{"w":"노조법 제64조 제3항 본문에 따라 중재위원은 공익위원 중 당사자가 합의로 선정한 자를 위원장이 지명한다. 합의가 안 되면 공익위원 중에서 위원장이 지명한다(같은 항 단서).","c":"상","v":1},"공인노2025_34-64-5":{"w":"노조법 시행령 제28조가 노조법 제62조에 따라 중재를 하게 되면 지체 없이 중재위원회를 구성하도록 정한다.","c":"상","v":1},"공인노2025_34-66-1":{"w":"노조법 제68조 제1항이 중재재정을 서면으로 하고 효력발생 기일을 적도록 정한다.","c":"상","v":1},"공인노2025_34-66-2":{"w":"노조법 제69조 제1항에 따라 지방·특별노동위원회의 중재재정이 위법이거나 월권이면 송달받은 날부터 10일 이내에 중앙노동위원회에 재심을 신청할 수 있다.","c":"상","v":1},"공인노2025_34-66-3":{"w":"노조법 시행령 제29조 제2항에 따라 재심결정서는 관계 당사자와 관계 노동위원회에 지체 없이 송달한다.","c":"상","v":1},"공인노2025_34-66-4":{"w":"노조법 제68조 제2항에 따라 그 중재위원회의 해석에 따르고 그 해석은 중재재정과 같은 효력을 가진다.","c":"상","v":1},"공인노2025_34-69-1":{"w":"노조법 제76조 제1항이 고용노동부장관의 긴급조정 결정 요건을 정한다. 결정하려면 미리 중앙노동위원회 위원장의 의견을 들어야 한다(같은 조 제2항).","c":"상","v":1},"공인노2025_34-69-2":{"w":"노조법 제76조 제2항에 따라 고용노동부장관은 미리 중앙노동위원회 위원장의 의견을 듣고 제3항에 따라 긴급조정 결정 시 이유를 붙여 공표하고 중앙노동위원회와 당사자에게 통고한다.","c":"상","v":1},"공인노2025_34-69-4":{"w":"노조법 시행령 제32조가 정한 공표 방법이다.","c":"상","v":1},"공인노2025_34-69-5":{"w":"노조법 제79조 제1항에 따라 긴급조정에서 조정 성립 가망이 없으면 중앙노동위원회 위원장이 공익위원 의견을 들어 중재회부 여부를 결정한다. 이 결정은 통고를 받은 날부터 15일 이내에 한다(같은 조 제2항).","c":"상","v":1},"공인노2026_35-60-2":{"w":"노조법 제54조 제1항이 정한 조정기간이다.","c":"상","v":1},"공인노2026_35-60-3":{"w":"노조법 제51조가 국가·지방자치단체·국공영기업체·방위산업체·공익사업의 노동쟁의 조정을 우선 취급하고 신속히 처리하도록 정한다.","c":"상","v":1},"공인노2026_35-60-4":{"w":"노조법 제57조 제1항에 따라 당사자 쌍방이 신청하거나 동의하면 조정위원회 대신 단독조정인이 조정할 수 있다. 단독조정인은 쌍방 합의로 선정된 위원 중에서 위원장이 지명한다(같은 조 제2항).","c":"상","v":1},"공인노2026_35-60-5":{"w":"노조법 제58조는 조정위원회나 단독조정인이 기일을 정해 당사자 쌍방을 출석시켜 주장의 요점을 확인하도록 정한다.","c":"상","v":1},"공인노2026_35-61-1":{"w":"노조법 제61조 제2항에 따라 수락된 조정안으로 작성한 조정서는 단체협약과 같은 효력을 가진다.","c":"상","v":1},"공인노2026_35-61-2":{"w":"노조법 제61조 제3항에 따라 조정위원회가 제60조 제4항에 따라 제시한 해석·이행방법 견해는 중재재정과 같은 효력을 가진다.","c":"상","v":1},"공인노2026_35-61-3":{"w":"노조법 제70조 제1항에 따라 중재재정의 내용은 단체협약과 같은 효력을 가진다.","c":"상","v":1},"공인노2026_35-61-5":{"w":"노조법 제60조 제2항(조정 종료 결정)과 제61조의2 제1항(종료 후 조정)을 합친 내용이다.","c":"상","v":1},"공인노2026_35-62-1":{"w":"노조법 제62조 제2호에 따라 일방이 단체협약에 근거해 중재를 신청하면 노동위원회는 중재를 한다. 쌍방이 함께 신청한 경우도 같다(제1호).","c":"상","v":1},"공인노2026_35-62-3":{"w":"노조법 제65조 제2항에 따라 중재위원회 위원장은 중재위원 중에서 호선한다.","c":"상","v":1},"공인노2026_35-62-4":{"w":"노조법 제68조 제1항이 중재재정을 서면으로 하고 효력발생 기일을 적도록 정한다.","c":"상","v":1},"공인노2026_35-62-5":{"w":"노조법 제69조 제1항에 따라 위법 또는 월권이면 10일 이내에 중앙노동위원회에 재심을 신청할 수 있다.","c":"상","v":1},"공인노2019_28-45-1":{"w":"판례는 부당노동행위의 성립 요건 사실에 대한 증명책임을 이를 주장하는 근로자나 노동조합에 지운다. 부당해고 사건에서 사용자가 해고의 정당성을 증명해야 하는 것과 다르다.","c":"중","v":1},"공인노2019_28-45-2":{"w":"판례는 해고 사유로 내세운 것과 달리 실질적으로 정당한 조합활동을 이유로 해고했다면 노조법 제81조 제1항 제1호의 부당노동행위로 본다. 사용자의 부당노동행위 의사는 해고 경위·시기·다른 근로자와의 형평 등 제반 사정으로 추정한다.","c":"중","v":1},"공인노2019_28-45-4":{"w":"노조법 제81조 제1항 제1호가 노동조합 업무를 위한 정당한 행위를 이유로 한 해고 등 불이익 취급을 부당노동행위로 정한다.","c":"상","v":1},"공인노2019_28-45-5":{"w":"판례는 연장근로 허가 의무가 일반적으로 없더라도 파업 참가를 이유로 특정 근로자에게만 연장근로를 거부하면 경제적 불이익을 주는 것이어서 노조법 제81조 제1항 제1호·제5호의 불이익 취급이 될 수 있다고 본다.","c":"중","v":1},"공인노2019_28-46-1":{"w":"판례는 노동위원회의 구제명령이 사용자에게 이행해야 할 공법상 의무를 지울 뿐 노사 간 사법상 법률관계를 직접 발생·변경시키지 않는다고 본다. 그래서 사법상 권리 확정은 별도로 민사소송으로 다툰다.","c":"중","v":1},"공인노2019_28-46-2":{"w":"노조법 제82조 제2항이 정한 구제신청 기간이다. 이 기간은 제척기간이어서 지나면 구제신청은 각하된다.","c":"상","v":1},"공인노2019_28-46-3":{"w":"노조법 제83조 제3항은 부당노동행위 심문에서 당사자에게 증거 제출과 증인 반대심문의 충분한 기회를 주도록 정한다. 증인은 당사자 신청이나 직권으로 출석시킬 수 있다(같은 조 제2항).","c":"상","v":1},"공인노2019_28-46-5":{"w":"노조법 제85조 제5항이 정한 긴급이행명령이다. 이를 위반하면 제95조로 과태료를 부과한다.","c":"상","v":1},"공인노2022_31-44-2":{"w":"노조법 제81조 제1항 제4호 단서가 근로자의 후생자금 또는 경제상 불행 그 밖의 재해 방지·구제 등을 위한 기금 기부를 예외로 정한다.","c":"상","v":1},"공인노2022_31-44-3":{"w":"노조법 제81조 제1항 제2호 단서가 근로자 3분의 2 이상을 대표하는 노동조합의 유니언 숍 협정을 예외로 허용한다. 다만 제명·탈퇴 후 신규 조직·다른 노조 가입을 이유로 한 신분상 불이익은 금지된다.","c":"상","v":1},"공인노2022_31-44-4":{"w":"노조법 제81조 제1항 제4호 단서가 최소한의 규모의 노동조합사무소 제공을 예외로 정한다.","c":"상","v":1},"공인노2022_31-44-5":{"w":"노조법 제81조 제1항 제3호가 노동조합 대표자 또는 노동조합으로부터 위임을 받은 자와의 교섭을 정당한 이유 없이 거부·해태하는 행위를 부당노동행위로 정한다.","c":"상","v":1},"공인노2022_31-46-3":{"w":"노조법 제82조 제2항 괄호에 따라 계속하는 부당노동행위는 그 종료일부터 3개월 이내에 구제를 신청한다.","c":"상","v":1},"공인노2024_33-52-1":{"w":"노조법 제81조 제1항 제4호 본문은 운영비 원조를 금지하고 단서는 자주적 운영·활동을 침해할 위험이 없는 범위의 운영비 원조를 예외로 둔다. 2018년 헌법불합치 결정을 반영해 2020년 개정되었다.","c":"상","v":1},"공인노2024_33-52-3":{"w":"노조법 제84조 제1항에 따라 노동위원회는 부당노동행위가 성립하면 구제명령을, 성립하지 않으면 기각결정을 해야 한다. 판정·명령·결정은 서면으로 사용자와 신청인에게 각각 교부한다(같은 조 제2항).","c":"상","v":1},"공인노2024_33-52-4":{"w":"판례는 지배·개입의 부당노동행위가 성립하려면 단결권을 침해하려는 의사에 기한 행위가 있으면 되고 단결권 침해라는 결과가 실제로 발생할 필요는 없다고 본다.","c":"중","v":1},"공인노2024_33-52-5":{"w":"노조법 제86조에 따라 구제명령은 재심신청이나 행정소송 제기로 효력이 정지되지 않는다.","c":"상","v":1},"공인노2025_34-62-2":{"w":"노조법 제89조 제2호에 따라 확정된 구제명령(제85조 제3항 등)을 위반한 자는 3년 이하 징역 또는 3천만원 이하 벌금에 처한다.","c":"상","v":1},"공인노2025_34-62-3":{"w":"노조법 제85조 제1항에 따라 지방노동위원회의 구제명령이나 기각결정에 불복하는 당사자는 송달받은 날부터 10일 이내에 중앙노동위원회에 재심을 신청할 수 있다.","c":"상","v":1},"공인노2025_34-62-4":{"w":"노조법 제81조 제1항 제1호의 불이익 취급이다. 판례는 그 요건 사실의 주장·증명책임을 부당노동행위라고 주장하는 근로자나 노동조합에 지운다.","c":"중","v":1},"공인노2025_34-62-5":{"w":"대법원은 부당노동행위 구제명령의 대상인 사용자를 근로계약상 사용자에 한정하지 않고 구제명령을 이행할 법률적·사실적 권한이나 능력이 있는 지위에 있으면 그 한도에서 사용자로 보았다(원청의 지배·개입 사건).","c":"중","v":1},"공인노2025_34-63-2":{"w":"대법원은 특정 노동조합에 가입하려 하거나 연대하려는 노동조합에 대한 부당노동행위로 그 특정 노동조합의 권리가 침해될 수 있으면 그 노조가 직접 상대방이 아니어도 자기 이름으로 구제신청을 할 수 있다고 보았다.","c":"중","v":1},"공인노2025_34-63-3":{"w":"노조법 제81조 제1항 제4호 단서가 자주적 운영·활동을 침해할 위험이 없는 범위의 운영비 원조를 예외로 정한다. 그 판단 기준은 같은 조 제2항(목적·경위, 횟수·기간, 금액·방법, 총수입 대비 비율, 관리방법·사용처)이다.","c":"상","v":1},"공인노2025_34-63-4":{"w":"노조법 제81조 제1항 제3호가 노조 대표자나 위임받은 자와의 협약 체결 등 단체교섭을 정당한 이유 없이 거부·해태하는 행위를 부당노동행위로 정한다.","c":"상","v":1},"공인노2025_34-63-5":{"w":"노조법 제85조 제5항에 따라 사용자가 행정소송을 내면 관할법원은 중앙노동위원회 신청으로 판결 확정 시까지 구제명령의 전부나 일부를 이행하도록 결정할 수 있다. 위반하면 제95조로 과태료를 부과한다.","c":"상","v":1},"공인노2026_35-63-5":{"w":"판례는 노동조합이 소속 조합원이나 가입하려는 근로자에 대한 부당노동행위로 노동조합 자신의 단결권 등이 침해될 수 있으므로 노조 자신의 이름으로 구제신청을 할 수 있다고 본다. 노조법 제82조 제1항도 신청인을 근로자 또는 노동조합으로 정한다.","c":"중","v":1},"공인노2026_35-64-3":{"w":"노조법 제82조 제2항 괄호가 계속하는 행위는 종료일부터 3개월 이내에 신청하도록 정한다.","c":"상","v":1},"공인노2019_28-48-1":{"w":"노동위원회법 제2조 제1항이 노동위원회를 중앙·지방·특별노동위원회로 나눈다.","c":"상","v":1},"공인노2019_28-48-3":{"w":"노동위원회법 제17조의2 제2항에 따라 처분의 효력은 판정서·명령서·결정서 또는 재심판정서를 송달받은 날부터 발생한다.","c":"상","v":1},"공인노2019_28-48-4":{"w":"노동위원회법 제27조 제1항에 따라 중앙노동위원회 처분에 대한 소송은 중앙노동위원회 위원장을 피고로 하여 송달받은 날부터 15일 이내에 제기한다.","c":"상","v":1},"공인노2019_28-48-5":{"w":"노동위원회법 제31조 제1호에 따라 노동위원회의 보고·서류제출 요구에 응하지 않거나 거짓 보고·서류를 낸 자는 500만원 이하 벌금에 처한다.","c":"상","v":1},"공인노2022_31-47-1":{"w":"노동위원회법 제6조 제4항이 정한 공익위원 위촉 절차(위원장·노조·사용자단체 추천 후 순차배제)다.","c":"상","v":1},"공인노2022_31-47-2":{"w":"노동위원회법 제15조의2 제2호에 따라 당사자 양쪽이 단독심판을 신청하거나 동의하면 위원장은 공익위원 1명을 지명해 사건을 처리하게 할 수 있다. 신청 요건을 명백히 갖추지 못한 경우도 같다(제1호).","c":"상","v":1},"공인노2022_31-47-4":{"w":"노동위원회법 제27조 제1항이 중앙노동위원회 처분에 대한 소송의 피고를 중앙노동위원회 위원장으로 정한다. 제소기간은 송달받은 날부터 15일이다.","c":"상","v":1},"공인노2022_31-47-5":{"w":"노동위원회법 제16조의3 제5항에 따라 화해조서는 민사소송법상 재판상 화해의 효력을 가진다.","c":"상","v":1},"공인노2024_33-68-1":{"w":"노동위원회법 제16조의3 제1항에 따라 노조법 제84조의 판정·명령·결정 전까지 당사자 신청을 받아 화해를 권고하거나 화해안을 제시할 수 있다.","c":"상","v":1},"공인노2024_33-68-2":{"w":"노동위원회법 제16조의3 제1항은 당사자 신청뿐 아니라 직권으로도 화해를 권고하거나 화해안을 제시할 수 있게 한다.","c":"상","v":1},"공인노2024_33-68-3":{"w":"노동위원회법 제16조의3 제3항이 정한 화해조서 작성 의무다.","c":"상","v":1},"공인노2024_33-68-4":{"w":"노동위원회법 제16조의3 제5항에 따라 화해조서는 민사소송법상 재판상 화해와 같은 효력이 있어 확정판결과 같은 효력을 가진다.","c":"상","v":1},"공인노2024_33-69-3":{"w":"노동위원회법 제17조의3 제2항·제3항이 정한 공시송달 방법과 효력발생 시기다.","c":"상","v":1},"공인노2024_33-70-1":{"w":"노동위원회법 제22조 제1항에 따라 노동위원회는 관계 행정기관에 협조를 요청할 수 있고 요청받은 기관은 특별한 사유가 없으면 따라야 한다.","c":"상","v":1},"공인노2024_33-70-3":{"w":"노동위원회법 제24조에 따라 중앙노동위원회는 지방·특별노동위원회에 사무 처리 기본방침과 법령 해석에 관한 지시를 할 수 있다.","c":"상","v":1},"공인노2024_33-70-4":{"w":"노동위원회법 제26조 제1항이 정한 재심권이다. 재심 신청은 처분을 송달받은 날부터 10일 이내에 한다(같은 조 제2항).","c":"상","v":1},"공인노2024_33-70-5":{"w":"노동위원회법 제27조 제1항이 정한 제소기간(15일)과 피고(중앙노동위원회 위원장)다. 이 기간은 불변기간이다(같은 조 제3항).","c":"상","v":1},"공인노2025_34-75-1":{"w":"노동위원회법 제16조 제1항에 따라 부문별 위원회 위원장은 다른 법률에 특별한 규정이 없으면 그 위원 중에서 호선한다.","c":"상","v":1},"공인노2025_34-76-1":{"w":"노동위원회법 제9조 제1항에 따라 노동위원회마다 위원장 1명을 둔다. 중앙노동위원회 위원장은 정무직이다(같은 조 제3항).","c":"상","v":1},"공인노2025_34-76-2":{"w":"노동위원회법 제9조 제4항(위원장)과 제11조 제2항(상임위원)이 위원장과 상임위원을 해당 노동위원회의 공익위원으로 하고 심판·차별시정·조정사건을 담당할 수 있게 한다.","c":"상","v":1},"공인노2025_34-76-3":{"w":"노동위원회법 제10조 제1항에 따라 위원장은 노동위원회를 대표하고 사무를 총괄한다.","c":"상","v":1},"공인노2025_34-76-4":{"w":"노동위원회법 제11조 제1항에 따라 상임위원은 공익위원 자격자 중에서 중앙노동위원회 위원장의 추천과 고용노동부장관의 제청으로 대통령이 임명한다.","c":"상","v":1},"공인노2026_35-70-1":{"w":"노동위원회법 제2조 제1항이 노동위원회를 중앙·지방·특별노동위원회로 나눈다.","c":"상","v":1},"공인노2026_35-70-2":{"w":"노동위원회법 제3조 제1항 제1호에 따라 중앙노동위원회는 지방노동위원회와 특별노동위원회 처분에 대한 재심사건을 관장한다.","c":"상","v":1},"공인노2026_35-70-3":{"w":"노동위원회법 제2조 제2항이 중앙노동위원회와 지방노동위원회를 고용노동부장관 소속으로 둔다. 특별노동위원회는 해당 사항을 관장하는 중앙행정기관의 장 소속이다(같은 조 제3항).","c":"상","v":1},"공인노2026_35-70-5":{"w":"노동위원회법 제3조 제1항 제3호가 정한 중앙노동위원회 관장 사건이다.","c":"상","v":1},"공인노2026_35-73-1":{"w":"노동위원회법 제16조의3 제4항이 화해조서에 관계 당사자와 화해에 관여한 부문별 위원회 위원 전원이 서명·날인하도록 정한다.","c":"상","v":1},"공인노2026_35-73-2":{"w":"노동위원회법 제16조의3 제1항이 판정·명령·결정 전까지 직권 화해 권고를 허용한다.","c":"상","v":1},"공인노2026_35-73-3":{"w":"노동위원회법 제16조의3 제2항에 따라 노동위원회는 화해안을 작성할 때 당사자의 의견을 충분히 들어야 한다.","c":"상","v":1},"공인노2026_35-73-4":{"w":"노동위원회법 제16조의3 제3항에 따라 당사자가 화해안을 수락하면 노동위원회는 화해조서를 작성해야 한다.","c":"상","v":1},"공인노2017_26-47-1":{"w":"근로자참여법 제4조 제1항은 근로조건 결정권이 있는 사업·사업장 단위로 노사협의회를 설치하되 상시 30명 미만 사업장은 제외한다.","c":"상","v":1},"공인노2017_26-47-2":{"w":"근로자참여법 제4조 제2항이 지역을 달리하는 사업장에도 노사협의회를 설치할 수 있게 한다.","c":"상","v":1},"공인노2017_26-47-3":{"w":"근로자참여법 제6조 제3항(2022년 신설)에 따라 과반수 노조가 있으면 근로자위원은 노조 대표자와 그 노조가 위촉하는 자로 한다.","c":"상","v":1},"공인노2017_26-47-4":{"w":"근로자참여법 제6조 제4항에 따라 사용자위원은 해당 사업·사업장의 대표자와 그 대표자가 위촉하는 자로 한다.","c":"상","v":1},"공인노2022_31-50-1":{"w":"근로자참여법 제4조 제1항이 노사협의회를 근로조건 결정권이 있는 사업이나 사업장 단위로 설치하도록 정한다.","c":"상","v":1},"공인노2022_31-50-2":{"w":"근로자참여법 시행령 제2조에 따라 하나의 사업 전체 근로자 수가 30명 이상이면 근로자가 지역별로 흩어져 있어도 주된 사무소에 노사협의회를 설치해야 한다.","c":"상","v":1},"공인노2022_31-50-3":{"w":"근로자참여법 제21조 제1호가 근로자의 교육훈련 및 능력개발 기본계획 수립을 의결사항으로 정한다.","c":"상","v":1},"공인노2022_31-50-4":{"w":"근로자참여법 제20조 제1항 제8호가 정한 협의사항이다.","c":"상","v":1},"공인노2024_33-65-1":{"w":"근로자참여법 제12조가 3개월마다 정기회의를 열고 필요하면 임시회의를 열도록 정한다. 정기회의를 열지 않으면 제32조로 200만원 이하 벌금이다.","c":"상","v":1},"공인노2024_33-65-2":{"w":"근로자참여법 제13조 제3항에 따라 의장은 회의 개최 7일 전에 일시·장소·의제를 각 위원에게 알려야 한다.","c":"상","v":1},"공인노2024_33-65-4":{"w":"근로자참여법 제16조에 따라 노사협의회 회의는 공개가 원칙이고 협의회 의결로 비공개할 수 있다.","c":"상","v":1},"공인노2024_33-65-5":{"w":"근로자참여법 제15조에 따라 회의는 근로자위원과 사용자위원 각 과반수 출석으로 열고 출석위원 3분의 2 이상 찬성으로 의결한다.","c":"상","v":1},"공인노2024_33-66-1":{"w":"근로자참여법 제30조 제1호에 따라 노사협의회 설치를 정당한 사유 없이 거부·방해한 자는 1천만원 이하 벌금에 처한다.","c":"상","v":1},"공인노2024_33-66-2":{"w":"근로자참여법 제30조 제2호에 따라 의결 사항을 정당한 사유 없이 이행하지 않은 자는 1천만원 이하 벌금에 처한다.","c":"상","v":1},"공인노2024_33-66-3":{"w":"근로자참여법 제30조 제3호에 따라 임의 중재 결정을 정당한 사유 없이 이행하지 않은 자는 1천만원 이하 벌금에 처한다.","c":"상","v":1},"공인노2024_33-66-5":{"w":"근로자참여법 제33조 제1항이 정한 과태료다. 협의회규정은 설치일부터 15일 이내에 제출해야 한다(제18조 제1항).","c":"상","v":1},"공인노2024_33-72-1":{"w":"근로자참여법 제28조 제2항에 따라 고충처리위원이 처리하기 곤란한 사항은 노사협의회 회의에 부쳐 협의 처리한다. 고충처리위원은 고충을 들은 날부터 10일 이내에 처리결과를 통보해야 한다(같은 조 제1항).","c":"상","v":1},"공인노2025_34-67-1":{"w":"근로자참여법 제6조 제1항에 따라 노사협의회는 노사 같은 수의 위원으로 각 3명 이상 10명 이하로 구성한다.","c":"상","v":1},"공인노2025_34-67-2":{"w":"근로자참여법 제6조 제3항(2022년 신설)에 따라 근로자 과반수로 조직된 노조가 있으면 근로자위원은 그 노조 대표자와 노조가 위촉하는 자로 한다. 그 외에는 근로자 과반수가 참여한 직접·비밀·무기명 투표로 선출한다(같은 조 제2항).","c":"상","v":1},"공인노2025_34-67-3":{"w":"근로자참여법 제6조 제4항에 따라 사용자위원은 해당 사업·사업장의 대표자와 그 대표자가 위촉하는 자로 한다.","c":"상","v":1},"공인노2025_34-67-4":{"w":"근로자참여법 시행령 제3조가 근로자위원 선출에 입후보하려는 사람을 해당 사업·사업장의 근로자로 한정한다.","c":"상","v":1},"공인노2025_34-70-4":{"w":"근로자참여법 제5조(노동조합과의 관계)가 노동조합의 단체교섭 등 모든 활동은 이 법의 영향을 받지 않는다고 정한다.","c":"상","v":1},"공인노2025_34-71-1":{"w":"근로자참여법 제7조 제1항에 따라 의장은 위원 중에서 호선하고 근로자위원과 사용자위원 중 각 1명을 공동의장으로 할 수 있다.","c":"상","v":1},"공인노2025_34-71-3":{"w":"근로자참여법 제9조 제2항이 직무 수행과 관련한 근로자위원 불이익 처분을 금지한다. 위반하면 고용노동부장관이 시정을 명할 수 있다(제11조).","c":"상","v":1},"공인노2025_34-71-4":{"w":"근로자참여법 제10조 제1항이 근로자위원 선출 개입·방해를 금지한다. 위반 시 시정명령 대상이고(제11조) 시정명령 불이행은 제31조로 500만원 이하 벌금이다.","c":"상","v":1},"공인노2025_34-71-5":{"w":"근로자참여법 제10조 제2항이 사용자에게 근로자위원 업무를 위한 장소 사용 등 기본 편의 제공 의무를 지운다.","c":"상","v":1},"공인노2026_35-66-1":{"w":"근로자참여법 제12조 제1항에 따라 노사협의회는 3개월마다 정기회의를 열어야 한다.","c":"상","v":1},"공인노2026_35-66-3":{"w":"근로자참여법 제13조 제2항에 따라 노사 일방의 대표자가 회의 목적을 문서로 밝혀 소집을 요구하면 의장은 따라야 한다.","c":"상","v":1},"공인노2026_35-66-4":{"w":"근로자참여법 제13조 제3항이 회의 개최 7일 전 통보 의무를 정한다.","c":"상","v":1},"공인노2026_35-66-5":{"w":"근로자참여법 시행령 제5조 제2항에 따라 협의회규정의 제정·변경은 협의회 의결을 거쳐야 한다.","c":"상","v":1},"공인노2026_35-68-1":{"w":"근로자참여법 시행령 제8조 제1항에 따라 고충처리위원은 비상임·무보수다. 노사협의회 위원도 같다(법 제9조 제1항).","c":"상","v":1},"공인노2026_35-68-2":{"w":"근로자참여법 시행령 제8조 제3항에 따라 고충처리 협의나 업무에 쓴 시간은 근로한 시간으로 본다.","c":"상","v":1},"공인노2026_35-68-3":{"w":"근로자참여법 시행령 제8조 제2항이 고충처리위원 직무수행과 관련한 불리한 처분을 금지한다.","c":"상","v":1},"공인노2026_35-68-4":{"w":"근로자참여법 제27조 제1항에 따라 고충처리위원은 노사를 대표하는 3명 이내로 구성하고 협의회가 있으면 협의회가 위원 중에서 선임한다.","c":"상","v":1},"공인노2017_26-48-4":{"w":"교원노조법 제6조 제8항이 단체교섭·협약 체결 시 국민여론과 학부모 의견을 수렴해 성실히 교섭하고 권한을 남용하지 않도록 정한다.","c":"상","v":1},"공인노2017_26-49-1":{"w":"공무원노조법 제8조 제4항 전단에 따라 정부교섭대표는 효율적 교섭을 위해 정부교섭대표가 아닌 관계 기관의 장을 교섭에 참여하게 할 수 있다.","c":"상","v":1},"공인노2017_26-49-3":{"w":"공무원노조법 제12조 제1항에 따라 교섭이 결렬되면 당사자 어느 한쪽 또는 양쪽이 중앙노동위원회에 조정을 신청할 수 있다.","c":"상","v":1},"공인노2017_26-49-4":{"w":"공무원노조법 제10조 제1항은 법령·조례·예산으로 규정되는 내용을 단체협약으로서 효력이 없다고 하고 제2항은 정부교섭대표가 그 내용이 이행되도록 성실히 노력하도록 정한다.","c":"상","v":1},"공인노2017_26-49-5":{"w":"공무원노조법 제5조 제2항에 따라 설립신고서는 고용노동부장관에게 낸다. 교원노조도 같다(교원노조법 제4조 제3항).","c":"상","v":1},"공인노2019_28-49-4":{"w":"교원노조법 제7조 제1항에 따라 법령·조례·예산으로 규정되는 내용과 법령·조례의 위임으로 규정되는 내용은 단체협약으로서 효력이 없다. 사립학교 설립·경영자와 맺은 협약도 같다.","c":"상","v":1},"공인노2019_28-50-1":{"w":"공무원노조법 제3조 제2항은 노조 활동을 할 때도 다른 법령상 공무원의 의무에 반하는 행위를 금지한다. 노조 조직·가입과 정당한 활동에는 국가공무원법 제66조 제1항(집단행위 금지)이 적용되지 않는다(같은 조 제1항).","c":"상","v":1},"공인노2019_28-50-3":{"w":"공무원노조법 제9조 제2항이 교섭하려는 사항에 권한을 가진 정부교섭대표에게 서면으로 교섭을 요구하도록 정한다.","c":"상","v":1},"공인노2022_31-48-2":{"w":"공무원노조법 제7조 제2항이 전임자에게 그 기간 중 국가공무원법 제71조 또는 지방공무원법 제63조에 따른 휴직명령을 하도록 정한다.","c":"상","v":1},"공인노2022_31-48-3":{"w":"공무원노조법 제8조 제2항이 정한 정부교섭대표의 교섭 응낙 의무다.","c":"상","v":1},"공인노2022_31-48-4":{"w":"공무원노조법 제14조 제1항이 정한 공무원 노동관계 조정위원회 설치 근거다. 7명 이내의 공익위원으로 구성한다(같은 조 제2항).","c":"상","v":1},"공인노2022_31-48-5":{"w":"공무원노조법 제10조 제2항이 정한 성실 이행 노력 의무다. 시행령 제10조는 그 이행 결과를 협약 유효기간 만료 3개월 전까지 서면으로 알리도록 한다.","c":"상","v":1},"공인노2022_31-49-4":{"w":"교원노조법 제6조 제8항이 국민여론과 학부모 의견 수렴 의무를 정한다.","c":"상","v":1},"공인노2024_33-73-1":{"w":"교원노조법 제3조가 교원노조의 정치활동을 전면 금지한다.","c":"상","v":1},"공인노2024_33-73-2":{"w":"교원노조법 제5조 제1항(2022년 개정)에 따라 교원은 임용권자의 동의를 받아 노동조합으로부터 급여를 받으며 노조 업무에만 종사할 수 있다.","c":"상","v":1},"공인노2024_33-73-4":{"w":"교원노조법 제7조 제1항이 법령·조례·예산으로 규정되는 내용의 협약 효력을 부정한다.","c":"상","v":1},"공인노2024_33-73-5":{"w":"교원노조법 제5조 제4항이 정한 전임자 불이익 금지다.","c":"상","v":1},"공인노2024_33-74-1":{"w":"교원노조법 제5조의2 제2항이 교원근무시간면제심의위원회를 경제사회노동위원회에 두도록 정한다.","c":"상","v":1},"공인노2024_33-74-3":{"w":"교원노조법 제5조의2 제3항이 3년마다 적정성 재심의·의결을 할 수 있다고 정한다.","c":"상","v":1},"공인노2024_33-74-4":{"w":"교원노조법 제5조의2 제4항이 한도 초과 부분만 무효로 정한다.","c":"상","v":1},"공인노2024_33-74-5":{"w":"교원노조법 제5조의3과 시행령 제2조의6에 따라 임용권자는 매년 4월 30일까지 고용노동부장관이 지정하는 홈페이지에 3년간 게재하는 방법으로 공개한다.","c":"상","v":1},"공인노2024_33-75-2":{"w":"공무원노조법 제6조 제2항 제1호가 지휘·감독권 행사나 업무 총괄에 종사하는 공무원의 가입을 금지하고 구체적 범위는 대통령령으로 정한다(같은 조 제4항, 시행령 제3조).","c":"상","v":1},"공인노2024_33-76-2":{"w":"공무원노조법 제17조 제2항에 따라 노조법 제32조가 적용되므로 유효기간은 3년을 넘지 않는 범위에서 노사가 정한다.","c":"상","v":1},"공인노2024_33-76-3":{"w":"공무원노조법 제9조 제4항(2021년 개정)에 따라 정부교섭대표는 교섭 요구 노조가 둘 이상이면 창구 단일화를 요청할 수 있고 단일화되면 교섭에 응해야 한다.","c":"상","v":1},"공인노2024_33-76-4":{"w":"공무원노조법 제10조 제1항이 법령·조례로 위임받아 규정되는 내용의 협약 효력을 부정하고 제2항이 이행 노력 의무를 정한다.","c":"상","v":1},"공인노2024_33-76-5":{"w":"공무원노조법 제8조 제1항 단서가 정한 비교섭 사항이다.","c":"상","v":1},"공인노2024_33-77-4":{"w":"공무원노조법 제16조 제3항이 확정된 중재재정에 따르도록 하지만 같은 법 벌칙(제18조)은 쟁의행위 금지 위반만 처벌하고 노조법 제92조는 적용이 배제된다(제17조 제3항).","c":"상","v":1},"공인노2024_33-78-2":{"w":"공무원노조법 제17조 제3항의 적용 배제 목록에 노조법 제35조가 없으므로 공무원노조에도 일반적 구속력이 적용된다. 지역적 구속력(제36조)은 배제된다.","c":"상","v":1},"공인노2024_33-79-1":{"w":"교원노조법 제6조 제4항이 교섭하려는 사항에 권한을 가진 자에게 서면으로 교섭을 요구하도록 정한다.","c":"상","v":1},"공인노2024_33-79-2":{"w":"교원노조법 제6조 제1항 제1호가 유·초·중등 교원노조 대표자의 교섭 상대방을 교육부장관, 시·도 교육감, 사립학교 설립·경영자로 정한다.","c":"상","v":1},"공인노2024_33-79-3":{"w":"교원노조법 시행령 제3조의2 제2항이 교섭위원 수를 조직 규모 등을 고려해 10명 이내로 정한다.","c":"상","v":1},"공인노2024_33-79-4":{"w":"교원노조법 제6조 제2항이 교섭위원을 노조 대표자와 그 조합원으로 구성하도록 정한다.","c":"상","v":1},"공인노2024_33-80-1":{"w":"교원노조법 제10조 제2호가 조정안을 한쪽이라도 거부하면 중재를 하도록 정한다. 노조법 제63조(중재 시 쟁의행위 금지기간)는 적용이 배제되고(제14조 제2항) 교원노조법에도 중재기간 규정은 없다.","c":"상","v":1},"공인노2025_34-77-1":{"w":"공무원노조법 제10조 제1항이 법령·조례·예산으로 규정되는 내용의 단체협약 효력을 부정한다.","c":"상","v":1},"공인노2025_34-77-2":{"w":"공무원노조법 제10조 제1항이 조례에 의해 위임받아 규정되는 내용도 협약 효력이 없다고 정한다.","c":"상","v":1},"공인노2025_34-77-3":{"w":"공무원노조법 제11조가 정한 쟁의행위 금지다. 위반하면 제18조로 5년 이하 징역 또는 5천만원 이하 벌금이다.","c":"상","v":1},"공인노2025_34-77-5":{"w":"공무원노조법 제12조 제4항에 따라 조정은 신청받은 날부터 30일 이내에 마쳐야 하고 합의하면 30일 이내에서 연장할 수 있다.","c":"상","v":1},"공인노2025_34-78-1":{"w":"교원노조법 제2조 제1호가 유아교육법 제20조 제1항의 교원을 포함한다.","c":"상","v":1},"공인노2025_34-78-2":{"w":"교원노조법 제2조 제2호가 초·중등교육법 제19조 제1항의 교원을 포함한다.","c":"상","v":1},"공인노2025_34-78-3":{"w":"교원노조법 제2조 제3호가 고등교육법 제14조 제2항·제4항의 교원을 포함하되 강사는 제외한다.","c":"상","v":1},"공인노2025_34-78-4":{"w":"교원노조법 제3조는 교원노조의 정치활동을 어떠한 것도 허용하지 않는다.","c":"상","v":1},"공인노2025_34-79-1":{"w":"교원노조법 제15조 제1항에 따라 제8조(쟁의행위 금지)를 위반한 자는 5년 이하 징역 또는 5천만원 이하 벌금에 처한다.","c":"상","v":1},"공인노2025_34-80-2":{"w":"공무원노조법 제7조 제2항이 전임자에게 그 기간 중 국가공무원법 제71조 또는 지방공무원법 제63조에 따른 휴직명령을 하도록 정한다.","c":"상","v":1},"공인노2026_35-74-4":{"w":"공무원노조법 제17조 제3항이 노조법 제88조~제92조의 적용을 배제하므로 단체교섭 거부(노조법 제81조 제1항 제3호)에 대한 제90조 처벌이 공무원노조 관계에는 적용되지 않는다.","c":"상","v":1},"공인노2026_35-75-4":{"w":"공무원노조법 제17조 제2항에 따라 노조법 제68조 제2항의 「중재위원회」를 「공무원 노동관계 조정위원회」로 읽으므로 중재재정 해석은 그 위원회의 해석에 따른다.","c":"상","v":1},"공인노2026_35-76-1":{"w":"공무원노조법 제8조 제3항이 정한 공동교섭과 권한 위임이다.","c":"상","v":1},"공인노2026_35-76-2":{"w":"공무원노조법 제17조 제2항에 따라 노조법 제31조 제3항이 적용되고 「행정관청」은 고용노동부장관으로 읽는다.","c":"상","v":1},"공인노2026_35-76-3":{"w":"노조법 제35조의 일반적 구속력이다. 공무원노조법 제17조 제3항은 이 조항의 적용을 배제하지 않는다.","c":"상","v":1},"공인노2026_35-76-4":{"w":"공무원노조법 제9조 제4항 전단이 정한 교섭창구 단일화 요청이다.","c":"상","v":1},"공인노2026_35-77-1":{"w":"교원노조법 제6조 제2항에 따라 교섭위원은 해당 노동조합의 대표자와 그 조합원으로만 구성한다.","c":"상","v":1},"공인노2026_35-77-3":{"w":"교원노조법 제7조 제1항이 법령·조례·예산으로 규정되는 내용과 법령·조례의 위임으로 규정되는 내용의 단체협약 효력을 부정한다.","c":"상","v":1},"공인노2026_35-77-4":{"w":"교원노조법 제14조 제1항에 따라 노조법 제31조 제2항이 적용되고 행정관청은 고용노동부장관으로 읽는다.","c":"상","v":1},"공인노2026_35-77-5":{"w":"교원노조법 제14조 제1항에 따라 노조법 제32조 제1항이 적용된다.","c":"상","v":1},"공인노2026_35-78-1":{"w":"교원노조법 제14조 제1항은 노조법 제24조의2 제5항의 「경영자단체」를 「교육부장관」으로 읽으므로 사용자 대표 위원은 교육부장관이 추천하는 사람이다.","c":"상","v":1},"공인노2026_35-79-1":{"w":"교원노조법 제9조 제3항이 정한 30일 조정기간이다. 공무원노조법과 달리 연장 규정이 없다.","c":"상","v":1},"공인노2026_35-79-2":{"w":"교원노조법 제11조 제1항이 교원의 노동쟁의 조정·중재를 위해 중앙노동위원회에 교원 노동관계 조정위원회를 두도록 정한다. 조정담당 공익위원 3명으로 구성한다(같은 조 제2항).","c":"상","v":1},"공인노2026_35-79-3":{"w":"교원노조법 시행령 제6조 제2항에 따라 중앙노동위원회는 신청 내용이 조정·중재 대상이 아니라고 보면 신청인에게 그 사유와 다른 해결방법을 알려주어야 한다.","c":"상","v":1},"공인노2026_35-79-5":{"w":"교원노조법 시행령 제6조 제3항이 조정·중재를 하게 되면 지체 없이 서면으로 당사자에게 알리고 교원 노동관계 조정위원회를 구성하도록 정한다.","c":"상","v":1},"공인노2017_26-27-1":{"w":"1948년 제헌헌법 제17조가 근로조건의 기준을 법률로 정하도록 했다. 현행 헌법 제32조 제3항도 근로조건 기준을 인간의 존엄성을 보장하도록 법률로 정한다고 규정한다.","c":"중","v":1},"공인노2017_26-27-2":{"w":"1948년 제헌헌법 제17조가 여자와 소년의 근로에 대한 특별한 보호를 규정했다. 현행 헌법은 여자(제32조 제4항)와 연소자(제32조 제5항)로 나누어 정한다.","c":"중","v":1},"공인노2017_26-27-4":{"w":"1948년 제헌헌법 제18조가 근로자의 단결·단체교섭·단체행동의 자유를 법률의 범위 내에서 보장했다.","c":"중","v":1},"공인노2017_26-27-5":{"w":"1948년 제헌헌법 제18조가 사기업 근로자의 이익분배균점권을 규정했고 이 조항은 1962년 개정 헌법에서 삭제되었다.","c":"중","v":1},"공인노2019_28-27-1":{"w":"헌법 제37조 제2항의 일반적 법률유보에 따라 노동3권도 국가안전보장·질서유지·공공복리를 위해 필요한 경우 법률로 제한할 수 있다. 본질적 내용은 침해할 수 없다.","c":"상","v":1},"공인노2019_28-27-2":{"w":"헌법재판소는 헌법 제33조 제1항의 단결권은 단결할 자유만 뜻하고 단결하지 않을 자유(소극적 단결권)는 헌법 제10조의 일반적 행동자유권이나 제21조의 결사의 자유에서 근거를 찾는다고 본다.","c":"중","v":1},"공인노2019_28-27-3":{"w":"헌법 제33조 제2항에 따라 공무원인 근로자는 법률이 정하는 자에 한해 노동3권을 가진다. 이를 구체화한 법률이 공무원노조법과 교원노조법이다.","c":"상","v":1},"공인노2019_28-27-4":{"w":"헌법재판소는 노동3권이 국가 간섭을 배제하는 자유권이면서 국가의 적극적 보호를 요하는 성격을 함께 가진 「사회적 보호기능을 담당하는 자유권」 또는 「사회권적 성격을 띤 자유권」이라고 본다.","c":"중","v":1},"공인노2022_31-26-1":{"w":"헌법재판소가 노동3권의 성격을 사회적 보호기능을 담당하는 자유권 또는 사회권적 성격을 띤 자유권으로 설명한 결정이 있다.","c":"중","v":1},"공인노2022_31-26-2":{"w":"헌법 제33조 제1항이 근로조건 향상을 위한 자주적인 단결권·단체교섭권·단체행동권을 보장한다.","c":"상","v":1},"공인노2022_31-26-3":{"w":"헌법재판소는 유니언 숍 협정 사건에서 노동조합의 적극적 단결권이 근로자 개인의 단결하지 않을 자유보다 중시되고 노조에 조직강제권을 주어도 단결하지 않을 자유의 본질적 내용을 침해한다고 단정할 수 없다고 보았다.","c":"중","v":1},"공인노2022_31-26-4":{"w":"헌법재판소는 헌법 제33조 제1항의 단결권에 소극적 단결권은 포함되지 않고 그것은 일반적 행동자유권이나 결사의 자유에서 근거를 찾는다고 본다.","c":"중","v":1},"공인노2024_33-41-2":{"w":"1953년 제정 노동쟁의조정법은 사용자가 쟁의행위로 손해를 입어도 노동조합이나 근로자에게 배상을 청구할 수 없다는 민사면책 규정을 두었다.","c":"중","v":1},"공인노2024_33-41-3":{"w":"1963년 개정 노동조합법이 노동조합의 정치활동 금지 규정을 신설했고 이 규정은 1997년 노조법 제정 때 폐지되었다.","c":"중","v":1},"공인노2024_33-41-4":{"w":"1997년 3월 노동조합법과 노동쟁의조정법을 통합해 노동조합 및 노동관계조정법이 제정되었다.","c":"중","v":1},"공인노2024_33-41-5":{"w":"2010.1.1 개정 노조법이 복수노조 허용과 함께 교섭창구 단일화 절차(제29조의2 등)를 신설했고 2011.7.1부터 시행되었다.","c":"중","v":1},"공인노2024_33-42-1":{"w":"대법원 판례는 노동3권이 근로조건 향상이라는 생존권의 목적을 위한 것이므로 그중 단체교섭권이 가장 중핵적 권리이고 단결권과 단체행동권은 이를 위한 수단이라고 본다.","c":"중","v":1},"공인노2024_33-42-2":{"w":"헌법재판소는 노동3권의 사회권적 성격이 입법조치로 근로자의 헌법적 권리를 보장할 국가의 의무에서 드러난다고 본다.","c":"중","v":1},"공인노2024_33-42-4":{"w":"헌법 제33조 제3항에 따라 주요방위산업체 근로자의 단체행동권은 법률로 제한하거나 인정하지 않을 수 있고 노조법 제41조 제2항이 이를 구체화한다.","c":"상","v":1},"공인노2024_33-42-5":{"w":"다른 노동조합의 단체교섭권을 사전에 배제하는 유일교섭단체조항은 헌법 제33조 제1항이 모든 근로자에게 보장한 단체교섭권의 본질적 내용을 침해할 우려가 있어 효력이 부정된다는 것이 판례와 행정해석의 입장이다.","c":"중","v":1},"공인노2025_34-41-1":{"w":"헌법재판소는 단결권에 단결하지 않을 자유가 포함되지 않는다고 본다. 소극적 단결권은 일반적 행동자유권이나 결사의 자유로 보호된다.","c":"중","v":1},"공인노2025_34-41-2":{"w":"헌법 제37조 제2항에 따라 노동3권도 국가안전보장·질서유지·공공복리를 위해 필요한 경우 법률로 제한할 수 있다.","c":"상","v":1},"공인노2025_34-41-4":{"w":"헌법재판소는 노동3권을 사회적 보호기능을 담당하는 자유권 또는 사회권적 성격을 띤 자유권으로 본다.","c":"중","v":1},"공인노2025_34-41-5":{"w":"헌법 제33조 제2항에 따라 공무원인 근로자는 법률이 정하는 자에 한해 노동3권을 가진다.","c":"상","v":1},"공인노2026_35-80-1":{"w":"헌법재판소는 노동3권이 제대로 보장되려면 근로자의 권리행사의 실질적 조건을 형성·유지하는 국가의 적극적 활동, 곧 입법조치가 필요하다고 본다. 노동3권의 사회권적 성격에서 나오는 결론이다.","c":"중","v":1},"공인노2026_35-80-2":{"w":"헌법재판소는 헌법에 단체협약체결권이 명시되어 있지 않아도 근로조건 향상을 위한 단체교섭권에 단체협약체결권이 포함된다고 본다. 협약을 맺을 수 없는 교섭은 의미가 없기 때문이다.","c":"중","v":1},"공인노2026_35-80-4":{"w":"헌법재판소는 노동3권을 사회적 보호기능을 담당하는 자유권으로 본다.","c":"중","v":1},"공인노2026_35-80-5":{"w":"헌법재판소는 단결권이 결사의 자유가 근로 영역에서 구체화된 것으로 연혁적·개념적으로 자유권의 본질을 가진다고 본다.","c":"중","v":1},"공인노2017_26-41-1":{"old":1,"ow":"출제 당시 정답 O. 2021년 개정(2021.7.6 시행)으로 근로시간면제심의위원회는 고용노동부가 아니라 경제사회노동위원회에 두므로 틀린 문장이다(노동조합법 제24조의2제1항)."},"공인노2019_28-31-1":{"old":1,"ow":"출제 당시 정답 O. 2021년 개정(2021.7.6 시행)으로 근로시간면제심의위원회는 고용노동부가 아니라 경제사회노동위원회에 두므로 틀린 문장이다(노동조합법 제24조의2제1항)."},"공인노2017_26-41-5":{"old":1,"ow":"출제 당시 정답 O. 전임자 급여 지급을 요구하며 하는 쟁의행위를 금지한 옛 제24조제5항이 2021년 개정(2021.7.6 시행)으로 삭제되어 지금 법에는 이 금지 규정이 없으므로 틀린 문장이다(노동조합법 제24조)."},"공인노2019_28-31-5":{"old":1,"ow":"출제 당시 정답 O. 근로시간 면제 한도를 넘는 급여 지급을 요구하며 하는 쟁의행위를 금지한 옛 제24조제5항이 2021년 개정(2021.7.6 시행)으로 삭제되었다. 지금은 한도를 넘는 단체협약이나 사용자 동의가 그 부분만 무효일 뿐 쟁의행위 금지 규정은 없으므로 틀린 문장이다(노동조합법 제24조제4항)."},"공인노2024_33-44-5":{"old":1,"ow":"출제 당시 정답 O(구 노조법 제2조 제4호 라목·제12조 제3항 제1호). 2025.9.9 개정(2026.3.10 시행)으로 제2조 제4호 라목 「근로자가 아닌 자의 가입을 허용하는 경우」가 삭제되어 지금은 이를 이유로 설립신고서를 반려하지 않는다. 반려사유는 제2조 제4호 가·나·다·마목과 보완 불이행만 남았다(제12조 제3항)."},"공인노2019_28-50-2":{"old":1,"ow":"출제 당시 정답 O(구 공무원노조법 제9조 제4항 후단 「교섭창구가 단일화될 때까지 교섭을 거부할 수 있다」). 2021.1.5 개정(2021.7.6 시행)으로 후단이 「교섭창구가 단일화된 때에는 교섭에 응하여야 한다」로 바뀌어 지금은 교섭 거부권을 명시한 조문이 없다(현행 제9조 제4항)."},"공인노2019_28-50-4":{"old":1,"ow":"출제 당시 정답 O(구 공무원노조법 제7조 제3항). 2022.6.10 개정(2023.12.11 시행)으로 제7조 제3항이 삭제되고 근무시간 면제 제도(제7조의2)가 생겨 지금은 전임자 보수 지급 금지 조문이 없다. 전임자는 노동조합으로부터 급여를 받고 휴직명령을 받는다(제7조 제1항·제2항)."}};
